window.LICEY_DATA = {"art": [{"id": "a0", "title": "Как смотреть на искусство", "period": "Азбука", "intro": [], "traits": ["Жанры: портрет, пейзаж, натюрморт, историческая, бытовая и религиозная живопись", "Виды: живопись, графика, скульптура, архитектура", "Техники: фреска, темпера, масло, акварель, мозаика", "Перспектива — приём, создающий иллюзию глубины на плоскости", "Светотень (кьяроскуро) — лепка объёма светом и тенью"], "works": [], "quiz": [{"q": "Как называется жанр живописи, где изображена природа?", "o": ["Натюрморт", "Пейзаж", "Портрет", "Марина"], "a": 1, "e": "Пейзаж — изображение природы. Марина — его разновидность: морской пейзаж."}, {"q": "Что такое натюрморт?", "o": ["Изображение неживых предметов: цветов, посуды, фруктов", "Портрет умершего человека", "Картина на мифологический сюжет", "Роспись по сырой штукатурке"], "a": 0, "e": "Nature morte по-французски — «мёртвая природа»: композиция из предметов."}, {"q": "Роспись по сырой штукатурке называется…", "o": ["Темпера", "Мозаика", "Фреска", "Гравюра"], "a": 2, "e": "Fresco — «свежий»: краски впитываются в сырую штукатурку и живут веками."}, {"q": "Приём, который создаёт иллюзию глубины на плоской картине:", "o": ["Перспектива", "Контраст", "Орнамент", "Колорит"], "a": 0, "e": "Линейная перспектива: параллельные линии сходятся в точке на горизонте."}], "why": ["Экскурсоводы, путеводители и подписи в музеях говорят на своём языке: жанр, фреска, темпера, перспектива. Здесь собраны главные термины, каждый с примером. Разберитесь с ними один раз, и любая картина дальше будет читаться легче."], "groups": [{"h": "Какое бывает искусство", "p": "Сначала главное деление: картина, рисунок, статуя или здание. Это виды изобразительного искусства.", "items": [{"t": "Живопись", "d": "Изображение красками на холсте, доске или стене.", "c": "Леонардо да Винчи. «Мона Лиза»", "more": ["Леонардо да Винчи писал «Мону Лизу» больше десяти лет, начиная примерно с 1503 года, и так и не отдал её заказчику. Скорее всего, на портрете Лиза Герардини, жена флорентийского торговца шёлком.", "Сила живописи в цвете и свете. Посмотрите на лицо: контуры будто растворены в дымке, поэтому выражение кажется то печальным, то улыбающимся. Леонардо добивался этого десятками тончайших полупрозрачных слоёв краски. Этот приём называют сфумато, о нём будет в главе про Возрождение.", "В 1911 году картину украли из Лувра, и два года её искала полиция всего мира. Именно после этой истории «Мона Лиза» стала самой известной картиной на свете."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Графика", "d": "Рисунок и печатная гравюра: карандаш, тушь, уголь.", "c": "Дюрер. «Носорог», гравюра. Он рисовал по описанию, ни разу не видев зверя", "more": ["В 1515 году в Лиссабон привезли из Индии живого носорога, первого в Европе за тысячу лет. Немецкий художник Альбрехт Дюрер его ни разу не видел. Он сделал изображение по чужому письму и наброску, поэтому у зверя панцирь, похожий на рыцарские латы, и лишний рожок на спине.", "Это гравюра. Рисунок вырезают на деревянной доске, покрывают краской и печатают на бумаге, как штампом. С одной доски можно сделать сотни оттисков. Поэтому «Носорог» разошёлся по всей Европе, и почти двести лет даже в учебниках зоологии носорогов рисовали именно так."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer,_The_Rhinoceros,_1515,_NGA_47903.jpg", "lic": "CC0", "by": "Albrecht Dürer", "src": "media/img/b96612112b-1000.webp", "w": 1000, "h": 785, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg/1280px-Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Скульптура", "d": "Объёмная фигура из камня, бронзы, дерева или глины.", "c": "Венера Милосская, Древняя Греция", "more": ["Статую нашёл крестьянин в 1820 году на греческом острове Милос, отсюда название. Её создали около 130 года до нашей эры. Это богиня любви Афродита, римляне называли её Венерой.", "Руки были утрачены ещё до находки. Как она их держала, спорят до сих пор: возможно, в руке было яблоко. В отличие от картины, скульптуру обходят по кругу, и с каждой стороны она выглядит по-новому. Скульптор продумывает все точки зрения сразу. Сейчас Венера стоит в Лувре."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Архитектура", "d": "Искусство проектировать и строить здания.", "c": "Парфенон в Афинах", "more": ["Парфенон построили в Афинах с 447 по 432 год до нашей эры как храм богини Афины, покровительницы города. Внутри стояла её статуя высотой около 12 метров, покрытая золотом и слоновой костью.", "В нём почти нет прямых линий. Колонны слегка наклонены внутрь и чуть утолщены посередине, а основание немного выгнуто вверх. Дело в том, что издалека идеально прямые линии кажутся провисшими. Греческие архитекторы рассчитали этот обман зрения и исправили его заранее.", "В 1687 году во время войны с венецианцами турки хранили в храме порох. Снаряд попал внутрь, порох взорвался, и Парфенон остался без крыши."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Что изображают: жанры", "p": "Жанр отвечает на вопрос «что изображено?».", "items": [{"t": "Портрет", "d": "Изображение конкретного человека.", "c": "Вермеер. «Девушка с жемчужной серёжкой»", "more": ["Ян Вермеер жил в голландском городе Делфт в XVII веке и написал всего около 35 картин. Девушка на этой картине, скорее всего, не заказчица. Голландцы называли такие работы «тронье»: этюд головы в необычном костюме, чтобы показать характер и мастерство.", "Посмотрите на свет: блики на губах и в глазах, а жемчужина нарисована всего двумя мазками. Сверху яркий блик, снизу отражение белого воротника. Синюю краску для тюрбана делали из толчёного лазурита, камня, который возили из Афганистана. Она стоила дороже золота."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Пейзаж", "d": "Изображение природы.", "c": "Констебл. «Телега для сена»", "more": ["Джон Констебл всю жизнь писал одни и те же места: деревни на реке Стур в Англии, где он вырос. На картине 1821 года телега переезжает реку вброд. Так делали специально, чтобы деревянные колёса намокли и не рассыхались, а лошади заодно напились.", "В то время пейзаж считали второсортным жанром, гораздо выше ценились исторические и библейские сюжеты. Констебл доказывал, что обычная природа достойна большого холста. В Англии картину не купили, а на выставке в Париже в 1824 году она получила золотую медаль и вдохновила французских художников, будущих импрессионистов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:John_Constable_-_The_Hay_Wain_(1821).jpg", "lic": "Public domain", "by": "John Constable", "src": "media/img/8ec3e1f802-1000.webp", "w": 1000, "h": 690, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/John_Constable_-_The_Hay_Wain_%281821%29.jpg/1280px-John_Constable_-_The_Hay_Wain_%281821%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Марина", "d": "Морской пейзаж.", "c": "Айвазовский. «Девятый вал»", "more": ["Слово «марина» происходит от латинского mare, «море». Морские пейзажи особенно любили в странах, которые жили мореплаванием и торговлей: в Голландии, Англии, позже в России.", "Иван Айвазовский написал около шести тысяч картин, почти все о море. При этом с натуры он море не писал: наблюдал, запоминал и работал по памяти в мастерской. Он говорил, что движение стихий нельзя поймать кистью с натуры, его можно только запомнить. История «Девятого вала» ниже, в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Hovhannes Aivazovsky (1817 - 1900) – painter (Russian) Born in Rossiiskaya imper", "src": "media/img/14baff2254-1000.webp", "w": 1000, "h": 672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg/1280px-Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Натюрморт", "d": "Композиция из предметов: посуда, еда, цветы.", "c": "Хеда. «Завтрак»", "more": ["Виллем Хеда из голландского Харлема писал «завтраки»: недоеденный пирог, опрокинутый бокал, лимон с наполовину снятой кожурой. Почти всё выдержано в серебристо-коричневых тонах.", "Для голландцев XVII века такие картины были с подтекстом. Недопитое вино, погасшая свеча, часы напоминали, что жизнь проходит быстро, а богатство не вечно. Заодно художник показывал мастерство: попробуйте нарисовать отражение окна в изогнутом стекле бокала."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg", "lic": "Public domain", "by": "Willem Claesz. Heda", "src": "media/img/a187280085-1000.webp", "w": 1000, "h": 744, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/d7/Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Бытовой жанр", "d": "Сцены повседневной жизни.", "c": "Брейгель. «Крестьянская свадьба»", "more": ["Питер Брейгель написал «Крестьянскую свадьбу» около 1567 года. Невесту найти несложно: она сидит под зелёной тканью, над её головой бумажная корона. А вот где жених, спорят до сих пор, его на картине явно не видно.", "До Брейгеля крестьян почти не делали главными героями. Он вместе с другом ходил на деревенские праздники, переодевшись крестьянином, и наблюдал. Двое мужчин несут миски с кашей на снятой с петель двери, мальчик в огромной шапке облизывает тарелку. Так выглядела настоящая жизнь Фландрии XVI века."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Pieter Bruegel the Elder", "src": "media/img/f9e9cbaf49-1000.webp", "w": 1000, "h": 691, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg/1280px-Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Историческая картина", "d": "Важные события прошлого: битвы, договоры, коронации.", "c": "Веласкес. «Сдача Бреды»: побеждённый отдаёт ключи от города", "more": ["В 1625 году испанская армия после долгой осады взяла голландский город Бреду. Через десять лет придворный художник Диего Веласкес написал момент сдачи. Голландский командир протягивает ключи от города, а испанский генерал Спинола не даёт ему встать на колени и дружески кладёт руку на плечо.", "Справа строй испанцев с длинными пиками, их так много, что картину иногда называют «Копья». Веласкес показал не торжество победителя, а уважение к побеждённому. Историческая картина считалась тогда самым почётным жанром: она учила зрителя примерами из прошлого."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Velazquez-The_Surrender_of_Breda.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/c2f87ed612-1000.webp", "w": 1000, "h": 825, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Velazquez-The_Surrender_of_Breda.jpg/1280px-Velazquez-The_Surrender_of_Breda.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Чем рисуют: техники", "p": "Техника отвечает на вопрос «чем и на чём?». От неё зависит, как произведение выглядит и сколько проживёт.", "items": [{"t": "Фреска", "d": "Роспись по сырой штукатурке.", "c": "Джотто. Фреска в часовне в Падуе, около 1305 года", "more": ["Слово «фреска» происходит от итальянского fresco, «свежий». Художник покрывает сырой штукатуркой ровно тот участок стены, который успеет расписать за день. Краска впитывается и, высыхая, становится частью стены. Исправить ошибку можно, только сбив штукатурку и начав заново.", "Около 1305 года Джотто расписал часовню Скровеньи в Падуе: почти сорок сцен из жизни Христа и Марии. На этой фреске ученики оплакивают Христа. Люди склоняются над телом, ангелы в небе рыдают, а две фигуры сидят к нам спиной. Так живо и по-человечески горе до Джотто не изображали. С него начинается путь к Возрождению."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Мозаика", "d": "Изображение из кусочков стекла и камня.", "c": "Императрица Феодора. Равенна, VI век", "more": ["Мозаику набирают из маленьких кубиков цветного стекла, которые называют смальтой. Для золотого фона внутрь стеклянного кубика запаивали тонкую золотую фольгу. Кубики ставили под разным наклоном, чтобы они по-разному ловили свет, и стены мерцали при свечах.", "Эта мозаика в церкви Сан-Витале в итальянском городе Равенна сделана около 547 года. Византийская императрица Феодора несёт в храм золотую чашу. Византийцы любили мозаику ещё и потому, что она не выцветает: этим цветам почти полторы тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mosaic_of_Theodora_-_Basilica_San_Vitale_(Ravenna).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/b7c048832f-1000.webp", "w": 1000, "h": 592, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg/1280px-Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Темпера", "d": "Краски на яичном желтке. Ими писали иконы.", "c": "Андрей Рублёв. «Троица»", "more": ["Художник растирал цветной порошок и смешивал его с яичным желтком и водой. Такая краска сохнет за минуты, поэтому писали тонкими слоями, один поверх другого. Основой служила деревянная доска, покрытая белым левкасом, это смесь мела и клея.", "Андрей Рублёв написал «Троицу» в начале XV века для Троице-Сергиева монастыря. На ней три ангела, которые пришли в гости к Аврааму, и одновременно образ Бога в трёх лицах. Фигуры вписаны в круг, без начала и конца: так Рублёв показал согласие и единство. Сейчас икона хранится в Третьяковской галерее."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Масло", "d": "Краски на растительном масле.", "c": "Ван Эйк. В зеркале на стене видна вся комната", "more": ["Масляные краски сохнут медленно, по нескольку дней. Их можно смешивать прямо на картине, накладывать прозрачные слои один на другой и писать мельчайшие детали. Нидерландские художники XV века довели эту технику до совершенства, и потом она распространилась по всей Европе.", "Посмотрите на выпуклое зеркало на стене этого портрета 1434 года. В нём отражается вся комната со спины и ещё двое людей в дверях. Один из них, вероятно, сам художник. Над зеркалом надпись на латыни: «Ян ван Эйк был здесь». Такую точность до масляных красок получить было невозможно."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Акварель", "d": "Прозрачные краски на воде, по бумаге.", "c": "Дюрер. «Заяц»", "more": ["Акварель разводят водой, и сквозь слой краски просвечивает бумага. Поэтому белого цвета в акварели обычно нет: белым остаётся сама бумага. Ошибку почти невозможно исправить, работать нужно быстро и точно.", "Дюрер нарисовал «Зайца» в 1502 году. Шерсть сделана тысячами тонких мазков, а в глазу зайца отражается окно мастерской. Рисунок очень хрупкий: его хранят в Вене и показывают публике редко, чтобы краски не выцвели на свету."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_Hare,_1502_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Albrecht Dürer", "src": "media/img/81fb234d1c-1000.webp", "w": 1000, "h": 1105, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg/1280px-Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как художник обманывает глаз: приёмы", "p": "Картина плоская, но мы видим в ней глубину и объём. Этого добиваются особыми приёмами.", "items": [{"t": "Перспектива", "d": "Иллюзия глубины: дальнее меньше, линии сходятся в одну точку.", "c": "Перуджино. Плиты площади ведут взгляд к храму", "more": ["Линейную перспективу придумали во Флоренции около 1420 года. Архитектор Филиппо Брунеллески показал, что все параллельные линии, которые уходят вдаль, на картине должны сходиться в одной точке на горизонте. С тех пор художники строят пространство почти по законам геометрии.", "Перуджино расписал эту стену Сикстинской капеллы в Риме в 1482 году. Плиты площади нарисованы как расчерченная сетка, и все её линии сходятся к двери храма в центре. Наш взгляд сам идёт туда. Фигуры вдали становятся меньше, и плоская стена превращается в огромную площадь."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg", "lic": "Public domain", "by": "Pietro Perugino", "src": "media/img/d566659d89-1000.webp", "w": 1000, "h": 619, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Светотень", "d": "Объём через контраст света и тени.", "c": "Караваджо. Лица и руки выступают из темноты", "more": ["Итальянцы называли этот приём кьяроскуро, буквально «светло-тёмное». Резкий переход от света к тени делает предметы объёмными, как будто их можно потрогать. Художник Караваджо довёл приём до предела: фон у него почти чёрный, а свет падает узким лучом, как от прожектора.", "На картине 1601 года двое учеников ужинают со случайным странником и вдруг узнают в нём воскресшего Христа. Один вскакивает со стула, другой раскидывает руки. Свет выхватывает лица и руки, и кажется, что персонажи вот-вот выйдут из картины к нам. Корзина с фруктами стоит на самом краю стола и, кажется, сейчас упадёт."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1602-3_Caravaggio,Supper_at_Emmaus_National_Gallery,_London.jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/30559d6da5-1000.webp", "w": 1000, "h": 711, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg/1280px-1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a1", "title": "Первобытность и Древний Египет", "period": "40 000 лет до н. э. — IV век до н. э.", "intro": [], "traits": ["Наскальная живопись: охра, уголь, звери в движении", "Египетский канон: голова в профиль, плечи анфас", "Размер фигуры = её важность", "Монументальность: пирамиды, сфинкс, храмы", "Искусство служит культу мёртвых и вечности"], "works": [{"t": "Росписи пещеры Ласко", "a": "Неизвестные мастера (Франция)", "y": "около 17 000 лет до н. э.", "d": "Сотни быков, лошадей и оленей, нарисованных углём и глиной. Пещеру нашли подростки в 1940 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["В 1940 году четверо подростков во Франции искали подземный ход и случайно провалились в пещеру. На стенах они увидели сотни нарисованных зверей: быков, лошадей, оленей. Рисункам около 17 000 лет.", "Художники работали в полной темноте, при свете каменных ламп с животным жиром. Краски делали из красной и жёлтой глины и угля. Часть краски выдували через полую косточку, как из баллончика.", "После открытия в пещеру пошли тысячи туристов. От их дыхания на стенах начала расти плесень, и рисунки стали портиться. В 1963 году пещеру закрыли. Сейчас посетители смотрят точную копию, построенную рядом."]}, {"t": "Бюст Нефертити", "a": "Скульптор Тутмос", "y": "около 1345 г. до н. э.", "d": "Жена фараона Эхнатона. Эпоха Эхнатона — редкий момент, когда египетский канон стал мягче и живее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nofretete_Neues_Museum.jpg", "lic": "CC BY-SA 3.0", "by": "Philip Pikart", "src": "media/img/e03c2fb10a-1000.webp", "w": 1000, "h": 1464, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Nofretete_Neues_Museum.jpg/1280px-Nofretete_Neues_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Нефертити была женой фараона Эхнатона. Бюст сделал скульптор Тутмос около 1345 года до нашей эры. Его нашли в 1912 году в развалинах мастерской Тутмоса.", "Скульптура сделана из известняка, покрыта тонким слоем гипса и раскрашена. Посмотрите на глаза: правый вставлен из горного хрусталя, а левый так и остался пустым. Почему, никто точно не знает. Может быть, это была учебная модель для других мастеров.", "Эхнатон хотел поклоняться одному богу, солнцу, и при нём искусство стало мягче и живее, чем обычно в Египте. Сейчас бюст хранится в Берлине."]}, {"t": "Пирамиды Гизы", "a": "Архитекторы фараонов IV династии", "y": "около 2500 г. до н. э.", "d": "Гробницы фараонов Хуфу, Хафра и Менкаура. Пирамида Хеопса — единственное сохранившееся из семи чудес света.", "img": {"page": "https://commons.wikimedia.org/wiki/File:All_Gizah_Pyramids.jpg", "lic": "CC BY-SA 2.0", "by": "Ricardo Liberato", "src": "media/img/dedccf333e-1000.webp", "w": 1000, "h": 665, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/All_Gizah_Pyramids.jpg/1280px-All_Gizah_Pyramids.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Три большие пирамиды построили для трёх фараонов: Хуфу (его ещё называют Хеопсом), его сына Хафра и внука Менкаура. Самая большая, пирамида Хуфу, появилась около 2560 года до нашей эры. Её строили примерно двадцать лет.", "Она сложена из двух миллионов каменных блоков. Каждый весит в среднем как два легковых автомобиля. Высота была 146 метров, почти как пятидесятиэтажный дом. Почти четыре тысячи лет это было самое высокое здание на Земле.", "Раньше думали, что пирамиды строили рабы. Но рядом нашли посёлок строителей с пекарнями и могилами. Оказалось, работали обычные египтяне за еду и плату. Камни тянули на санях по дорогам и насыпям, а песок поливали водой, чтобы сани легче скользили.", "Сначала пирамиды были облицованы гладким белым камнем и блестели на солнце. Потом облицовку разобрали на постройки, и стали видны ступеньки из блоков."]}, {"t": "Маска Тутанхамона", "a": "Египетские мастера", "y": "около 1323 г. до н. э.", "d": "Золото, лазурит, стекло. Маска закрывала лицо мумии юного фараона, гробницу которого нашли нетронутой в 1922 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:CairoEgMuseumTaaMaskMostlyPhotographed.jpg", "lic": "Public domain", "by": "Roland Unger", "src": "media/img/52271ee97b-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/CairoEgMuseumTaaMaskMostlyPhotographed.jpg/1280px-CairoEgMuseumTaaMaskMostlyPhotographed.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Тутанхамон стал фараоном в девять лет и умер примерно в девятнадцать. Великим правителем он не был, зато сегодня его знает весь мир.", "Его гробница была маленькой и спрятанной, поэтому грабители её не нашли. В 1922 году её открыл англичанин Говард Картер. Внутри было больше пяти тысяч вещей: колесницы, мебель, украшения, игры.", "Мумию положили в три гроба, вложенных друг в друга, как матрёшка. Два внешних деревянные, покрыты золотом, а самый маленький, внутренний, отлит из чистого золота. Маска была надета прямо на голову мумии внутри этого золотого гроба. Сама маска сделана из золота весом больше десяти килограммов и украшена синим камнем лазуритом и цветным стеклом. Египтяне верили, что золото не тускнеет, как и тело бога."]}], "quiz": [{"q": "Как изображали человека по египетскому канону?", "o": ["Полностью в профиль", "Голова и ноги в профиль, плечи анфас", "Полностью анфас", "Со спины"], "a": 1, "e": "Так каждая часть тела видна в самом «понятном» ракурсе."}, {"q": "Для чего в первую очередь служило искусство Египта?", "o": ["Для украшения жилищ", "Для обеспечения вечной жизни после смерти", "Для торговли", "Для развлечения"], "a": 1, "e": "Гробницы, статуи и росписи помогали душе жить в вечности."}, {"q": "Чем рисовали первобытные художники?", "o": ["Масляными красками", "Охрой и углём", "Акварелью", "Темперой на яйце"], "a": 1, "e": "Природные пигменты: охра (красная и жёлтая глина), уголь, мел."}], "why": ["Египтяне создали одну из первых в мире систем письма, первые огромные каменные постройки и правила рисования, которые не менялись почти три тысячи лет. Их сфинксов и обелиски потом повторяли повсюду, два настоящих египетских сфинкса стоят даже на набережной Невы в Петербурге. А пещерные рисунки показывают, что человек начал рисовать задолго до того, как научился писать."], "groups": [{"h": "Первые художники", "p": "Пещерные рисунки находят по всему миру. Краски делали из глины и угля.", "items": [{"t": "Пещера Ласко", "d": "Сотни зверей, около 17 000 лет назад.", "c": "Франция", "more": ["Около 17 000 лет назад охотники нарисовали в пещере на юге Франции около 600 животных и вырезали на стенах ещё полторы тысячи изображений. Работали при свете каменных светильников с животным жиром.", "Краски делали из охры, это красная и жёлтая глина, и из угля. Иногда краску выдували через полую кость прямо на стену. Зачем рисовали, точно неизвестно. Возможно, это были обряды перед охотой или рассказы о ней. Как пещеру нашли, читайте в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Пещера Шове", "d": "Около 36 000 лет. Объём за счёт выступов скалы.", "c": "Львы на охоте", "more": ["Пещеру Шове во Франции нашли в 1994 году. Её рисункам около 36 000 лет, вдвое больше, чем в Ласко. Здесь больше всего хищников: львы, медведи, шерстистые носороги.", "Художник выбирал выступы и выпуклости скалы, чтобы спина или голова зверя выглядели объёмными. Некоторые звери нарисованы с несколькими парами ног, словно бегут. Это похоже на первую в истории попытку показать движение."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lions_painting,_Chauvet_Cave_(museum_replica).jpg", "lic": "Public domain", "by": "HTO", "src": "media/img/1a1d14f43b-1000.webp", "w": 1000, "h": 854, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg/1280px-Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Первые статуэтки", "d": "Фигурки-обереги из камня и кости.", "c": "«Венера Виллендорфская», 11 см, около 25 000 лет", "more": ["Фигурку нашли в 1908 году в Австрии у деревни Виллендорф. Высота всего 11 сантиметров, она помещается в ладони. Её вырезали из известняка около 25 000 лет назад и раскрасили красной охрой.", "Лица у неё нет, голова покрыта как будто косами. Учёные считают, что это символ плодородия и благополучия, оберег, который носили с собой. Название «Венера» дали археологи в шутку, в честь римской богини красоты."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_of_Willendorf_frontview_retouched_2.jpg", "lic": "CC BY 2.5", "by": "User:MatthiasKabel", "src": "media/img/12389dba14-1000.webp", "w": 1000, "h": 1644, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Venus_of_Willendorf_frontview_retouched_2.jpg/1280px-Venus_of_Willendorf_frontview_retouched_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как узнать египетское искусство", "p": "Если видите эти признаки, перед вами почти наверняка Египет.", "items": [{"t": "Голова сбоку, плечи спереди", "d": "Главное правило египетского канона.", "c": "Небамун охотится на птиц. Роспись гробницы", "more": ["Небамун был писцом, который вёл учёт зерна в храме. Около 1350 года до нашей эры его гробницу расписали сценами счастливой жизни. Здесь он охотится на птиц в зарослях папируса вместе с женой и дочерью, а его кот ловит добычу.", "Египтяне рисовали не то, что видит глаз в одно мгновение, а то, как предмет устроен. Голова лучше узнаётся сбоку, глаз и плечи спереди, ноги сбоку. Фигура выглядит необычно, зато в ней есть всё. Египтяне верили, что изображение будет жить вместо человека в загробном мире, поэтому ни одна часть тела не должна была потеряться."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Tomb_of_Nebamun.jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/e75471c9b9-1000.webp", "w": 1000, "h": 852, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Tomb_of_Nebamun.jpg/1280px-Tomb_of_Nebamun.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Кто важнее, тот крупнее", "d": "Размер фигуры показывает её важность.", "c": "Палетка Нармера, около 5000 лет", "more": ["Каменная палетка сделана около 3100 года до нашей эры. Это одна из первых записей истории: царь Нармер объединил Верхний и Нижний Египет в одно государство.", "Нармер замахивается булавой на врага, он почти вдвое выше всех. За ним маленький слуга несёт его сандалии. Размер здесь показывает не расстояние, как в перспективе, а важность. Этот приём египтяне сохранили на три тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Narmer_palette_(obverse).jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/f78c1b74f9-1000.webp", "w": 1000, "h": 1446, "remote": "https://upload.wikimedia.org/wikipedia/commons/5/57/Narmer_palette_%28obverse%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Рисунки рядом с письменами", "d": "Иероглифы подписывают, кто изображён и что происходит.", "c": "«Книга мёртвых». Сердце умершего взвешивают на весах", "more": ["«Книга мёртвых» это свиток папируса с заклинаниями, который клали в гробницу. Он подсказывал умершему, как пройти через загробный мир. Этот свиток сделан для писца Хунефера около 1300 года до нашей эры.", "На картинке загробный суд. Слева бог с головой шакала Анубис ведёт Хунефера к весам. На одной чаше лежит сердце человека, на другой перо богини правды Маат. Египтяне верили, что в сердце хранится память обо всех поступках. Если сердце окажется тяжелее пера, человек жил нечестно, и его съест чудовище Амамат с головой крокодила, которое ждёт у весов.", "Бог мудрости Тот с головой птицы ибиса записывает результат. Сердце Хунефера оказалось лёгким, и справа его ведут к Осирису, владыке загробного мира. Иероглифы над фигурами это подписи и тексты молитв. В Египте изображение и письмо всегда шли рядом, ведь сами иероглифы тоже маленькие рисунки."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Book_of_the_Dead_of_Hunefer_sheet_3.jpg", "lic": "Public domain", "by": "Hunefer", "src": "media/img/62d67ae425-1000.webp", "w": 1000, "h": 457, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Book_of_the_Dead_of_Hunefer_sheet_3.jpg/1280px-Book_of_the_Dead_of_Hunefer_sheet_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Огромные каменные постройки", "d": "Пирамиды, храмы и сфинксы, рассчитанные на вечность.", "c": "Большой сфинкс в Гизе", "more": ["Большой сфинкс вырезан прямо в скале около 2500 года до нашей эры. Его длина 73 метра, высота 20. У него тело льва, символ силы, и голова фараона, скорее всего Хафры, чья пирамида стоит рядом.", "Тысячи лет сфинкса заносило песком по самую шею, и в древности его не раз откапывали. Нос отбит, когда и кем, точно неизвестно. Сфинкс сторожил дорогу к пирамидам. Его размеры должны были показать мощь фараона и вечность его власти."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Great_Sphinx_(%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/4acef234c4-1000.webp", "w": 1000, "h": 646, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg/1280px-Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a2", "title": "Античность: Греция и Рим", "period": "VIII век до н. э. — V век н. э.", "intro": [], "traits": ["Человек — мера всех вещей", "Идеальные пропорции и гармония", "Контрапост — живая поза с опорой на одну ногу", "Ордера в архитектуре: дорический, ионический, коринфский", "Рим: реалистичный портрет, арки, купола"], "works": [{"t": "Дискобол", "a": "Мирон (римская копия)", "y": "около 450 г. до н. э.", "d": "Атлет за миг до броска. Мирон «остановил» движение — для того времени смелый эксперимент.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG", "lic": "CC BY-SA 4.0", "by": "Livioandronico2013", "src": "media/img/7b0a35bc6a-1000.webp", "w": 1000, "h": 1672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG/1280px-Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Скульптор Мирон сделал эту статую около 450 года до нашей эры. Атлет на секунду замер перед броском диска: тело закручено, рука с диском отведена назад.", "Это смелый эксперимент. Мирон «остановил» быстрое движение, как фотограф, хотя фотографии не будет ещё две тысячи лет. При этом лицо атлета спокойно. Греки считали, что достойный человек сохраняет самообладание даже в самом напряжённом деле.", "Бронзовый оригинал утерян. До нас дошли только римские копии из мрамора, которые римляне массово заказывали для своих вилл."]}, {"t": "Венера Милосская", "a": "Предположительно Александрос Антиохийский", "y": "около 130 г. до н. э.", "d": "Эпоха эллинизма. Руки утрачены, но статуя стала символом женской красоты. Хранится в Лувре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Статую нашёл крестьянин в 1820 году на острове Милос. Французский моряк уговорил посла купить её, и вскоре она оказалась в Лувре.", "Это эпоха эллинизма, около 130 года до нашей эры. Посмотрите на позу: лёгкий изгиб тела, ткань соскальзывает с бёдер, голова повёрнута. Она спокойная, как классика, но мягче и живее.", "Руки утрачены. Как она их держала, неизвестно. Существует много версий: с яблоком, с зеркалом, со щитом. Возможно, именно эта загадка сделала статую такой знаменитой."]}, {"t": "Ника Самофракийская", "a": "Неизвестный скульптор", "y": "около 190 г. до н. э.", "d": "Богиня победы на носу корабля. Мрамор передаёт ветер и мокрую ткань — вершина эллинистической динамики.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nike_of_Samothrake_Louvre_Ma2369_n4.jpg", "lic": "Public domain", "by": "", "src": "media/img/53813a5b17-1000.webp", "w": 1000, "h": 1515, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Nike_of_Samothrake_Louvre_Ma2369_n4.jpg/1280px-Nike_of_Samothrake_Louvre_Ma2369_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Ника это богиня победы. Статую поставили на острове Самофракия около 190 года до нашей эры в честь победы в морском сражении. Она стояла на мраморном носу корабля, как будто только что опустилась на него с неба.", "Лица и рук нет, но фигура полна движения. Ветер прижимает мокрую ткань к телу, крылья развёрнуты назад. Скульптор передал в мраморе то, что почти невозможно передать в камне: воздух и ветер.", "Сейчас Ника стоит в Лувре наверху парадной лестницы, и зрители поднимаются к ней снизу, как когда-то моряки."]}, {"t": "Парфенон", "a": "Иктин и Калликрат, скульптор Фидий", "y": "447–438 гг. до н. э.", "d": "Храм Афины на Акрополе — эталон дорического ордера. Колонны чуть наклонены и утолщены, чтобы храм казался идеально ровным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Главный храм Афин построили на холме Акрополь с 447 по 432 год до нашей эры. Им руководил правитель Перикл, работали архитекторы Иктин и Калликрат, скульптурами занимался Фидий.", "Храм посвящён Афине-Деве, покровительнице города. На фронтонах и по всему периметру шли скульптуры: битвы богов, шествие афинян. Изначально всё было раскрашено яркими красками, белым мрамор стал только со временем.", "Колонны чуть наклонены и утолщены посередине, чтобы здание выглядело идеально ровным издалека. Это дорический ордер, самый строгий из трёх греческих ордеров. Часть скульптур Парфенона сейчас хранится в Британском музее, и Греция давно просит их вернуть."]}, {"t": "Колизей", "a": "Римские строители", "y": "72–80 гг. н. э.", "d": "Амфитеатр на 50 000 зрителей. Римская формула: арки, бетон и три греческих ордера на фасаде.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Colosseo_2020.jpg", "lic": "CC BY-SA 4.0", "by": "FeaturedPics", "src": "media/img/9059ffbfcd-1000.webp", "w": 1000, "h": 701, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Colosseo_2020.jpg/1280px-Colosseo_2020.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Колизей открыли в 80 году после 100 дней игр. Он вмещал около 50 000 зрителей. Здесь шли бои гладиаторов, травля зверей, казни и даже, по некоторым свидетельствам, морские сражения в залитой водой арене.", "Под ареной был целый подземный этаж с клетками и подъёмниками, звери появлялись прямо из-под песка. От солнца зрителей закрывал огромный тент, его натягивали моряки.", "Римляне построили Колизей из бетона и камня всего за десять лет. На фасаде три яруса арок, а на колоннах три греческих ордера один над другим. Так римляне соединили греческую красоту и свою инженерию."]}], "quiz": [{"q": "Что такое контрапост?", "o": ["Тип колонны", "Поза с опорой на одну ногу, создающая живое равновесие", "Техника литья бронзы", "Роспись вазы"], "a": 1, "e": "Контрапост оживил скульптуру и вернулся в эпоху Возрождения (вспомните «Давида» Микеланджело)."}, {"q": "Какой храм стоит на афинском Акрополе?", "o": ["Пантеон", "Колизей", "Парфенон", "Храм Артемиды"], "a": 2, "e": "Парфенон посвящён Афине-Деве. Пантеон — в Риме."}, {"q": "Что римляне добавили к греческому искусству?", "o": ["Иероглифы", "Правдивый портрет и арочные конструкции", "Иконопись", "Золотой фон"], "a": 1, "e": "Римский портрет честен: морщины, лысины, характер. А арки и бетон дали огромные пространства."}], "why": ["Греки первыми сделали главным героем искусства человека, его тело, ум и характер. Римляне взяли греческие идеи и добавили инженерную мощь: бетон, арки, купола. Колонны на фасадах театров, банков и музеев, статуи в парках, даже здание Капитолия в Вашингтоне выросли отсюда. Без античности не понять ни Возрождение, ни классицизм."], "groups": [{"h": "Как греки искали идеал", "p": "За триста лет греческая скульптура прошла путь от застывших фигур до бурного движения. Сравните три статуи по порядку.", "items": [{"t": "Архаика: фигура как столб", "d": "Ранние статуи стоят прямо, руки прижаты, на лице улыбка.", "c": "Курос из Анависоса, около 530 года до н. э.", "more": ["Такие статуи юношей называют куросами. Их ставили на могилах и в храмах. Видно влияние Египта: левая нога выставлена вперёд, тело неподвижно, руки опущены вдоль боков.", "Странная улыбка на лице не означает радость. Учёные называют её «архаической улыбкой». Скорее всего, так скульпторы пытались оживить лицо, ещё не умея передавать настоящие эмоции."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Kroisos_Kouros,_NAMA_3851.jpg", "lic": "CC BY-SA 4.0", "by": "Yair-haklai", "src": "media/img/971da50533-1000.webp", "w": 1000, "h": 2549, "remote": "https://upload.wikimedia.org/wikipedia/commons/2/24/Kroisos_Kouros%2C_NAMA_3851.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Классика: контрапост", "d": "Фигура опирается на одну ногу, и всё тело приходит в живое равновесие.", "c": "Поликлет. «Копьеносец», римская копия", "more": ["Около 440 года до нашей эры скульптор Поликлет написал трактат «Канон», где рассчитал идеальные пропорции тела. Например, голова должна составлять седьмую часть роста. Статую «Копьеносец» он сделал как наглядный пример этих правил.", "Посмотрите на ноги. Одна держит вес тела, другая расслаблена и отставлена назад. От этого бёдра наклоняются в одну сторону, а плечи в другую. Такую позу называют контрапостом. Фигура стоит спокойно, но кажется, что она может сделать шаг. Оригинал из бронзы не сохранился, до нас дошли римские копии в мраморе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Doryphoros_from_Pompeii_(Naples).jpg", "lic": "CC BY-SA 4.0", "by": "Yair-haklai", "src": "media/img/91444c7285-1000.webp", "w": 1000, "h": 2170, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Doryphoros_from_Pompeii_%28Naples%29.jpg/1280px-Doryphoros_from_Pompeii_%28Naples%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Эллинизм: драма и движение", "d": "Позднее искусство показывает страдание, борьбу, напряжение мышц.", "c": "«Лаокоон и сыновья», I век до н. э.", "more": ["По легенде, жрец Лаокоон предупреждал троянцев не вносить в город деревянного коня. Боги, которые хотели гибели Трои, послали змей, и те задушили Лаокоона и его сыновей.", "Скульпторы с острова Родос показали самый страшный момент. Тело выгнуто, мышцы напряжены, лицо искажено болью. Рядом со спокойным «Копьеносцем» разница огромная. Статую нашли в Риме в 1506 году, и на раскопки пришёл посмотреть Микеланджело. Она сильно повлияла на его собственные работы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Laocoon_and_His_Sons.jpg", "lic": "CC BY-SA 4.0", "by": "Hagesandros, Athenedoros, and Polydoros", "src": "media/img/ec294ecf62-1000.webp", "w": 1000, "h": 899, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Laocoon_and_His_Sons.jpg/1280px-Laocoon_and_His_Sons.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вазопись", "d": "Греки расписывали глиняные сосуды сценами из мифов.", "c": "Эксекий. Ахилл и Аякс играют в кости", "more": ["Греческие картины на досках почти все погибли, поэтому о греческой живописи мы знаем в основном по вазам. Мастер Эксекий около 530 года до нашей эры сам сделал этот сосуд и сам его расписал, о чём оставил подпись.", "Два героя Троянской войны во время передышки играют в кости. Оба в доспехах, щиты рядом. Над Ахиллом надпись «четыре», над Аяксом «три»: Ахилл выигрывает. Это чернофигурная техника: фигуры чёрным лаком по рыжей глине, детали процарапаны иглой."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Achilles_and_Ajax_playing_dice,_Attic_black-figured_amphora,_signed_by_Exekias_as_both_painter_and_potter,_540-530_BC,_inv._16757_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01049.jpg", "lic": "Public domain", "by": "Daderot", "src": "media/img/c381a33021-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Achilles_and_Ajax_playing_dice%2C_Attic_black-figured_amphora%2C_signed_by_Exekias_as_both_painter_and_potter%2C_540-530_BC%2C_inv._16757_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01049.jpg/1280px-thumbnail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Что придумали римляне", "p": "Римляне ценили практичность. Их главные открытия касаются строительства и правдивого портрета.", "items": [{"t": "Купол и бетон", "d": "Римляне изобрели прочный бетон и научились перекрывать огромные залы куполом.", "c": "Пантеон в Риме, около 125 года", "more": ["Пантеон был храмом всех богов. Его купол диаметром 43 метра почти две тысячи лет оставался самым большим в мире и до сих пор остаётся самым большим куполом из неармированного бетона.", "Наверху круглое отверстие диаметром 9 метров, через него в храм падает луч солнца и медленно движется по стенам в течение дня. Чтобы купол не рухнул под собственным весом, наверху римляне добавляли в бетон лёгкую вулканическую пемзу, а внизу тяжёлый камень."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pantheon_(Rome),_Dome_interior.jpg", "lic": "CC0", "by": "Wilfredor", "src": "media/img/5c11a0fa37-1000.webp", "w": 1000, "h": 856, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Pantheon_%28Rome%29%2C_Dome_interior.jpg/1280px-Pantheon_%28Rome%29%2C_Dome_interior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Арки и акведуки", "d": "Арка распределяет вес и позволяет строить высоко и надолго.", "c": "Акведук Пон-дю-Гар, Франция, I век", "more": ["Акведук это водопровод. По этому мосту вода шла в римский город Ним за 50 километров. Высота почти 50 метров, три яруса арок. Камни уложены без раствора, они держатся только за счёт точного веса и формы.", "Уклон канала наверху меньше 25 сантиметров на километр, такая точность поражает инженеров и сегодня. Римские арки, своды и купола потом станут основой архитектуры на две тысячи лет вперёд."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pont_du_Gard_BLS.jpg", "lic": "CC BY-SA 3.0", "by": "Benh LIEU SONG (Flickr)", "src": "media/img/185b2effbf-1000.webp", "w": 1000, "h": 386, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Pont_du_Gard_BLS.jpg/1280px-Pont_du_Gard_BLS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Правдивый портрет", "d": "Греки изображали идеал, римляне показывали человека таким, какой он есть.", "c": "Император Каракалла, около 215 года", "more": ["Римляне хранили дома восковые маски умерших предков, поэтому ценили точное сходство. Морщины, лысина, тяжёлый подбородок, всё изображали честно.", "Император Каракалла был жестоким правителем, и скульптор этого не скрыл. Голова резко повёрнута, брови сдвинуты, взгляд подозрительный. Сам император любил этот образ: он хотел, чтобы его боялись."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bust_Caracalla.jpg", "lic": "CC BY-SA 3.0", "by": "Herodotptlomeu (talk)", "src": "media/img/8af5a1df59-1000.webp", "w": 1000, "h": 750, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/41/Bust_Caracalla.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Римская живопись", "d": "Стены домов расписывали фресками, и многие сохранились под пеплом Везувия.", "c": "Вилла Мистерий, Помпеи, I век до н. э.", "more": ["В 79 году вулкан Везувий засыпал пеплом города Помпеи и Геркуланум. Пепел сохранил дома вместе с росписями, и благодаря этому мы видим, как выглядела римская живопись.", "В одном из залов виллы по всем стенам идёт непрерывная сцена: женщины проходят обряд посвящения в таинства бога Диониса. Насыщенный красный фон так и называют «помпейским красным»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Roman_fresco_Villa_dei_Misteri_Pompeii_005b.jpg", "lic": "Public domain", "by": "original files by WolfgangRieger", "src": "media/img/dcbb1b78d2-1000.webp", "w": 1000, "h": 1198, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3c/Roman_fresco_Villa_dei_Misteri_Pompeii_005b.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "a3", "title": "Средневековье: икона, романика, готика", "period": "V — XIV век", "intro": [], "traits": ["Золотой фон — символ божественного света", "Плоские фигуры, обратная перспектива", "Мозаика, икона, витраж, книжная миниатюра", "Готика: стрельчатые арки, витражи, устремлённость вверх", "Анонимность: мастер служит Богу, а не славе"], "works": [{"t": "Троица", "a": "Андрей Рублёв", "y": "1411 или 1425–1427", "d": "Три ангела у стола — образ Святой Троицы. Фигуры вписаны в круг — символ вечности и согласия. Главная русская икона, хранится в Третьяковской галерее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Андрей Рублёв был монахом и написал эту икону в начале XV века, около 1411 или 1425 года, для Троицкого собора в монастыре Сергия Радонежского.", "Сюжет взят из Библии: к старцу Аврааму пришли три странника, и он угощал их у дуба. Христиане увидели в них образ Бога в трёх лицах. Рублёв убрал всё лишнее: самого Авраама, его жену, слуг. Остались три ангела вокруг стола с чашей.", "Фигуры вписаны в круг, головы склонены друг к другу. Это образ любви и согласия. Нежные голубые, золотистые и зелёные цвета делают икону тихой и светлой. В 1551 году церковный собор постановил писать Троицу так, как писал Рублёв."]}, {"t": "Собор Парижской Богоматери", "a": "Строители-готы", "y": "1163–1345", "d": "Образец ранней готики: розы-витражи, контрфорсы, химеры. Собор вдохновил Гюго на роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Notre-Dame_de_Paris_2013-07-24.jpg", "lic": "CC BY-SA 3.0", "by": "P e z i", "src": "media/img/a720a76e0c-1000.webp", "w": 1000, "h": 1350, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Notre-Dame_de_Paris_2013-07-24.jpg/1280px-Notre-Dame_de_Paris_2013-07-24.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Строительство началось в 1163 году и продолжалось почти двести лет. Собор стоит на острове посреди Сены, в самом сердце Парижа.", "На фасаде три портала со скульптурами и огромная роза-витраж. Сзади видны аркбутаны, каменные опоры, которые держат стены снаружи. Знаменитые химеры на крыше появились позже, в XIX веке, их добавил архитектор Виолле-ле-Дюк при реставрации.", "После Французской революции собор обветшал и мог быть снесён. Его спас Виктор Гюго: в 1831 году он написал роман «Собор Парижской Богоматери», и Париж решил восстановить храм. В 2019 году собор сильно пострадал от пожара, рухнул шпиль. В декабре 2024 года его открыли после реставрации."]}, {"t": "Оплакивание Христа", "a": "Джотто ди Бондоне", "y": "около 1305", "d": "Фреска в капелле Скровеньи. Лица полны горя, фигуры объёмны — Джотто первым вернул живописи человеческие чувства.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Около 1305 года богатый банкир Энрико Скровеньи заказал роспись своей домовой часовни в Падуе художнику Джотто. Тот покрыл стены почти сорока сценами из жизни Марии и Христа.", "Здесь близкие оплакивают снятого с креста Христа. Мария обнимает тело сына, Иоанн раскинул руки от горя, ангелы в небе плачут и мечутся. Горная гряда идёт по диагонали вниз и ведёт наш взгляд к лицам Марии и Христа.", "Главное новшество Джотто в том, что фигуры объёмные и тяжёлые, они стоят на земле. Две фигуры сидят к нам спиной, как будто мы стоим рядом. До Джотто так не делали. Через сто лет художники Возрождения назовут его своим учителем."]}, {"t": "Император Юстиниан со свитой", "a": "Византийские мастера", "y": "около 547", "d": "Мозаика в Равенне. Фигуры парят без тени, смотрят прямо на нас — так выглядит власть, освящённая небом.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Meister_von_San_Vitale_in_Ravenna.jpg", "lic": "Public domain", "by": "Meister von San Vitale in Ravenna", "src": "media/img/a845c3d3d2-1000.webp", "w": 1000, "h": 1353, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Meister_von_San_Vitale_in_Ravenna.jpg/1280px-Meister_von_San_Vitale_in_Ravenna.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мозаика украшает церковь Сан-Витале в Равенне, её закончили около 547 года. Напротив неё мозаика с императрицей Феодорой.", "Юстиниан в пурпурной одежде с нимбом несёт золотое блюдо для хлеба причастия. Справа священники, слева воины и придворные. Все стоят в ряд, смотрят прямо на нас, ноги будто не касаются земли.", "Так византийцы показывали, что власть императора священна, он наместник Бога. Любопытно, что сам Юстиниан никогда не был в Равенне. Мозаика заменяла его присутствие."]}], "quiz": [{"q": "Что означает золотой фон в иконе?", "o": ["Богатство заказчика", "Божественный свет, небесный мир", "Солнечный день", "Пустыню"], "a": 1, "e": "Золото — не «место», а свет иного мира."}, {"q": "Какие черты отличают готику?", "o": ["Купола и плоские крыши", "Стрельчатые арки, витражи, высота", "Пирамиды и обелиски", "Колонны дорического ордера"], "a": 1, "e": "Готический собор весь стремится вверх, а стены превращаются в витражи."}, {"q": "Кто написал икону «Троица»?", "o": ["Феофан Грек", "Дионисий", "Андрей Рублёв", "Симон Ушаков"], "a": 2, "e": "Андрей Рублёв, начало XV века."}, {"q": "Какой художник предвестил Возрождение, вернув фигурам объём и эмоции?", "o": ["Джотто", "Рембрандт", "Ван Эйк", "Боттичелли"], "a": 0, "e": "Джотто работал около 1300 года — за век до расцвета Ренессанса."}], "why": ["После падения Рима в 476 году Европа на тысячу лет стала христианской. Искусство теперь рассказывало не о красоте тела, а о Боге и спасении души. Многие люди не умели читать, и росписи, витражи и иконы были для них Библией в картинках. В этой главе вы поймёте, почему средневековые фигуры плоские, а соборы такие высокие, и откуда взялась русская икона."], "groups": [{"h": "Византия: свет и золото", "p": "Восточная Римская империя со столицей в Константинополе прожила ещё тысячу лет. От неё Русь получила христианство и иконопись.", "items": [{"t": "Купол как небо", "d": "Огромный купол над храмом символизирует небо.", "c": "Собор Святой Софии в Константинополе, 537 год", "more": ["Император Юстиниан построил Святую Софию всего за пять лет. Её купол диаметром около 31 метра опирается на четыре арки, а у основания прорезан сорока окнами. Из-за этого кажется, что купол парит над храмом на свету.", "По летописи, послы киевского князя Владимира, побывав здесь, сказали, что не знали, на небе они или на земле. Вскоре Русь приняла христианство из Византии. В 1453 году город захватили турки, и собор стал мечетью."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Interior_of_Hagia_Sophia_(8)_-_Istanbul_(2022).jpg", "lic": "CC BY-SA 4.0", "by": "ImanFakhri", "src": "media/img/9a17f8be88-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Interior_of_Hagia_Sophia_%288%29_-_Istanbul_%282022%29.jpg/1280px-Interior_of_Hagia_Sophia_%288%29_-_Istanbul_%282022%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Икона: окно в другой мир", "d": "Икона показывает не земной мир, а небесный, поэтому в ней свои правила.", "c": "Владимирская икона Богоматери, XII век", "more": ["Икону написали в Константинополе и около 1131 года привезли на Русь. Её считали покровительницей Москвы и много раз носили по городу во время нашествий.", "Посмотрите: Младенец прижимается щекой к щеке матери. Этот тип иконы называют «Умиление». Фон золотой, это свет Царства Небесного. Фигуры плоские, без теней, потому что в небесном мире нет обычного земного света, который отбрасывает тень."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Virgin_of_Vladimir.jpg", "lic": "Public domain", "by": "Michel Bakni", "src": "media/img/9b635a556f-1000.webp", "w": 1000, "h": 1456, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Virgin_of_Vladimir.jpg/1280px-Virgin_of_Vladimir.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Романский стиль: крепость веры", "p": "В XI и XII веках на Западе строили массивные каменные храмы с толстыми стенами и маленькими окнами.", "items": [{"t": "Толстые стены, полукруглые арки", "d": "Романские соборы похожи на крепости.", "c": "Собор в Шпайере, Германия, XI век", "more": ["Название «романский» придумали в XIX веке: этот стиль похож на римский, у него такие же полукруглые арки. Своды делали из камня, и они были очень тяжёлыми. Чтобы стены выдержали вес, их строили толстыми, а окна делали маленькими.", "Собор в Шпайере строили императоры, он был самым большим храмом Европы своего времени. Внутри полутемно и торжественно. Такой храм ощущался как надёжная крепость веры в неспокойное время."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Aerial_image_of_the_Speyer_Cathedral_(view_from_the_southwest).jpg", "lic": "CC BY-SA 4.0", "by": "Carsten Steger", "src": "media/img/5c8558262f-1000.webp", "w": 1000, "h": 738, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Aerial_image_of_the_Speyer_Cathedral_%28view_from_the_southwest%29.jpg/1280px-Aerial_image_of_the_Speyer_Cathedral_%28view_from_the_southwest%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вышивка-летопись", "d": "Длинная история в картинках, как комикс.", "c": "Ковёр из Байё, около 1070 года", "more": ["Это полотно длиной почти 70 метров с вышивкой шерстью. Оно рассказывает, как нормандский герцог Вильгельм завоевал Англию в 1066 году.", "Сцены идут одна за другой, с подписями на латыни, как кадры комикса. На этом фрагменте люди показывают на небо, где летит комета. Это комета Галлея, она действительно появилась весной 1066 года, и её сочли знаком беды для английского короля."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg", "lic": "Public domain", "by": "Myrabella", "src": "media/img/e9267b627a-1000.webp", "w": 1000, "h": 642, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg/1280px-Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Готика: всё стремится вверх", "p": "С середины XII века строители нашли способ сделать стены лёгкими, а храмы очень высокими.", "items": [{"t": "Стены из стекла", "d": "Стрельчатые своды и наружные опоры позволили заменить стены витражами.", "c": "Сент-Шапель в Париже, 1248 год", "more": ["Секрет готики в стрельчатой арке и аркбутанах, наружных каменных «костылях», которые подпирают стены снаружи. Вес свода уходит на эти опоры, и стену можно почти целиком заменить окнами.", "Король Людовик IX построил Сент-Шапель для хранения реликвии, которую считали терновым венцом Христа. Витражи занимают около 600 квадратных метров и показывают больше тысячи библейских сцен. Когда светит солнце, кажется, что стоишь внутри драгоценного камня."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Sainte-Chapelle,_Paris,_upper_chapel_windows.jpg", "lic": "CC0", "by": "Gerda Arendt", "src": "media/img/46498a171d-1000.webp", "w": 1000, "h": 750, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Sainte-Chapelle%2C_Paris%2C_upper_chapel_windows.jpg/1280px-Sainte-Chapelle%2C_Paris%2C_upper_chapel_windows.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Роза", "d": "Огромное круглое окно-витраж на фасаде.", "c": "Северная роза собора в Шартре, около 1230 года", "more": ["Витраж собирают из кусочков цветного стекла, соединённых свинцовыми полосками. Стекло окрашивали ещё при варке: добавляли металлы, кобальт давал синий, медь красный.", "Синий цвет Шартра такой глубокий, что его называют «шартрским синим», и повторить его рецепт до сих пор не удаётся точно. Свет считался образом Бога, поэтому цветные окна делали храм «небесным Иерусалимом» на земле."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg", "lic": "Public domain", "by": "Eusebius", "src": "media/img/1e536f9172-1000.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg/1280px-Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Книжная миниатюра", "d": "Рукописные книги украшали маленькими картинами.", "c": "«Великолепный часослов герцога Беррийского», октябрь", "more": ["Книгопечатания ещё не было, книги переписывали от руки и украшали рисунками. Самая знаменитая из них сделана для французского герцога братьями Лимбург около 1415 года.", "Каждый месяц календаря показан сценой. В октябре крестьяне сеют зерно, а за рекой стоит настоящий парижский дворец Лувр, каким он был тогда. На полях стоит пугало в виде лучника, чтобы отгонять птиц. Здесь уже появляется интерес к реальному миру, предвестие Возрождения."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_octobre.jpg", "lic": "Public domain", "by": "Limbourg brothers / Barthélemy d'Eyck", "src": "media/img/7ce709c192-1000.webp", "w": 1000, "h": 1667, "remote": "https://upload.wikimedia.org/wikipedia/commons/f/f5/Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_octobre.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "a4", "title": "Возрождение", "period": "XV — XVI век", "intro": [], "traits": ["Гуманизм: человек в центре мира", "Линейная перспектива и анатомическая точность", "Античные сюжеты наравне с библейскими", "Сфумато, масляная живопись", "Титаны: Леонардо, Микеланджело, Рафаэль"], "works": [{"t": "Рождение Венеры", "a": "Сандро Боттичелли", "y": "около 1485", "d": "Языческая богиня выходит из моря на раковине. Для христианской Флоренции — смелый жест. Линии плавные, как в танце.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/d1f4f16c8b-1000.webp", "w": 1000, "h": 628, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Сандро Боттичелли написал картину около 1485 года во Флоренции, скорее всего для семьи Медичи. Это одна из первых больших картин с языческой богиней после тысячи лет христианского искусства.", "Богиня любви Венера родилась из морской пены и плывёт к берегу на раковине. Слева её подгоняют боги ветров, справа нимфа встречает её с плащом в цветах. Поза Венеры повторяет античные статуи: Боттичелли видел их в коллекции Медичи.", "Линии плавные, фигуры лёгкие, будто танцуют. Боттичелли интересовала не анатомия, а красота и поэзия. Через несколько лет под влиянием проповедника Савонаролы он сжёг часть своих «языческих» работ, но эта уцелела."]}, {"t": "Мона Лиза (Джоконда)", "a": "Леонардо да Винчи", "y": "1503–1519", "d": "Самая известная картина мира. Обратите внимание на сфумато: уголки губ и глаз растворены в дымке, поэтому улыбка «ускользает».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Леонардо начал портрет около 1503 года. Скорее всего, это Лиза Герардини, жена флорентийского торговца Франческо дель Джокондо, отсюда второе название. Леонардо так и не отдал картину заказчику и возил её с собой до конца жизни.", "Главный приём здесь сфумато, по-итальянски «как дым». Контуры не обведены линией, а растворяются в мягких тенях. Особенно у уголков губ и глаз. Поэтому кажется, что Мона Лиза то улыбается, то грустит.", "Пейзаж за спиной фантастический, слева и справа он на разной высоте. В 1911 году итальянский рабочий украл картину из Лувра, и её два года искали по всему миру. После этого она стала самой знаменитой картиной на планете."]}, {"t": "Сотворение Адама", "a": "Микеланджело Буонарроти", "y": "около 1511", "d": "Фреска потолка Сикстинской капеллы. Пальцы Бога и Адама почти касаются — в этом зазоре вся драма.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Michelangelo_-_Creation_of_Adam_(cropped).jpg", "lic": "Public domain", "by": "Michelangelo", "src": "media/img/9cda9ecdae-1000.webp", "w": 1000, "h": 454, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1508 году папа Юлий II поручил Микеланджело расписать потолок Сикстинской капеллы. Микеланджело считал себя скульптором и сопротивлялся, но за четыре года написал площадь больше 500 квадратных метров, работая на лесах под самым сводом.", "Эта сцена самая известная. Бог в окружении ангелов протягивает руку к Адаму, чтобы передать ему жизнь. Адам вялый, он ещё не ожил. Между их пальцами крошечный зазор, и в нём всё напряжение момента.", "Тело Адама написано как античная скульптура. Некоторые врачи заметили, что фигура Бога с ангелами по форме похожа на человеческий мозг. Случайно это или нет, неизвестно, но Микеланджело хорошо знал анатомию."]}, {"t": "Афинская школа", "a": "Рафаэль Санти", "y": "1509–1511", "d": "Платон и Аристотель в центре, вокруг — великие мыслители. Идеальная перспектива: все линии сходятся к двум философам.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg", "lic": "Public domain", "by": "Raphael", "src": "media/img/88562caed1-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/1280px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Рафаэль написал эту фреску в 1509–1511 годах в покоях папы в Ватикане. Ему было всего около двадцати шести лет.", "Под величественными арками собрались философы и учёные Древней Греции. В центре Платон указывает вверх, в мир идей, а его ученик Аристотель указывает вниз, на реальный мир. Так Рафаэль показал два главных пути в философии.", "Многим философам Рафаэль дал лица своих современников: Платон похож на Леонардо, а Гераклит в центре на переднем плане на Микеланджело. Себя художник тоже нарисовал справа, он смотрит прямо на нас. Все линии здания сходятся к двум главным фигурам, это образец перспективы."]}, {"t": "Портрет четы Арнольфини", "a": "Ян ван Эйк", "y": "1434", "d": "Северное Возрождение. В выпуклом зеркале на стене отражена вся комната и сам художник.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Фламандский художник Ян ван Эйк написал портрет в 1434 году. На нём итальянский купец Джованни Арнольфини и его жена в доме в городе Брюгге.", "Ван Эйк одним из первых в совершенстве освоил масляную живопись. Посмотрите на детали: каждый волосок собачки, блеск латунной люстры, апельсины на подоконнике. Апельсины были дорогими, и это знак богатства.", "В выпуклом зеркале на стене отражается вся комната и ещё двое людей у двери. Над зеркалом надпись: «Ян ван Эйк был здесь. 1434». Возможно, художник был свидетелем важного события в жизни этой пары."]}, {"t": "Давид", "a": "Микеланджело Буонарроти", "y": "1501–1504", "d": "Пятиметровый мраморный юноша перед боем с Голиафом. Классический контрапост — привет от Греции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%27David%27_by_Michelangelo_Fir_JBU004.jpg", "lic": "CC BY 3.0", "by": "Jörg Bittner Unna", "src": "media/img/36bbc1e88e-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/%27David%27_by_Michelangelo_Fir_JBU004.jpg/1280px-%27David%27_by_Michelangelo_Fir_JBU004.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Микеланджело было 26 лет, когда в 1501 году он взялся за огромный кусок мрамора, который сорок лет лежал во дворе собора. Другие скульпторы отказались от него, считая испорченным. Через три года статуя высотой больше пяти метров была готова.", "По Библии, юный пастух Давид победил великана Голиафа камнем из пращи. Обычно Давида изображали после победы, с головой врага. Микеланджело показал момент до боя: Давид собран, брови нахмурены, праща перекинута через плечо.", "Поза построена на контрапосте, как у греческих статуй. Голова и руки немного больше нормы: статуя должна была стоять высоко на соборе и смотреться снизу. Флорентийцы увидели в Давиде символ своего маленького города, который не боится сильных врагов."]}], "quiz": [{"q": "Что такое гуманизм?", "o": ["Вера в магию", "Взгляд, ставящий человека в центр мира", "Стиль архитектуры", "Техника фрески"], "a": 1, "e": "Гуманисты верили в достоинство и возможности человека."}, {"q": "Как называется дымчатая манера Леонардо, смягчающая контуры?", "o": ["Сфумато", "Импасто", "Пуантилизм", "Гризайль"], "a": 0, "e": "Sfumato — «исчезающий как дым»."}, {"q": "В каком городе началось итальянское Возрождение?", "o": ["Рим", "Венеция", "Флоренция", "Милан"], "a": 2, "e": "Флоренция при Медичи — колыбель Ренессанса."}, {"q": "Кто из этих художников — представитель Северного Возрождения?", "o": ["Рафаэль", "Ян ван Эйк", "Боттичелли", "Тициан"], "a": 1, "e": "Ван Эйк работал во Фландрии и прославился масляной живописью."}], "why": ["Возрождение изменило то, как мы видим мир. Художники изучили анатомию, придумали перспективу и вернули искусству интерес к человеку. Многое из того, что сегодня кажется нормальным для картины, придумано именно тогда: глубина, объём, живые лица, точные пропорции. Это самая известная эпоха в истории искусства, и её работы вы точно уже видели."], "groups": [{"h": "Наука и искусство вместе", "p": "Художники Возрождения были и учёными. Они изучали тело, геометрию, оптику.", "items": [{"t": "Пропорции человека", "d": "Художники вычисляли идеальные пропорции тела.", "c": "Леонардо да Винчи. «Витрувианский человек», около 1490", "more": ["Римский архитектор Витрувий писал, что тело человека с раскинутыми руками и ногами вписывается и в круг, и в квадрат. Леонардо проверил это на рисунке. Он измерял людей и записал, что размах рук равен росту, а ладонь равна четырём пальцам.", "Леонардо тайно вскрывал умерших, чтобы понять, как устроены мышцы и кости, и оставил сотни анатомических рисунков. Знание анатомии позволило художникам рисовать тело точнее, чем когда-либо раньше."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vitruvian_Man_by_Leonardo_da_Vinci.jpg", "lic": "CC BY-SA 4.0", "by": "Paris Orlando", "src": "media/img/5d9a454d9c-1000.webp", "w": 1000, "h": 1421, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Vitruvian_Man_by_Leonardo_da_Vinci.jpg/1280px-Vitruvian_Man_by_Leonardo_da_Vinci.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Купол Брунеллески", "d": "Архитектор решил задачу, которую считали невозможной.", "c": "Купол собора во Флоренции, 1420–1436", "more": ["Собор во Флоренции строили больше ста лет, но над ним зияла огромная дыра шириной 45 метров. Никто не знал, как перекрыть её куполом: не было таких длинных деревянных опор для строительства.", "Филиппо Брунеллески изучил римский Пантеон и придумал купол из двух оболочек, внутренней и внешней, с кирпичами, уложенными «ёлочкой». Купол держал сам себя во время строительства. Это самый большой кирпичный купол в мире. Тот же Брунеллески открыл правила линейной перспективы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Florence,_Italy,_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg", "lic": "CC BY 4.0", "by": "Vyacheslav Argenberg", "src": "media/img/7f3408f659-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Florence%2C_Italy%2C_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg/1280px-Florence%2C_Italy%2C_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Северное Возрождение", "p": "В Нидерландах и Германии Возрождение шло своим путём: меньше античности, больше точности и религиозных чувств.", "items": [{"t": "Художник как личность", "d": "Художник впервые пишет себя с достоинством учёного и мастера.", "c": "Альбрехт Дюрер. Автопортрет, 1500", "more": ["В Средние века художник считался ремесленником, как сапожник. Дюрер изобразил себя прямо, фронтально, как обычно изображали только Христа. Справа надпись: «Я, Альбрехт Дюрер из Нюрнберга, написал себя вечными красками в 28 лет».", "Дюрер ездил в Италию, изучал перспективу и пропорции и привёз эти идеи в Германию. Его гравюры продавались по всей Европе, и он стал первым художником, который прославился благодаря печати."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_1500_self-portrait_(High_resolution_and_detail).jpg", "lic": "Public domain", "by": "Albrecht Dürer", "src": "media/img/b8ac429923-1000.webp", "w": 1000, "h": 1383, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Albrecht_D%C3%BCrer_-_1500_self-portrait_%28High_resolution_and_detail%29.jpg/1280px-Albrecht_D%C3%BCrer_-_1500_self-portrait_%28High_resolution_and_detail%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Фантазия и мораль", "d": "Странные миры, полные символов.", "c": "Иероним Босх. «Сад земных наслаждений», около 1500", "more": ["Это триптих, картина из трёх створок. Слева рай, где Бог знакомит Адама и Еву. В центре люди предаются удовольствиям среди огромных ягод и птиц. Справа ад с музыкальными инструментами-пытками и чудовищами.", "Босх предупреждал, к чему ведут грехи. Смысл многих деталей до сих пор разгадывают. Через четыреста лет его фантазии вдохновят сюрреалистов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg", "lic": "Public domain", "by": "Hieronymus Bosch", "src": "media/img/cdc9c499d7-1000.webp", "w": 1000, "h": 569, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg/1280px-The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a5", "title": "Барокко", "period": "XVII век", "intro": [], "traits": ["Динамика, диагональные композиции", "Резкий контраст света и тени", "Театральность, пышность, эмоции на пределе", "Синтез искусств: архитектура + скульптура + живопись", "Голландия: бытовой жанр и натюрморт"], "works": [{"t": "Призвание апостола Матфея", "a": "Караваджо", "y": "1599–1600", "d": "Луч света следует за жестом Христа и падает на сборщика податей. Свет здесь — сам призыв.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Calling_of_Saint_Matthew-Caravaggo_(1599-1600).jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/0184cd4f33-1000.webp", "w": 1000, "h": 1028, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg/1280px-The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Караваджо написал картину в 1599–1600 годах для церкви в Риме. По Евангелию, Христос позвал сборщика налогов Матфея, и тот оставил всё и пошёл за ним.", "Сцена происходит в обычной римской таверне. Люди в модной одежде считают деньги. Справа входит Христос и указывает на Матфея. Луч света из невидимого окна идёт следом за его рукой и падает на лица. Матфей показывает на себя, будто спрашивает: «Я?»", "Караваджо писал святых как простых людей, иногда моделями служили уличные бродяги. Многим это не нравилось. Но его резкий свет из темноты, тенебросо, подхватили художники по всей Европе."]}, {"t": "Ночной дозор", "a": "Рембрандт ван Рейн", "y": "1642", "d": "Групповой портрет стрелковой роты, превращённый в живую сцену. На самом деле действие дневное — картина потемнела от лака.", "img": {"page": "https://commons.wikimedia.org/wiki/File:La_ronda_de_noche,_por_Rembrandt_van_Rijn.jpg", "lic": "Public domain", "by": "Rembrandt", "src": "media/img/056817c627-1000.webp", "w": 1000, "h": 814, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg/1280px-La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1642 году отряд городской стражи Амстердама заказал Рембрандту групповой портрет. Такие портреты обычно выглядели как ряды голов, и каждый платил за своё место.", "Рембрандт превратил портрет в живую сцену: капитан отдаёт приказ, отряд выступает, кто-то заряжает мушкет, бьёт барабан, бежит девочка с курицей на поясе, символом отряда. Картина огромная, около 4 на 4,5 метра.", "Название «Ночной дозор» появилось позже: лак со временем потемнел, и сцена стала казаться ночной. На самом деле это день. Говорят, что заказчики были недовольны, потому что не всех хорошо видно, но это скорее легенда."]}, {"t": "Менины", "a": "Диего Веласкес", "y": "1656", "d": "Загадка-картина: художник пишет королевскую чету, отражённую в зеркале, а смотрим на сцену мы — с их места.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Las_Meninas,_by_Diego_Vel%C3%A1zquez,_from_Prado_in_Google_Earth.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/394994c256-1000.webp", "w": 1000, "h": 1151, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/1280px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Испанский придворный художник Диего Веласкес написал картину в 1656 году. В центре маленькая инфанта Маргарита, дочь короля, вокруг неё фрейлины, по-испански менины, карлики и собака.", "Слева сам Веласкес стоит у огромного холста с кистью. Кого он пишет? В зеркале на дальней стене отражаются король и королева. Значит, они стоят там, где стоим мы, зрители, и все смотрят на них.", "Получается игра: мы видим сцену глазами короля. Картину считают одной из самых загадочных в истории. Пикассо написал по её мотивам 58 своих вариантов."]}, {"t": "Девушка с жемчужной серёжкой", "a": "Ян Вермеер", "y": "около 1665", "d": "«Северная Мона Лиза». Тихий голландский свет, ультрамарин и один блик на жемчуге.", "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Ян Вермеер жил в городе Делфт и написал эту работу около 1665 года. Это не портрет на заказ, а этюд головы в экзотическом костюме, голландцы называли такие работы «тронье».", "Девушка обернулась через плечо, губы приоткрыты, будто хочет что-то сказать. Фон тёмный, почти чёрный, поэтому лицо и тюрбан светятся. Синий цвет сделан из лазурита, привезённого из Афганистана, он стоил дороже золота.", "Жемчужина нарисована всего двумя мазками: блик сверху и отражение воротника снизу. Возможно, это вообще не жемчуг, а полированное олово или стекло, слишком уж она большая. Имя девушки неизвестно."]}, {"t": "Экстаз святой Терезы", "a": "Джан Лоренцо Бернини", "y": "1647–1652", "d": "Скульптура как театральная сцена: мрамор превращён в облака и складки, сверху льётся настоящий свет из скрытого окна.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ecstasy_of_Saint_Teresa_September_2015-2a.jpg", "lic": "CC BY-SA 4.0", "by": "Gian Lorenzo Bernini", "src": "media/img/ed744cd141-1000.webp", "w": 1000, "h": 1585, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Ecstasy_of_Saint_Teresa_September_2015-2a.jpg/1280px-Ecstasy_of_Saint_Teresa_September_2015-2a.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Скульптор и архитектор Джан Лоренцо Бернини создал эту композицию в 1647–1652 годах для капеллы в римской церкви.", "Святая Тереза из Авилы описала видение: ангел пронзил её сердце золотой стрелой, и она почувствовала одновременно боль и огромную любовь к Богу. Бернини показал этот момент. Тереза парит на мраморном облаке, ангел улыбается.", "Это настоящий театр. Сверху льётся свет из скрытого окна, золотые лучи из бронзы падают на фигуры. По бокам капеллы Бернини поместил скульптуры заказчиков в ложах, как зрителей в театре. Мрамор у него выглядит как мягкая ткань и пух облаков."]}], "quiz": [{"q": "Какой приём особенно характерен для Караваджо?", "o": ["Золотой фон", "Резкий луч света из темноты", "Пуантилизм", "Обратная перспектива"], "a": 1, "e": "Тенебросо — «тёмная манера»: фигуры вырваны из мрака светом."}, {"q": "Чем барокко отличается от Возрождения?", "o": ["Спокойствием и симметрией", "Движением, драмой, театральностью", "Плоскостью изображения", "Отказом от сюжета"], "a": 1, "e": "Возрождение — гармония, барокко — страсть и движение."}, {"q": "В какой стране работали Вермеер и Рембрандт?", "o": ["Испания", "Италия", "Голландия", "Франция"], "a": 2, "e": "Золотой век голландской живописи — XVII век."}], "why": ["Барокко родилось в XVII веке, когда католическая церковь и короли хотели поразить людей, вызвать сильные чувства. Отсюда драма, роскошь и театральность. А в протестантской Голландии в то же время появилось совсем другое, тихое искусство для обычных горожан. Поняв эти два пути, вы увидите, как искусство зависит от того, кто его заказывает."], "groups": [{"h": "Искусство, которое потрясает", "p": "Церковь и монархи использовали искусство, чтобы показать свою силу и славу.", "items": [{"t": "Движение и страсть", "d": "Диагонали, бурные жесты, тела в движении.", "c": "Рубенс. «Снятие с креста», 1614", "more": ["Питер Пауль Рубенс из Антверпена был самым успешным художником Европы, у него была огромная мастерская с учениками. Эту картину он написал для собора в родном городе.", "Тело Христа соскальзывает вниз по белому полотну, и все фигуры подхватывают его. Композиция построена по диагонали сверху вниз, от этого кажется, что всё происходит прямо сейчас. Белая ткань притягивает взгляд к центру. Это типичный приём барокко: зритель должен почувствовать, а не просто посмотреть."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg", "lic": "Public domain", "by": "Peter Paul Rubens", "src": "media/img/b778a01789-1000.webp", "w": 1000, "h": 586, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg/1280px-Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Дворец как театр", "d": "Архитектура барокко ослепляет роскошью.", "c": "Зеркальная галерея Версаля, 1684", "more": ["Король Франции Людовик XIV превратил охотничий домик в огромный дворец Версаль. Так он показывал, что вся власть в стране принадлежит ему. Его называли «король-солнце».", "В галерее 357 зеркал напротив семнадцати окон. Зеркала тогда были очень дорогими, их умели делать только в Венеции, а французы переманили мастеров. Днём галерея наполнена светом, вечером тысячи свечей отражались в стёклах. Позже по образцу Версаля строили дворцы по всей Европе, включая Петергоф."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Chateau_Versailles_Galerie_des_Glaces.jpg", "lic": "CC BY-SA 3.0", "by": "Myrabella", "src": "media/img/8e414e2d8a-1000.webp", "w": 1000, "h": 664, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Chateau_Versailles_Galerie_des_Glaces.jpg/1280px-Chateau_Versailles_Galerie_des_Glaces.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Голландия: искусство для горожан", "p": "В Голландии не было пышного двора, а церковь запрещала картины в храмах. Картины покупали обычные горожане для своих домов.", "items": [{"t": "Тихие сцены дома", "d": "Будничные занятия, свет из окна, порядок и покой.", "c": "Вермеер. «Молочница», около 1660", "more": ["Служанка аккуратно наливает молоко. Больше ничего не происходит, но от картины трудно оторваться. Свет падает из окна слева, на хлебе блестят крошечные точки краски, похожие на крупинки света.", "Голландцы гордились чистотой, трудом и порядком в доме, и такие картины показывали эти ценности. Вермеер работал медленно и писал около двух картин в год, поэтому их сохранилось так мало."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/e301c142dc-1000.webp", "w": 1000, "h": 1121, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg/1280px-Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Свет души", "d": "Рембрандт находил в тени глубину чувств.", "c": "Рембрандт. Автопортрет, 1669", "more": ["Рембрандт написал около восьмидесяти автопортретов за жизнь. Молодым он изображал себя в дорогих нарядах, когда был богат и знаменит. Потом он разорился, потерял жену и сына, дом продали за долги.", "Этот портрет написан в год смерти. Старое усталое лицо выходит из темноты, руки сложены. В нём нет ни позы, ни самолюбования. Рембрандт честно показывает, что сделала с ним жизнь, и от этого портрет кажется живым разговором."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Rembrandt", "src": "media/img/b30387ec73-1000.webp", "w": 1000, "h": 1295, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg/1280px-Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a6", "title": "Классицизм и романтизм", "period": "XVIII — первая половина XIX века", "intro": [], "traits": ["Классицизм: долг, разум, античные сюжеты, чёткий рисунок", "Романтизм: чувства, стихия, свобода, мистика", "Романтический герой одинок и противостоит миру", "Классицизм — линия, романтизм — цвет", "Интерес к национальной истории и фольклору"], "works": [{"t": "Клятва Горациев", "a": "Жак-Луи Давид", "y": "1784", "d": "Манифест классицизма: братья клянутся отцу сражаться за Рим. Мужчины — прямые линии долга, женщины справа — мягкие линии горя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Anne-Louis Girodet / After Jacques-Louis David", "src": "media/img/22bf98d9da-1000.webp", "w": 1000, "h": 780, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg/1280px-Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Жак-Луи Давид написал картину в 1784 году. Сюжет из истории Древнего Рима: три брата Горации клянутся отцу, что будут сражаться за Рим с тремя братьями из враждебного города, даже ценой жизни.", "Композиция очень чёткая. Три арки, три группы. Слева братья: прямые ноги, вытянутые руки, всё как натянутые струны. В центре отец с мечами. Справа плачущие женщины, их линии мягкие и согнутые. Одна из них невеста врага, другая сестра врага.", "Смысл ясен: долг перед родиной выше личных чувств. Через пять лет начнётся Французская революция, и картина станет для революционеров символом гражданской доблести."]}, {"t": "Свобода, ведущая народ", "a": "Эжен Делакруа", "y": "1830", "d": "Июльская революция в Париже. Аллегория Свободы с флагом идёт через баррикаду — символ Франции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg", "lic": "Public domain", "by": "Eugène Delacroix", "src": "media/img/0c3bfae6f4-1000.webp", "w": 1000, "h": 802, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg/1280px-Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В июле 1830 года парижане три дня сражались на баррикадах и свергли короля Карла X. Эжен Делакруа сам на баррикадах не был, но той же осенью написал эту картину.", "Женщина с трёхцветным флагом и во фригийском колпаке это не реальный человек, а аллегория Свободы. За ней идут люди разных сословий: рабочий с саблей, буржуа в цилиндре с ружьём, мальчишка с пистолетами. Под ногами погибшие.", "Тела, дым, движение вперёд, цвета флага повторяются по всей картине. Это романтизм: чувство порыва важнее точного рисунка. Сегодня Марианна, женщина во фригийском колпаке, символ Франции, её изображают на марках и монетах."]}, {"t": "Странник над морем тумана", "a": "Каспар Давид Фридрих", "y": "около 1818", "d": "Икона романтизма: одинокий человек спиной к нам перед бескрайней природой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg", "lic": "Public domain", "by": "Caspar David Friedrich", "src": "media/img/e5489bdc04-1000.webp", "w": 1000, "h": 1281, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg/1280px-Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Немецкий художник Каспар Давид Фридрих написал картину около 1818 года. Человек в тёмном пальто стоит на скале спиной к нам и смотрит на горы, утопающие в тумане.", "Мы не видим его лица и смотрим вместе с ним. Это любимый приём Фридриха: зритель становится героем картины. Перед бескрайней природой человек одинок и мал, но он поднялся на вершину.", "Для романтиков природа была путём к Богу и к самому себе. Сегодня эта картина стала символом всего романтизма и часто появляется на обложках книг о философии."]}, {"t": "Третье мая 1808 года", "a": "Франсиско Гойя", "y": "1814", "d": "Расстрел испанских повстанцев французами. Белая рубаха и раскинутые руки — образ жертвы на все времена.", "img": {"page": "https://commons.wikimedia.org/wiki/File:El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_thin_black_margin.jpg", "lic": "Public domain", "by": "El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_in_Google_Earth.jpg: Francisco", "src": "media/img/e92f790510-1000.webp", "w": 1000, "h": 772, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg/1280px-El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1808 году армия Наполеона заняла Испанию. 2 мая жители Мадрида восстали, а ночью и утром 3 мая французы расстреливали пленных. Франсиско Гойя написал картину в 1814 году, после изгнания французов.", "Солдаты стоят ровным рядом спиной к нам, лиц не видно, они как машина. Напротив жертвы. Человек в белой рубашке раскинул руки, на ладони виден след, похожий на рану от гвоздя. Он как распятый мученик.", "Свет от большого фонаря падает на него, а остальное в темноте. До Гойи войну обычно изображали как подвиг. Он первым показал её как бессмысленное убийство. Эта картина повлияла на многие антивоенные работы, включая «Гернику» Пикассо."]}, {"t": "Последний день Помпеи", "a": "Карл Брюллов", "y": "1830–1833", "d": "Первая русская картина с мировой славой. Классицистические фигуры в романтической катастрофе.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/7a055b23ec-1000.webp", "w": 1000, "h": 702, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg/1280px-Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Карл Брюллов побывал на раскопках Помпей и шесть лет работал над картиной, закончив её в 1833 году. Размер почти 5 на 6,5 метра.", "Извержение Везувия, 79 год. Рушатся здания и статуи, небо разрывает молния. Люди пытаются спасти близких: сыновья несут старика-отца, мать обнимает дочерей. В левом углу художник изобразил себя с ящиком красок.", "Фигуры прекрасны, как античные статуи, это от классицизма. А катастрофа, страх и ночное зарево от романтизма. Картину с восторгом встретили в Риме и Париже, и это был первый мировой успех русской живописи. Гоголь назвал её «светлым воскресением живописи»."]}], "quiz": [{"q": "Что ставит на первое место классицизм?", "o": ["Личные чувства", "Долг и разум", "Мистику", "Впечатление момента"], "a": 1, "e": "Классицизм учит: долг перед обществом выше личного."}, {"q": "Какие темы любят романтики?", "o": ["Порядок и симметрию", "Стихию, свободу, одиночество героя", "Геометрические фигуры", "Повседневный быт"], "a": 1, "e": "Буря, ночь, горы, революция — всё, что сильнее разума."}, {"q": "Кто написал «Последний день Помпеи»?", "o": ["Илья Репин", "Карл Брюллов", "Иван Айвазовский", "Василий Суриков"], "a": 1, "e": "Карл Брюллов, 1833 год."}], "why": ["В конце XVIII века Европа увлеклась раскопками Помпей и античностью и решила, что искусство должно учить разуму и долгу. Так появился классицизм. Через несколько десятилетий молодые художники восстали: им было важнее чувство, свобода и тайна. Это романтизм. Петербург, Пушкин, Брюллов, Айвазовский выросли из этих двух течений, и спор между разумом и чувством идёт в искусстве до сих пор."], "groups": [{"h": "Классицизм: разум и порядок", "p": "Образец снова античность, а главная ценность долг перед обществом.", "items": [{"t": "Колоннады и симметрия", "d": "Здания строят по античным правилам: портики, колонны, строгий порядок.", "c": "Казанский собор в Петербурге, 1811", "more": ["Архитектор Андрей Воронихин строил собор десять лет. Его полукруглая колоннада из 96 колонн охватывает площадь, как раскрытые руки. Образец понятен: колоннада собора Святого Петра в Риме.", "Петербург почти весь построен в стиле классицизма: Адмиралтейство, Биржа, Сенат. После войны 1812 года собор стал памятником победе. Здесь похоронен фельдмаршал Кутузов и хранятся французские знамёна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Kazan_Cathedral_Saint_Petersburg.jpg", "lic": "CC BY-SA 3.0", "by": "This Photo was taken by Wolfgang Moroder.  \n\nFeel free to use my photos, but ple", "src": "media/img/3a8181e131-1000.webp", "w": 1000, "h": 452, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Kazan_Cathedral_Saint_Petersburg.jpg/1280px-Kazan_Cathedral_Saint_Petersburg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мрамор как античность", "d": "Скульпторы подражали грекам: гладкий белый мрамор, идеальные тела.", "c": "Антонио Канова. «Психея, оживлённая поцелуем Амура», 1793", "more": ["По мифу, девушка Психея открыла запретный сосуд и уснула мёртвым сном. Её возлюбленный, бог любви Амур, разбудил её поцелуем.", "Итальянец Антонио Канова был самым знаменитым скульптором своего времени. Посмотрите, как фигуры образуют букву X, а руки складываются в круг вокруг лиц. Мрамор отполирован так гладко, что кажется тёплой кожей. Классицизм, но в нём уже есть нежность и чувство."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Psyche_Revived_by_Cupid%27s_Kiss,_Louvre_22_July_2017.jpg", "lic": "CC0", "by": "Joe deSousa", "src": "media/img/b50a95b65c-1000.webp", "w": 1000, "h": 668, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Psyche_Revived_by_Cupid%27s_Kiss%2C_Louvre_22_July_2017.jpg/1280px-Psyche_Revived_by_Cupid%27s_Kiss%2C_Louvre_22_July_2017.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Романтизм: чувство и свобода", "p": "Романтики любили бурю, ночь, катастрофы, экзотику и одиноких героев.", "items": [{"t": "Катастрофа и надежда", "d": "Романтики писали трагические события своего времени.", "c": "Жерико. «Плот „Медузы“», 1819", "more": ["В 1816 году французский корабль «Медуза» сел на мель у берегов Африки. Капитан и офицеры уплыли на шлюпках, а 147 человек бросили на наспех сколоченном плоту. Через 13 дней в живых осталось 15.", "Теодор Жерико разговаривал с выжившими, изучал тела в больнице и построил макет плота. Картина огромная, семь метров в ширину. Фигуры поднимаются пирамидой к человеку, который машет платком далёкому кораблю. Это обвинение властям и одновременно образ надежды."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Theodore_Gericault_Raft_of_the_Medusa-1.jpg", "lic": "Public domain", "by": "Théodore Géricault (1791-1824)", "src": "media/img/c8dda73790-1000.webp", "w": 1000, "h": 678, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c2/Theodore_Gericault_Raft_of_the_Medusa-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Свет и стихия", "d": "Цвет и свет важнее чёткого рисунка.", "c": "Тёрнер. «Последний рейс корабля „Отважный“», 1839", "more": ["Старый военный парусник «Отважный» сражался в знаменитой битве при Трафальгаре. Здесь маленький чёрный пароход тащит его на разборку. Уходит эпоха парусов, приходит эпоха пара.", "Уильям Тёрнер писал так свободно, что современники ругали его картины за «туман». Посмотрите на закат: он горит, как огонь. Корабль-призрак бледный, почти растворяется в воздухе. Через несколько десятилетий импрессионисты будут учиться у Тёрнера."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Fighting_Temeraire,_JMW_Turner,_National_Gallery.jpg", "lic": "Public domain", "by": "J. M. W. Turner", "src": "media/img/6fd8772780-1000.webp", "w": 1000, "h": 743, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/The_Fighting_Temeraire%2C_JMW_Turner%2C_National_Gallery.jpg/1280px-The_Fighting_Temeraire%2C_JMW_Turner%2C_National_Gallery.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Романтический портрет", "d": "Не важная особа, а живой человек с внутренним миром.", "c": "Кипренский. Портрет Пушкина, 1827", "more": ["Портрет заказал друг поэта Антон Дельвиг. Пушкину было 28 лет. Он в клетчатом шотландском плаще, руки скрещены, взгляд направлен куда-то в сторону.", "Позади статуя музы с лирой, знак поэтического вдохновения. Сам Пушкин написал о портрете: «Себя как в зеркале я вижу, но это зеркало мне льстит». Это самый известный прижизненный портрет поэта."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/7f8c1f87ea-1000.webp", "w": 1000, "h": 1158, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg/1280px-Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a7", "title": "Реализм и импрессионизм", "period": "вторая половина XIX века", "intro": [], "traits": ["Реализм: правда жизни, социальные темы, простые люди", "Передвижники в России: Репин, Суриков, Перов, Левитан", "Импрессионизм: свет, воздух, мимолётное впечатление", "Живопись на пленэре (на открытом воздухе)", "Раздельный мазок, светлая палитра"], "works": [{"t": "Бурлаки на Волге", "a": "Илья Репин", "y": "1870–1873", "d": "Одиннадцать бурлаков тянут баржу. Каждый — отдельная судьба, а молодой Ларька в центре поднимает голову — будто бунтует.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ilia_Efimovich_Repin_(1844-1930)_-_Volga_Boatmen_(1870-1873).jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/8c2c6391f0-1000.webp", "w": 1000, "h": 462, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg/1280px-Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Молодой Илья Репин увидел бурлаков на Неве и был потрясён контрастом: рядом нарядная публика гуляет, а люди, как скот, тянут баржу. Летом 1870 года он поехал на Волгу, жил среди бурлаков и делал зарисовки. Картину закончил в 1873 году.", "Бурлаки тащили суда против течения на длинной лямке. Здесь одиннадцать человек, и у каждого свой характер. Впереди мудрый Канин, бывший священник. В центре молодой Ларька поправляет лямку и поднимает голову, будто не хочет мириться с такой жизнью.", "Картину купил великий князь Владимир Александрович, и она объехала выставки Европы. Она сделала Репина знаменитым."]}, {"t": "Впечатление. Восходящее солнце", "a": "Клод Моне", "y": "1872", "d": "Картина, давшая имя целому направлению. Порт Гавра в утренней дымке, оранжевое солнце из нескольких мазков.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Monet_-_Impression,_Sunrise.jpg", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/d79ad960ff-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Monet_-_Impression%2C_Sunrise.jpg/1280px-Monet_-_Impression%2C_Sunrise.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Клод Моне написал вид порта в городе Гавр утром 1872 года. Туман, силуэты кораблей, лодки, и оранжевый круг солнца с бликом на воде, всё буквально несколькими мазками.", "В 1874 году группа молодых художников, которых не пускали на официальный парижский Салон, устроила свою выставку. Моне назвал эту картину «Впечатление», по-французски impression. Критик Луи Леруа в насмешку назвал всех участников «импрессионистами». Художникам название понравилось, и они его оставили.", "Интересно, что солнце на картине той же яркости, что и небо вокруг. Если сделать её чёрно-белой, солнце почти исчезнет. Его выделяет только цвет."]}, {"t": "Бал в Мулен де ла Галетт", "a": "Пьер Огюст Ренуар", "y": "1876", "d": "Танцы на Монмартре. Солнечные пятна скользят по одежде и лицам — сама радость жизни.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre-Auguste_Renoir,_Le_Moulin_de_la_Galette.jpg", "lic": "Public domain", "by": "Pierre-Auguste Renoir", "src": "media/img/4850d8c9de-1000.webp", "w": 1000, "h": 745, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg/1280px-Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мулен де ла Галетт это танцевальное кафе возле старой мельницы на холме Монмартр в Париже. По воскресеньям сюда приходили рабочие, швеи, художники. Пьер Огюст Ренуар написал картину в 1876 году прямо на месте.", "Друзья Ренуара позировали ему, сидя за столиками. Солнце пробивается сквозь листву и рассыпается пятнами по одежде, лицам и земле. Ренуар писал тени не серыми, а голубыми и сиреневыми, как они выглядят в солнечный день.", "Картина передаёт ощущение счастливого летнего дня. Ренуар говорил, что картина должна быть приятной и радостной, неприятного в жизни и так хватает."]}, {"t": "Над вечным покоем", "a": "Исаак Левитан", "y": "1894", "d": "Пейзаж настроения: маленькая церковь и кладбище над бескрайним простором. Левитан называл картину самой своей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:LevitanAboveEternalPeace.jpg", "lic": "Public domain", "by": "Isaac Levitan", "src": "media/img/2a3260c8a1-1000.webp", "w": 1000, "h": 723, "remote": "https://upload.wikimedia.org/wikipedia/commons/0/08/LevitanAboveEternalPeace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Исаак Левитан написал картину в 1894 году на озере Удомля в Тверской губернии. Маленькая деревянная церковь и старое кладбище стоят на высоком берегу, а внизу огромная вода и тяжёлые облака.", "Сам Левитан писал, что в этой картине весь он, его характер. Человеческая жизнь и вечность природы, маленький огонёк в окне церкви и бесконечный простор. Такие картины называют пейзажем настроения: главное не вид, а чувство, которое он вызывает.", "Левитан был учеником Саврасова и другом Чехова. Картину купил Павел Третьяков для своей галереи."]}, {"t": "Голубые танцовщицы", "a": "Эдгар Дега", "y": "около 1897", "d": "Дега любил балет, но показывал его закулисье. Пастель, необычный ракурс — будто подсмотренный кадр.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Degas_-_Blue_Dancers_(1898_Pushkin_Museum).jpg", "lic": "Public domain", "by": "Edgar Degas", "src": "media/img/5f2527d3eb-1000.webp", "w": 1000, "h": 983, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg/1280px-Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Эдгар Дега больше всего любил писать балет, но не спектакль, а закулисье: репетиции, разминку, усталость, поправленные лямки платья.", "Здесь четыре балерины в голубых пачках готовятся к выходу. Мы видим их сверху и сбоку, фигуры обрезаны краем картины, как на случайном снимке. Дега увлекался фотографией и японскими гравюрами, отсюда такие необычные ракурсы.", "Картина сделана пастелью, это цветные мелки. К старости зрение Дега ухудшилось, и он перешёл на пастель, потому что ей можно работать быстро и крупными штрихами. Цвета стали ярче и смелее."]}], "quiz": [{"q": "Откуда взялось слово «импрессионизм»?", "o": ["Из названия картины Моне «Впечатление»", "Из имени художника", "Из названия кафе", "Из манифеста Курбе"], "a": 0, "e": "«Impression, soleil levant» Моне, выставка 1874 года."}, {"q": "Как назывались русские реалисты, возившие выставки по стране?", "o": ["Мирискусники", "Передвижники", "Бубновалетовцы", "Символисты"], "a": 1, "e": "Товарищество передвижных художественных выставок, с 1870 года."}, {"q": "Что главное для импрессиониста?", "o": ["Мораль и долг", "Мгновенное впечатление: свет и воздух", "Геометрия формы", "Религиозный смысл"], "a": 1, "e": "Импрессионисты ловили мимолётное состояние природы."}], "why": ["Во второй половине XIX века художники решили писать то, что видят вокруг, а не мифы и героев. Реалисты показывали жизнь простых людей и социальную несправедливость. Импрессионисты пошли дальше и стали ловить мгновение: свет, воздух, движение. С этого момента живопись становится современной, и почти всё искусство XX века вырастает из импрессионизма."], "groups": [{"h": "Реализм: правда жизни", "p": "Художники рисуют крестьян, рабочих, бедных. Это было вызовом: такие сюжеты считали недостойными больших картин.", "items": [{"t": "Тяжёлый труд", "d": "Простые люди становятся героями больших картин.", "c": "Милле. «Сборщицы колосьев», 1857", "more": ["После жатвы бедным разрешали подбирать оставшиеся на поле колоски. Жан-Франсуа Милле показал трёх крестьянок, которые весь день гнут спину ради горсти зерна. Вдали виден богатый урожай, стога и телега.", "Богатые зрители испугались картины: им показалось, что она призывает к бунту. Милле же просто уважал крестьянский труд и писал фигуры спокойными и величественными, как статуи."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg", "lic": "Public domain", "by": "Jean-François Millet", "src": "media/img/4d54f6ccfc-1000.webp", "w": 1000, "h": 748, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg/1280px-Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Передвижники", "d": "Русские художники возили свои выставки по стране.", "c": "Перов. «Тройка», 1866", "more": ["Трое маленьких учеников мастерового зимой тащат по Москве огромную бочку с водой. Ветер, мороз, сзади помогает подтолкнуть прохожий. Дети измучены.", "В 1870 году русские реалисты создали Товарищество передвижных художественных выставок. Они возили картины по городам, чтобы искусство увидели не только в столицах. Василий Перов был одним из основателей. Мальчика в центре он писал с крестьянского сына Васи, который вскоре умер. Позже мать мальчика пришла к Перову и долго молилась у картины."], "img": {"page": "https://commons.wikimedia.org/wiki/File:%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_(1866).jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/5e295a21ce-1000.webp", "w": 1000, "h": 730, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_%281866%29.jpg/1280px-%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_%281866%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "История как драма", "d": "Исторические картины передвижников показывают характеры и столкновения.", "c": "Суриков. «Боярыня Морозова», 1887", "more": ["В XVII веке в России произошёл раскол церкви. Боярыня Феодосия Морозова отказалась принять новые обряды. Её арестовали и увозят на санях. Она поднимает руку с двумя пальцами, старым крестным знамением, и не сдаётся.", "Толпа реагирует по-разному: кто-то смеётся, кто-то плачет, нищий юродивый повторяет её жест. Василий Суриков долго искал лицо боярыни и нашёл его у своей тётки. Снег он писал с натуры, ходил по сугробам после проезда саней."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Surikov_Boyarynya_Morozova_gtg.jpg", "lic": "Public domain", "by": "Vasily Surikov", "src": "media/img/88b56450b6-1000.webp", "w": 1000, "h": 500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Surikov_Boyarynya_Morozova_gtg.jpg/1280px-Surikov_Boyarynya_Morozova_gtg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Импрессионизм: мгновение и свет", "p": "Художники вышли с мольбертами на улицу и писали быстро, отдельными мазками, чтобы поймать меняющийся свет.", "items": [{"t": "Один мотив, разный свет", "d": "Одно и то же место в разное время дня выглядит по-разному.", "c": "Моне. Руанский собор на закате, 1894", "more": ["Клод Моне снял комнату напротив собора в Руане и написал его фасад больше тридцати раз: утром, днём, вечером, в солнце и в тумане. Он работал над несколькими холстами сразу и менял их, когда менялся свет.", "Камень на этих картинах то голубой, то розовый, то золотой. Моне показывал, что цвет предмета не постоянен: мы видим свет, который от него отражается. Собор здесь почти растворился в воздухе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Claude_Monet_-_Rouen_Cathedral,_Facade_(Sunset).JPG", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/b2bd4bed00-1000.webp", "w": 1000, "h": 1560, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Claude_Monet_-_Rouen_Cathedral%2C_Facade_%28Sunset%29.JPG/1280px-Claude_Monet_-_Rouen_Cathedral%2C_Facade_%28Sunset%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Пруд с кувшинками", "d": "В поздних картинах Моне почти исчезает горизонт.", "c": "Моне. «Кувшинки»", "more": ["В деревне Живерни Моне устроил сад с прудом, японским мостиком и кувшинками и почти тридцать лет писал только его, около 250 картин.", "В поздних работах нет ни неба, ни берега. Только вода, отражения облаков и цветы на поверхности. Зритель как будто смотрит вниз в пруд. К концу жизни Моне почти ослеп, и краски стали ещё ярче и свободнее. Многие видят в этих картинах шаг к абстрактному искусству."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Claude_Monet_-_Seerosen.jpg", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/90db12e7ee-1000.webp", "w": 1000, "h": 741, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Claude_Monet_-_Seerosen.jpg/1280px-Claude_Monet_-_Seerosen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a8", "title": "Постимпрессионизм и модерн", "period": "1880-е — 1910-е", "intro": [], "traits": ["Ван Гог: экспрессивный мазок, яркий цвет", "Сезанн: геометрия формы — отец современного искусства", "Гоген: плоские яркие пятна, экзотика", "Модерн: плавные линии, орнамент, золото", "Символизм: сны, тревога, внутренний мир"], "works": [{"t": "Звёздная ночь", "a": "Винсент ван Гог", "y": "1889", "d": "Написана в лечебнице Сен-Реми. Небо закручено в вихри, кипарис взлетает пламенем — пейзаж души.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vincent van Gogh", "src": "media/img/ffa8e3768f-1000.webp", "w": 1000, "h": 792, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/1280px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1889 году Ван Гог добровольно лёг в лечебницу в городке Сен-Реми на юге Франции. Из окна палаты он видел холмы и деревню. Картину он написал по памяти, днём, в мастерской.", "Небо закручено вихрями, звёзды и луна горят огромными кругами света. Слева тёмный кипарис поднимается, как пламя. Деревня внизу спокойная и тихая, в окнах огоньки. Многие видят в этом контраст бурного внутреннего мира художника и мирной жизни.", "Ван Гог считал картину неудачной. Сейчас это одна из самых узнаваемых картин в мире, она хранится в Нью-Йорке, в Музее современного искусства."]}, {"t": "Гора Сент-Виктуар", "a": "Поль Сезанн", "y": "около 1904", "d": "Сезанн писал эту гору десятки раз, строя пейзаж из цветовых плоскостей. Пикассо называл его «отцом всех нас».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Montagne_Sainte-Victoire,_par_Paul_C%C3%A9zanne_108.jpg", "lic": "Public domain", "by": "Paul Cézanne", "src": "media/img/2ed60c49d5-1000.webp", "w": 1000, "h": 794, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg/1280px-Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Поль Сезанн жил в городе Экс-ан-Прованс и больше шестидесяти раз изобразил гору Сент-Виктуар, которая видна оттуда.", "На поздних картинах гора, деревья и дома сложены из цветовых плоскостей, как из кирпичиков. Тёплые цвета выступают вперёд, холодные голубые уходят назад. Так Сезанн строит пространство цветом, без привычной перспективы.", "Молодые художники ездили к Сезанну учиться. Пикассо назвал его «отцом всех нас». Без Сезанна не было бы кубизма и абстракции."]}, {"t": "Откуда мы? Кто мы? Куда мы идём?", "a": "Поль Гоген", "y": "1897–1898", "d": "Таитянская притча о жизни: читается справа налево, от младенца до старости.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_Gauguin_-_D%27ou_venons-nous.jpg", "lic": "Public domain", "by": "Paul Gauguin", "src": "media/img/42835591cb-1000.webp", "w": 1000, "h": 380, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Paul_Gauguin_-_D%27ou_venons-nous.jpg/1280px-Paul_Gauguin_-_D%27ou_venons-nous.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Поль Гоген бросил работу биржевого маклера, оставил семью и уехал на остров Таити в Тихом океане, чтобы жить простой жизнью. Картину он написал в 1897 году, когда был тяжело болен и думал о смерти.", "Её читают справа налево. Справа младенец, начало жизни. В центре человек срывает плод, это зрелость. Слева старуха, которая ждёт конца. Синий идол на заднем плане символизирует потустороннее.", "Цвета плоские и яркие, без теней, контуры обведены. Гоген учился у японских гравюр и средневековых витражей. Это картина-размышление о смысле жизни, отсюда и название в виде трёх вопросов."]}, {"t": "Поцелуй", "a": "Густав Климт", "y": "1907–1908", "d": "«Золотой период» Климта: настоящее сусальное золото, мужской орнамент из прямоугольников, женский — из кругов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg", "lic": "Public domain", "by": "Gustav Klimt", "src": "media/img/1ff5535fac-1000.webp", "w": 1000, "h": 1003, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg/1280px-The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Венский художник Густав Климт написал картину в 1907–1908 годах. Её сразу купило государство, ещё до окончания выставки.", "Влюблённые стоят на краю цветущего луга, у самого обрыва. Их одежды сливаются в одно золотое облако. У мужчины в узоре прямоугольники, у женщины круги и цветы. Так Климт показал мужское и женское начало.", "Отец Климта был ювелиром и гравёром по золоту, и Климт использовал настоящее сусальное золото. Он вдохновлялся византийскими мозаиками, которые видел в Равенне. Этот период его творчества называют золотым."]}, {"t": "Крик", "a": "Эдвард Мунк", "y": "1893", "d": "Мунк описал миг, когда «почувствовал бесконечный крик природы». Символ тревоги нового века.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edvard_Munch,_1893,_The_Scream,_oil,_tempera_and_pastel_on_cardboard,_91_x_73_cm,_National_Gallery_of_Norway.jpg", "lic": "Public domain", "by": "Edvard Munch", "src": "media/img/2119e6f136-1000.webp", "w": 1000, "h": 1241, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg/1280px-Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Норвежский художник Эдвард Мунк описал в дневнике: он шёл с друзьями на закате, небо стало кроваво-красным, друзья ушли вперёд, а он остановился и почувствовал огромный бесконечный крик, проходящий сквозь природу.", "Фигура на переднем плане не кричит, а слышит крик и зажимает уши. Её лицо похоже на череп. Линии неба, воды и тела изгибаются волнами, только мост прямой.", "Мунк сделал несколько версий: две картины, пастели и литографии. Картина стала символом тревоги современного человека. Это начало экспрессионизма, искусства, где главное передать сильное чувство."]}], "quiz": [{"q": "Кого называют «отцом современного искусства»?", "o": ["Моне", "Сезанна", "Ренуара", "Курбе"], "a": 1, "e": "Сезанн строил форму геометрически — из этого выросли кубизм и абстракция."}, {"q": "Какой стиль около 1900 года любил плавные растительные линии и орнамент?", "o": ["Барокко", "Модерн (ар-нуво)", "Кубизм", "Классицизм"], "a": 1, "e": "Модерн: Климт, Муха, Гауди, Шехтель."}, {"q": "Куда уехал Гоген в поисках первозданной жизни?", "o": ["В Японию", "На Таити", "В Египет", "В Россию"], "a": 1, "e": "Полинезия, Таити — его главные картины написаны там."}], "why": ["К концу XIX века молодым художникам импрессионизма стало мало. Им хотелось передать не только свет, но и чувства, порядок, символы. Каждый пошёл своим путём, и от этих путей разошлись дороги всего искусства XX века: экспрессионизм, кубизм, абстракция. Одновременно возник модерн, первый стиль, который охватил всё сразу, от зданий до афиш и ложек."], "groups": [{"h": "Четыре пути после импрессионизма", "p": "Художников этого времени называют постимпрессионистами. Общего стиля у них нет, у каждого свой метод.", "items": [{"t": "Цвет как чувство", "d": "Ван Гог усиливал цвет, чтобы передать эмоцию.", "c": "Ван Гог. «Подсолнухи», 1888", "more": ["Винсент Ван Гог написал серию подсолнухов в Арле на юге Франции, чтобы украсить комнату для своего друга Гогена. Жёлтый был для него цветом солнца, дружбы и надежды.", "Здесь почти всё жёлтое: фон, ваза, цветы. Краска положена толстыми рельефными мазками, их можно почти потрогать. Одни цветы распустились, другие уже вянут. При жизни Ван Гог продал всего одну картину, а в 1987 году одна из его «Подсолнухов» стала самой дорогой картиной в мире."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vincent_van_Gogh_-_Sunflowers_(1888,_National_Gallery_London).jpg", "lic": "Public domain", "by": "Vincent van Gogh", "src": "media/img/7625bce43c-1000.webp", "w": 1000, "h": 1271, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Vincent_van_Gogh_-_Sunflowers_%281888%2C_National_Gallery_London%29.jpg/1280px-Vincent_van_Gogh_-_Sunflowers_%281888%2C_National_Gallery_London%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Форма как порядок", "d": "Сезанн строил предметы из простых форм.", "c": "Сезанн. «Корзина с яблоками», около 1893", "more": ["Поль Сезанн говорил, что всё в природе можно свести к шару, цилиндру и конусу. Его яблоки тяжёлые и плотные, как будто из камня.", "Посмотрите внимательнее: край стола слева и справа на разной высоте, бутылка наклонена, корзина видна сверху, а стол сбоку. Сезанн показывает предметы сразу с нескольких точек зрения. Через пятнадцать лет Пикассо и Брак разовьют эту идею в кубизм."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg", "lic": "Public domain", "by": "Paul Cézanne", "src": "media/img/11ebd1d159-1000.webp", "w": 1000, "h": 800, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg/1280px-Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Точки вместо мазков", "d": "Сёра складывал картину из мелких цветных точек.", "c": "Сёра. «Воскресный день на острове Гранд-Жатт», 1884–1886", "more": ["Жорж Сёра изучал научные книги о цвете и решил не смешивать краски на палитре. Он ставил рядом крошечные точки чистого цвета, а глаз зрителя сам смешивает их на расстоянии. Этот метод назвали пуантилизмом, от французского point, «точка».", "Работа над картиной заняла два года. Парижане отдыхают на острове посреди Сены. Фигуры застывшие, как статуи, всё очень упорядоченно. Подойдите близко, и картина распадётся на точки, отойдите, и снова сложится."], "img": {"page": "https://commons.wikimedia.org/wiki/File:A_Sunday_on_La_Grande_Jatte,_Georges_Seurat,_1884.jpg", "lic": "Public domain", "by": "Georges Seurat", "src": "media/img/5892cb3721-1000.webp", "w": 1000, "h": 666, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg/1280px-A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Модерн: красота во всём", "p": "Около 1900 года стиль модерн охватил всю Европу. Его узнают по плавным изогнутым линиям, растительным узорам и женским фигурам.", "items": [{"t": "Дом как живое существо", "d": "Архитекторы модерна избегали прямых углов.", "c": "Антонио Гауди. Дом Бальо, Барселона, 1906", "more": ["Испанский архитектор Антонио Гауди перестроил обычный жилой дом для богатого текстильщика. Фасад покрыт мозаикой из цветной керамики и стекла, балконы похожи на маски, колонны на кости.", "Крышу Гауди сделал в виде спины дракона с чешуёй, а башенку с крестом в виде копья святого Георгия, который победил дракона. Внутри почти нет прямых линий, всё плавное, как в морской раковине. Гауди говорил, что прямая линия принадлежит людям, а кривая Богу."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Facade_of_Casa_Batll%C3%B3.jpg", "lic": "CC BY 4.0", "by": "Mattsjc", "src": "media/img/5e58e6ca9e-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Facade_of_Casa_Batll%C3%B3.jpg/1280px-Facade_of_Casa_Batll%C3%B3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Афиша как искусство", "d": "Плакаты модерна собирали как картины.", "c": "Альфонс Муха. Афиша «Жисмонда», 1894", "more": ["На Рождество 1894 года знаменитой актрисе Саре Бернар срочно понадобилась афиша для спектакля. Все художники были в отпуске, и заказ получил никому не известный чех Альфонс Муха.", "Он сделал высокую узкую афишу почти в рост человека: актриса в византийском наряде, мягкие пастельные цвета, мозаичный нимб. Парижане срывали афиши с улиц, чтобы забрать домой. Сара Бернар подписала с Мухой договор на шесть лет, и его стиль стал лицом модерна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg", "lic": "Public domain", "by": "Alphonse Mucha / Adam Cuerden", "src": "media/img/64de535394-1000.webp", "w": 1000, "h": 2829, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg/1280px-Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Русский символизм", "d": "Таинственные образы и мозаичный мазок.", "c": "Врубель. «Демон сидящий», 1890", "more": ["Михаил Врубель иллюстрировал поэму Лермонтова «Демон». Демон у него не злой, а одинокий и печальный, сильный юноша, который тоскует.", "Мазки положены гранями, как кристаллы или мозаика, цветы вокруг похожи на камни. Врубель много лет возвращался к образу Демона, это стало главной темой его жизни. Его считают первым русским художником модерна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vrubel_Demon.jpg", "lic": "Public domain", "by": "Mikhail Vrubel", "src": "media/img/625e6f6d2f-1000.webp", "w": 1000, "h": 531, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Vrubel_Demon.jpg/1280px-Vrubel_Demon.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a9", "title": "Авангард XX века", "period": "1905 — 1930-е", "intro": [], "traits": ["Фовизм: «дикий» чистый цвет", "Кубизм: предмет разложен на грани", "Абстракция: картина без сюжета", "Русский авангард: Малевич (супрематизм), Кандинский", "Сюрреализм: логика сна и подсознания"], "works": [{"t": "Чёрный супрематический квадрат", "a": "Казимир Малевич", "y": "1915", "d": "Манифест супрематизма. На выставке 1915 года Малевич повесил его в «красный угол», где в русском доме висит икона.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kazimir_Malevich,_1915,_Black_Suprematic_Square,_oil_on_linen_canvas,_79.5_x_79.5_cm,_Tretyakov_Gallery,_Moscow.jpg", "lic": "Public domain", "by": "Kazimir Malevich", "src": "media/img/2819ba4ed9-1000.webp", "w": 1000, "h": 1000, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg/1280px-Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Казимир Малевич показал «Чёрный квадрат» в декабре 1915 года в Петрограде на выставке «0,10». Он повесил его под потолком в углу, где в русском доме висит икона.", "Малевич назвал своё направление супрематизм, от латинского «высший». Он считал, что картина не должна изображать предметы. Чёрный квадрат на белом это «ноль форм», точка, с которой начинается новое искусство из чистых фигур и цвета.", "Квадрат на самом деле не идеальный, стороны немного разные. Под чёрной краской учёные нашли другие изображения и надпись карандашом. Малевич потом написал ещё несколько версий квадрата. Картина хранится в Третьяковской галерее."]}, {"t": "Композиция VII", "a": "Василий Кандинский", "y": "1913", "d": "Кандинский мыслил картину как симфонию: цвета звучат, линии играют мелодию. Одна из вершин ранней абстракции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vassily_Kandinsky,_1913_-_Composition_7.jpg", "lic": "Public domain", "by": "Wassily Kandinsky", "src": "media/img/c7747cc859-1000.webp", "w": 1000, "h": 657, "remote": "https://upload.wikimedia.org/wikipedia/commons/b/b4/Vassily_Kandinsky%2C_1913_-_Composition_7.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Василий Кандинский был юристом и в 30 лет бросил карьеру ради живописи. Он одним из первых пришёл к абстракции, картине без узнаваемых предметов.", "Кандинский слышал цвета как музыку: жёлтый звучал для него как труба, синий как виолончель. Свои большие абстракции он называл «композициями», как музыкальные произведения. «Композицию VII» он написал в 1913 году за четыре дня, после тридцати подготовительных эскизов.", "Здесь можно угадать мотивы Апокалипсиса, всемирного потопа и воскресения, но они растворены в вихре цвета. Картина хранится в Третьяковской галерее."]}, {"t": "Композиция с красным, синим и жёлтым", "a": "Пит Мондриан", "y": "1930", "d": "Только прямые линии и три основных цвета. Стиль Мондриана потом разошёлся по дизайну, моде и архитектуре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Piet_Mondriaan,_1930_-_Mondrian_Composition_II_in_Red,_Blue,_and_Yellow.jpg", "lic": "Public domain", "by": "Piet Mondrian", "src": "media/img/fe74d0d700-1000.webp", "w": 1000, "h": 1014, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg/1280px-Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Голландский художник Пит Мондриан начинал с обычных пейзажей деревьев. Постепенно он упрощал их, пока не остались только линии.", "В его зрелых картинах есть только чёрные горизонтальные и вертикальные линии, белый фон и три основных цвета: красный, синий, жёлтый. Мондриан искал гармонию и равновесие, как в музыке или математике.", "Его стиль ушёл далеко за пределы живописи. Платье Ива Сен-Лорана 1965 года, обложки, мебель, плитка в метро повторяют решётки Мондриана."]}, {"t": "Красный конь (Купание красного коня)", "a": "Кузьма Петров-Водкин", "y": "1912", "d": "Конь цвета иконного киновари, сферическая перспектива. Современники видели в нём предчувствие судьбы России.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Bathing_of_a_Red_Horse_(Petrov-Vodkin).jpg", "lic": "Public domain", "by": "Kuzma Petrov-Vodkin", "src": "media/img/30ebf4db21-1000.webp", "w": 1000, "h": 880, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg/1280px-Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Кузьма Петров-Водкин написал картину в 1912 году. Он вырос на Волге, в детстве купал лошадей и потом писал этюды в деревне.", "Конь не настоящего цвета, а ярко-красного, как киноварь на древних иконах. Мальчик на нём хрупкий и задумчивый. Земля и озеро немного выгнуты, будто мы видим кусочек планеты. Петров-Водкин называл это сферической перспективой.", "Через два года началась Первая мировая война, потом революция. Многие увидели в красном коне предчувствие судьбы России. Сам художник говорил, что просто учился у икон чистому цвету."]}], "quiz": [{"q": "Как называется направление Малевича?", "o": ["Кубизм", "Супрематизм", "Фовизм", "Сюрреализм"], "a": 1, "e": "Супрематизм — от лат. supremus, «высший»: превосходство чистой формы и цвета."}, {"q": "Что такое абстракция?", "o": ["Портрет в профиль", "Живопись без изображения узнаваемых предметов", "Пейзаж ночью", "Копия античной статуи"], "a": 1, "e": "Абстракция говорит формой и цветом, как музыка звуком."}, {"q": "Кубисты…", "o": ["Писали только кубы", "Раскладывали предмет на грани, показывая с разных сторон", "Писали на пленэре", "Копировали иконы"], "a": 1, "e": "Пикассо и Брак показывали предмет одновременно с нескольких точек зрения."}], "why": ["Начало XX века перевернуло искусство. Фотография научилась точно изображать мир, и художникам больше не нужно было копировать реальность. Они начали искать новый язык: чистый цвет, разложенные формы, картины совсем без изображения. Многое в современном дизайне, логотипах и архитектуре выросло из авангарда, и русские художники сыграли в нём одну из главных ролей."], "groups": [{"h": "Освобождение цвета и формы", "p": "Цвет и форма больше не обязаны быть похожими на настоящие.", "items": [{"t": "Фовизм: дикий цвет", "d": "Цвет выбирают по чувству, а не по правде.", "c": "Анри Матисс. «Женщина в шляпе», 1905", "more": ["Анри Матисс написал портрет своей жены. Лицо у неё зелёное, розовое и жёлтое, фон из пятен. На выставке 1905 года критик назвал Матисса и его друзей «дикими», по-французски fauves. Так появилось слово «фовизм».", "Матисс не хотел сделать жену некрасивой. Он считал, что цвет должен передавать радость и силу, а не точный оттенок кожи. Позже его картины «Танец» и «Музыку» заказал русский коллекционер Сергей Щукин, и сейчас они в Эрмитаже."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Matisse-Woman-with-a-Hat.jpg", "lic": "Public domain", "by": "Henri Matisse", "src": "media/img/d858d65f04-1000.webp", "w": 1000, "h": 1361, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Matisse-Woman-with-a-Hat.jpg/1280px-Matisse-Woman-with-a-Hat.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Экспрессионизм", "d": "Цвет и форма передают внутренний мир.", "c": "Франц Марк. «Синий конь», 1911", "more": ["Немецкий художник Франц Марк считал, что животные чище и честнее людей. Каждому цвету он приписывал смысл: синий означал мужское, духовное начало, жёлтый женское и радостное.", "Вместе с Кандинским он основал группу «Синий всадник». Марк погиб на Первой мировой войне в 1916 году, ему было 36 лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Marc,_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Franz Marc", "src": "media/img/f27edba562-1000.webp", "w": 1000, "h": 1335, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Marc%2C_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg/1280px-Marc%2C_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Футуризм: скорость", "d": "Итальянцы восхищались машинами и скоростью.", "c": "Боччони. «Уникальные формы непрерывности в пространстве», 1913", "more": ["Футуристы, от латинского «будущее», объявили, что гоночный автомобиль прекраснее античной статуи. Они хотели показать в искусстве движение и скорость нового века.", "Скульптура Умберто Боччони изображает шагающего человека, но воздух как будто обтекает и рвёт его форму. Это напоминает фотографию на длинной выдержке. Изображение статуи сегодня есть на итальянской монете в 20 евроцентов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg", "lic": "CC0", "by": "Umberto Boccioni", "src": "media/img/e8d3b6e1bd-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg/1280px-Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Русский авангард", "p": "В 1910–1920-х годах Россия стала одним из центров нового искусства. После революции авангард пошёл в плакаты, архитектуру и дизайн.", "items": [{"t": "Плакат из геометрии", "d": "Простые фигуры рассказывают политическую историю.", "c": "Эль Лисицкий. «Клином красным бей белых», 1919", "more": ["Во время Гражданской войны Лазарь Лисицкий, ученик Малевича, сделал плакат из одних фигур. Красный треугольник, Красная армия, врезается в белый круг, армию белых.", "Здесь нет ни одного человека, но смысл понятен с первого взгляда. Такой язык простых форм, цвета и коротких надписей потом перешёл в рекламу, логотипы и графический дизайн всего мира."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Beat_the_Whites_with_the_Red_Wedge.jpg", "lic": "Public domain", "by": "El Lissitzky", "src": "media/img/c132978d7b-1000.webp", "w": 1000, "h": 819, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Beat_the_Whites_with_the_Red_Wedge.jpg/1280px-Beat_the_Whites_with_the_Red_Wedge.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Башня-мечта", "d": "Архитектура будущего, которую так и не построили.", "c": "Модель башни Татлина, реконструкция", "more": ["В 1919 году Владимир Татлин спроектировал памятник Третьему Интернационалу: наклонную спиральную башню из стали высотой 400 метров, выше Эйфелевой. Внутри должны были вращаться залы с разной скоростью: раз в год, раз в месяц, раз в день.", "Построить её было невозможно, в стране не хватало даже металла. Остались только модели. Но башня стала символом авангарда: искусство должно было не украшать жизнь, а строить новый мир."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Model_of_Tatlin_Tower,_Royal_Academy,_London,_27_Feb_2012.jpg", "lic": "CC BY-SA 3.0", "by": "TobyJ", "src": "media/img/46908d9acb-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Model_of_Tatlin_Tower%2C_Royal_Academy%2C_London%2C_27_Feb_2012.jpg/1280px-Model_of_Tatlin_Tower%2C_Royal_Academy%2C_London%2C_27_Feb_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}], "music": [{"id": "m0", "title": "Как слушать музыку", "period": "Азбука", "intro": [], "traits": ["Мелодия, ритм, гармония, тембр", "Мажор — светло, минор — грустно", "Темп: адажио (медленно), аллегро (быстро), престо (очень быстро)", "Динамика: пиано (тихо), форте (громко)", "Формы: симфония, соната, концерт, опера, балет"], "works": [{"t": "Симфония № 5, часть 1", "a": "Людвиг ван Бетховен", "y": "1808", "d": "Четыре ноты «та-та-та-там» — самая узнаваемая тема в истории. Это мотив: короткая ячейка, из которой вырастает вся часть. Минор, аллегро, форте.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor,_op._67_-_i._allegro_con_brio.ogg", "lic": "Public domain", "by": "Ludwig van Beethoven", "src": "media/audio/e4d31e8acd.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e6/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg.mp3"}, "story": ["Это пример минора, аллегро и форте одновременно. Послушайте первые четыре ноты: три коротких и одна длинная. Это мотив, короткая музыкальная ячейка. Из неё Бетховен выращивает всю первую часть, повторяя мотив на разной высоте и у разных инструментов.", "Бетховен написал симфонию в 1808 году, когда уже начал глохнуть. Его секретарь потом рассказывал, будто композитор назвал начало «судьбой, которая стучится в дверь». Правда это или нет, неизвестно, но так её часто называют.", "Во время Второй мировой войны этот мотив использовали британцы: ритм «три коротких, один длинный» на азбуке Морзе означает букву V, Victory, победа."]}, {"t": "Сюита для виолончели № 1, Прелюдия", "a": "Иоганн Себастьян Бах", "y": "около 1720", "d": "Один инструмент — и целый мир. Послушайте тембр виолончели: тёплый, близкий к человеческому голосу. Мажор.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Cello_Suite_no._1_in_G_major,_BWV_1007_-_I._Pr%C3%A9lude.ogg", "lic": "Public domain", "by": "Bach, Johann-Sebastian.", "src": "media/audio/dd1ea7ee35.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg.mp3"}, "story": ["Это пример тембра и мажора. Здесь играет один инструмент, без оркестра. Слышите, как виолончель одна создаёт и мелодию, и гармонию? Бах выстроил её из ломаных аккордов, их звуки идут не вместе, а один за другим.", "Бах написал шесть сюит для виолончели около 1720 года. Почти двести лет их считали упражнениями для учеников. В 1890 году тринадцатилетний испанец Пабло Казальс нашёл старые ноты в магазине в Барселоне, двенадцать лет изучал и потом впервые сыграл на концертах. С тех пор это одна из главных вершин для каждого виолончелиста."]}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Пример темпа «престо»: стремительные пассажи изображают жужжание. Это музыкальная звукопись.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rimsky-Korsakov_-_flight_of_the_bumblebee.oga", "lic": "Public domain", "by": "Composition: Nikolai Rimsky-Korsakov. Performer: US Army Band", "src": "media/audio/0eeda89ef7.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c0/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga.mp3"}, "story": ["Это пример темпа престо и звукописи. Музыка изображает жужжание шмеля: очень быстрые ноты почти без остановки, мелодия вьётся вверх и вниз, как полёт насекомого.", "Пьеса взята из оперы Николая Римского-Корсакова «Сказка о царе Салтане» по Пушкину. Князь Гвидон превращается в шмеля, чтобы тайно полететь к отцу. В опере это короткий эпизод, но его так полюбили, что теперь исполняют отдельно на любых инструментах, от скрипки до тубы, чтобы показать быстроту пальцев."]}], "quiz": [{"q": "Как называется «окраска» звука, по которой мы отличаем скрипку от трубы?", "o": ["Темп", "Тембр", "Ритм", "Лад"], "a": 1, "e": "Тембр — индивидуальный цвет звучания инструмента или голоса."}, {"q": "Что означает «аллегро»?", "o": ["Медленно", "Тихо", "Быстро, весело", "Громко"], "a": 2, "e": "Allegro — «весело», то есть скоро. Медленно — adagio."}, {"q": "Как называется крупное сочинение для оркестра из нескольких частей?", "o": ["Соната", "Симфония", "Романс", "Этюд"], "a": 1, "e": "Симфония — обычно четыре части. Соната — для одного-двух инструментов."}, {"q": "Какой лад чаще звучит светло и радостно?", "o": ["Минор", "Мажор", "Хроматика", "Пентатоника"], "a": 1, "e": "Мажор — светлый, минор — печальный или драматичный."}], "why": ["В концертных программах и рецензиях пишут: «симфония в трёх частях», «тема у гобоя», «аллегро», «соль минор». Без этих слов музыку можно только слушать, а с ними можно понимать, что происходит и почему это действует. Здесь собраны главные термины и инструменты, а внизу три записи, на которых их легко услышать."], "groups": [{"h": "Из чего состоит музыка", "p": "Любое произведение можно разобрать на несколько составляющих. Когда вы слышите их по отдельности, музыка перестаёт быть просто «приятным шумом».", "items": [{"t": "Мелодия и нотная запись", "d": "Мелодия это то, что можно напеть. Её записывают нотами.", "c": "Средневековая запись хорала", "more": ["Мелодия это последовательность звуков разной высоты, которая складывается в узнаваемую фразу. Чтобы её сохранить, люди придумали ноты: значки на линейках, где положение показывает высоту звука, а форма его длительность.", "Современные ноты выросли из средневековых значков над текстом молитв. Сейчас запись почти одинакова во всём мире, поэтому музыкант из Японии сыграет пьесу бразильского композитора, ни разу его не услышав."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Te_Deum_(Gregorian).png", "lic": "Public domain", "by": "ancient", "src": "media/img/b8162769ee-1000.webp", "w": 1000, "h": 4955, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Te_Deum_%28Gregorian%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Ритм и темп", "d": "Ритм это рисунок длинных и коротких звуков, темп это скорость.", "c": "Метроном Мельцеля, начало XIX века", "more": ["Темп обозначают итальянскими словами: адажио значит медленно, анданте шагом, аллегро быстро, престо очень быстро. Итальянский язык стал языком музыки ещё в эпоху барокко, и эта традиция осталась.", "В 1815 году Иоганн Мельцель запатентовал метроном, маятник, который отстукивает заданную скорость. Бетховен одним из первых стал ставить в нотах точные цифры метронома, чтобы исполнители не путали темп."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Metronome_M%C3%A4lzel_1.jpg", "lic": "CC BY-SA 3.0", "by": "Myself", "src": "media/img/a2fe781364-1000.webp", "w": 1000, "h": 1646, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Metronome_M%C3%A4lzel_1.jpg/1280px-Metronome_M%C3%A4lzel_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Лад: мажор и минор", "d": "Мажор обычно звучит светло, минор печально или тревожно.", "c": "Скрипка Страдивари в музее Оксфорда", "more": ["Лад это набор звуков, из которых построена музыка, и их отношения друг к другу. В европейской музыке главные два лада: мажор и минор. Разница между ними в одном звуке, но слух сразу её замечает.", "Попробуйте сравнить внизу «Полёт шмеля» и прелюдию Баха. Бах в мажоре, звучит ясно и спокойно. Симфония Бетховена в миноре и звучит грозно. Композиторы выбирают лад, чтобы задать настроение."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Messiah_Stradivarius_ashmolean.JPG", "lic": "CC BY-SA 4.0", "by": "Geni", "src": "media/img/865ff2cb34-1000.webp", "w": 1000, "h": 2136, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Messiah_Stradivarius_ashmolean.JPG/1280px-Messiah_Stradivarius_ashmolean.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Инструменты оркестра", "p": "Симфонический оркестр делится на четыре группы. Каждая отвечает за свой тембр, то есть «окраску» звука.", "items": [{"t": "Струнные", "d": "Скрипки, альты, виолончели, контрабасы. Основа оркестра.", "c": "Скрипка Страдивари «Мессия», 1716", "more": ["Струнных в оркестре больше всего, около шестидесяти процентов музыкантов. Звук рождается, когда смычок из конского волоса трётся о струну. Скрипки играют высокие мелодии, контрабасы держат низ.", "Итальянский мастер Антонио Страдивари сделал около тысячи инструментов в XVII и XVIII веках. Эта скрипка почти не звучала на концертах и сохранилась как новая. Почему скрипки Страдивари так хороши, до конца не разгадано до сих пор."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Messiah_Stradivarius.jpg", "lic": "CC BY-SA 3.0", "by": "User:Pruneau", "src": "media/img/1e00443452-1000.webp", "w": 1000, "h": 2657, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1d/Messiah_Stradivarius.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Деревянные духовые", "d": "Флейта, гобой, кларнет, фагот. Яркие, певучие голоса.", "c": "Гобой", "more": ["Звук рождается из воздуха, который музыкант вдувает в трубку. У гобоя и фагота воздух проходит через двойную тростниковую пластинку, трость, поэтому звук немного носовой и выразительный.", "Перед концертом весь оркестр настраивается по ноте «ля», которую играет гобой. У него устойчивый и хорошо слышный звук. В «Лебедином озере» знаменитую тему лебедей поручено именно гобою."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Oboe_modern.jpg", "lic": "CC BY-SA 3.0", "by": "Hustvedt, Editor/Bearbeiter der Version vom 11.März 2022 = User:Gisbert K", "src": "media/img/f9173648fb-1000.webp", "w": 1000, "h": 703, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Oboe_modern.jpg/1280px-Oboe_modern.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Медные духовые", "d": "Трубы, валторны, тромбоны, туба. Самые громкие.", "c": "Валторна", "more": ["Медные инструменты звучат, когда музыкант вибрирует губами в мундштук. Трубы ярко сияют, тромбоны торжественны, валторна мягкая, её звук похож на охотничий рог.", "Валторна действительно произошла от охотничьего рога. Её трубка, если её размотать, длиной почти четыре метра. Медные дают оркестру мощь в кульминациях, как в «Полёте валькирий» Вагнера."], "img": {"page": "https://commons.wikimedia.org/wiki/File:French_horn_front.png", "lic": "CC BY 2.5", "by": "BenP", "src": "media/img/e0b0238eaa-1000.webp", "w": 1000, "h": 750, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/63/French_horn_front.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Ударные", "d": "Литавры, барабаны, тарелки. Ритм и яркие акценты.", "c": "Литавры", "more": ["Литавры это большие медные котлы, затянутые кожей. В отличие от простого барабана, их можно настроить на определённую ноту, педалью натягивая мембрану.", "В «Сюрпризе» Гайдна удар литавр разбудил дремлющую публику, а в «Болеро» Равеля малый барабан пятнадцать минут отбивает один и тот же ритм. Ударные отвечают за пульс и за неожиданность."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Munich_-_A_standard_set_of_timpani_Percussion_-_5647.jpg", "lic": "CC BY-SA 3.0", "by": "Jorge Royan", "src": "media/img/2e23c79307-1000.webp", "w": 1000, "h": 657, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Munich_-_A_standard_set_of_timpani_Percussion_-_5647.jpg/1280px-Munich_-_A_standard_set_of_timpani_Percussion_-_5647.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Главные формы", "p": "Форма это то, как устроено произведение. По названию часто сразу понятно, кто играет и сколько длится музыка.", "items": [{"t": "Симфония и концерт", "d": "Большое сочинение для оркестра, концерт ещё и с солистом.", "c": "Золотой зал Музикферайн в Вене", "more": ["Симфония обычно состоит из четырёх частей с разным темпом: быстрая, медленная, танцевальная и быстрый финал. В концерте с оркестром соревнуется солист, например пианист или скрипач, и у него есть каденция, место для виртуозного соло.", "Золотой зал в Вене открыли в 1870 году. Здесь каждый Новый год проходит знаменитый концерт Венского филармонического оркестра, его смотрят по телевизору десятки миллионов людей."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vienna_-_Musikverein.jpg", "lic": "CC BY-SA 2.0", "by": "roger4336", "src": "media/img/88f077cfcd-1000.webp", "w": 1000, "h": 661, "remote": "https://upload.wikimedia.org/wikipedia/commons/b/b1/Vienna_-_Musikverein.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Опера и балет", "d": "Опера это драма, где поют. Балет это драма, где танцуют.", "c": "Большой театр в Москве", "more": ["В опере есть арии, сольные песни героев, речитативы, где действие движется вперёд, и хоры. Балет рассказывает историю без слов, только музыкой и движением.", "Большой театр работает с 1776 года, нынешнее здание с колесницей Аполлона над портиком построено в 1856-м. Здесь в 1877 году прошла первая постановка «Лебединого озера» Чайковского."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Moscow_-_2025_-_Facade_of_Big_Theatre_(1).jpg", "lic": "CC BY 4.0", "by": "Юрий Д.К.", "src": "media/img/63b78d39f8-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Moscow_-_2025_-_Facade_of_Big_Theatre_%281%29.jpg/1280px-Moscow_-_2025_-_Facade_of_Big_Theatre_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "m1", "title": "Средневековье", "period": "V — XIV век", "intro": [], "traits": ["Григорианский хорал: одноголосие, латынь, без инструментов", "Музыка служит молитве", "Рождение нотной записи (Гвидо д’Ареццо)", "Рождение многоголосия (полифонии)", "Светская музыка трубадуров и менестрелей"], "works": [{"t": "Rorate caeli (григорианский хорал)", "a": "Анонимный церковный распев", "y": "Средние века", "d": "Адвентский распев «Кропите, небеса». Одна мелодическая линия, свободный ритм — так звучали храмы тысячу лет назад.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rorate_Caeli_~_Gregorian_Chant.ogg", "lic": "CC BY-SA 4.0", "by": "Inritter", "src": "media/audio/f768d50581.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f8/Rorate_Caeli_~_Gregorian_Chant.ogg/Rorate_Caeli_~_Gregorian_Chant.ogg.mp3"}, "story": ["Хорал назван в честь папы Григория Великого, жившего около 600 года. Легенда говорит, что голубь Святого Духа напевал ему мелодии на ухо. На самом деле хоралы складывались несколько веков разными певцами.", "Послушайте особенности: один голос, а если поют многие, то в унисон, одну и ту же мелодию. Нет инструментов, нет чёткого ритма, мелодия свободно следует за словами латинской молитвы.", "«Rorate caeli» значит «Кропите, небеса». Это песнопение поют в предрождественские недели адвента. В храме с гулким эхом такое пение звучит, будто доносится издалека."]}, {"t": "O frondens virga", "a": "Хильдегарда Бингенская", "y": "XII век", "d": "Хильдегарда — аббатиса, мистик, учёный и одна из первых композиторов, чьё имя мы знаем.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:O_frondens.ogg", "lic": "CC BY-SA 3.0", "by": "Hildegard of Bingen / user:Makemi", "src": "media/audio/f542345302.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/3/37/O_frondens.ogg/O_frondens.ogg.mp3"}, "story": ["Это песнопение Хильдегарды Бингенской, около 1150 года. «O frondens virga» значит «О цветущая ветвь», так она называет Деву Марию.", "Сравните с григорианским хоралом. Мелодия Хильдегарды взлетает гораздо выше и опускается ниже, она гибкая и почти экстатичная. Хильдегарда не училась музыке по правилам, и её песни звучат свободнее обычных церковных."]}, {"t": "Sumer is icumen in («Лето пришло»)", "a": "Анонимный английский автор", "y": "около 1260", "d": "Один из древнейших светских канонов: голоса вступают по очереди с одной мелодией. Песня о весне и кукушке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sumer_Is_Icumen_In_(13th_century_English_round).ogg", "lic": "CC BY-SA 4.0", "by": "Brandtnight2000", "src": "media/audio/d409d413f1.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/06/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg.mp3"}, "story": ["Это одна из старейших светских песен, записанных в Англии, около 1260 года. Её текст на старом английском: «Лето пришло, громко пой, кукушка!»", "Это канон, или ротá. Голоса вступают по очереди с одной и той же мелодией, и получается многоголосие. Под ними ещё два голоса повторяют короткую фразу. Всего до шести голосов, для XIII века это очень сложно.", "Рукопись хранилась в аббатстве в Рединге. Под английскими словами монах вписал латинский текст про Христа, чтобы песню можно было петь и в монастыре."]}], "quiz": [{"q": "Что такое григорианский хорал?", "o": ["Оркестровая симфония", "Одноголосное церковное пение на латыни", "Танец при дворе", "Опера на библейский сюжет"], "a": 1, "e": "Названо в честь папы Григория I."}, {"q": "Кто дал нотам названия, от которых произошли «до-ре-ми»?", "o": ["Бах", "Гвидо д’Ареццо", "Палестрина", "Моцарт"], "a": 1, "e": "Около 1000 года, по первым слогам строк гимна св. Иоанну."}, {"q": "Как называется многоголосие, где каждый голос ведёт свою мелодию?", "o": ["Монодия", "Полифония", "Гомофония", "Унисон"], "a": 1, "e": "Полифония — «много звуков»."}], "why": ["Почти тысячу лет главной музыкой Европы было церковное пение. Именно монахи придумали ноты, по которым музыканты играют до сих пор, и названия «до, ре, ми». А когда к одному голосу добавили второй и третий, появилось многоголосие, без которого не было бы ни Баха, ни симфоний, ни поп-песен с аккордами."], "groups": [{"h": "Как появились ноты", "p": "Раньше музыку передавали только на слух, от учителя к ученику. Монахам нужно было, чтобы молитвы звучали одинаково во всех монастырях.", "items": [{"t": "Невмы", "d": "Первые значки над текстом молитвы показывали, куда идёт мелодия.", "c": "Григорианский хорал «Ave maris stella»", "more": ["Сначала над словами молитвы рисовали маленькие крючки и точки, невмы. Они напоминали певцу, где голос поднимается, а где опускается, но точную высоту не показывали.", "Потом стали проводить горизонтальную линию, затем две, три и четыре. Так появился нотный стан. В церковных книгах до сих пор пишут хоралы на четырёх линиях квадратными нотами, как в Средние века."], "img": {"page": "https://commons.wikimedia.org/wiki/File:AveMarisStellaChant.jpg", "lic": "Public domain", "by": "Ascribed to St. Gregory. The Roman Antiphonary dates back to earlier than 1570.", "src": "media/img/08cb61f6a8-1000.webp", "w": 1000, "h": 178, "remote": "https://upload.wikimedia.org/wikipedia/commons/f/f8/AveMarisStellaChant.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Рука Гвидо", "d": "Учитель пения придумал названия нот и способ их запоминать.", "c": "«Гвидонова рука»", "more": ["Около 1025 года итальянский монах Гвидо д’Ареццо преподавал пение в соборе. Он заметил, что каждая строчка гимна святому Иоанну начинается на ступеньку выше предыдущей: ut, re, mi, fa, sol, la. Первые слоги стали названиями нот.", "Позже ut заменили на более удобное do, а добавили si. Чтобы ученики запоминали звуки, Гвидо привязал их к суставам пальцев на ладони. Учитель показывал на палец, ученик пел нужную ноту. Благодаря его методу петь научались за месяцы, а не за десять лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Guidonian_hand.jpg", "lic": "Public domain", "by": "", "src": "media/img/a2f8db0509-1000.webp", "w": 1000, "h": 1173, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Guidonian_hand.jpg/1280px-Guidonian_hand.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Кто сочинял и пел", "p": "Большинство авторов средневековой музыки неизвестны. Но некоторые имена дошли до нас.", "items": [{"t": "Хильдегарда Бингенская", "d": "Аббатиса, учёный и одна из первых композиторов, чьё имя известно.", "c": "Хильдегарда записывает видения", "more": ["Хильдегарда жила в Германии в XII веке. Она руководила монастырём, писала книги о медицине и растениях, переписывалась с императором и папой. При этом сочинила около семидесяти песнопений.", "Её мелодии необычные: широкие, взлетающие высоко вверх, гораздо свободнее обычного хорала. Она говорила, что музыку ей открывают видения. На этой миниатюре она записывает их на восковых табличках, а рядом монах переписывает текст."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Hildegard_von_Bingen.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/fb0c6493e7-1000.webp", "w": 1000, "h": 1462, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Hildegard_von_Bingen.jpg/1280px-Hildegard_von_Bingen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Миннезингеры и трубадуры", "d": "Рыцари-поэты пели о любви при дворах.", "c": "Вальтер фон дер Фогельвейде, Манесский кодекс", "more": ["Вне монастырей была своя музыка. На юге Франции её сочиняли трубадуры, в Германии миннезингеры. Это были часто знатные рыцари, которые пели о прекрасной даме, о весне, о походах.", "Манесский кодекс, книгу их песен, сделали в Цюрихе около 1300 года. На каждой странице портрет певца. Вальтер фон дер Фогельвейде сидит на камне в задумчивой позе, точно так, как описал себя в одном из стихотворений."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Codex_Manesse_Walther_von_der_Vogelweide.jpg", "lic": "Public domain", "by": "Meister des Codex Manesse", "src": "media/img/027ff268ad-1000.webp", "w": 1000, "h": 1520, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1a/Codex_Manesse_Walther_von_der_Vogelweide.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "m2", "title": "Возрождение", "period": "XV — XVI век", "intro": [], "traits": ["Хоровая полифония a cappella (без инструментов)", "Равноправие голосов, мягкая гармония", "Месса и мотет — церковные жанры", "Мадригал — светская песня о любви", "Лютня — главный домашний инструмент"], "works": [{"t": "Vestiva i colli", "a": "Джованни Палестрина", "y": "1566", "d": "Светский мадригал церковного мастера. Голоса текут спокойно, без резких скачков — фирменная ясность Палестрины.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg", "lic": "CC BY 4.0", "by": "Palestrina", "src": "media/audio/4ca1e6fd73.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/de/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg.mp3"}, "story": ["Это мадригал Палестрины 1566 года, его название значит «Одевала холмы». Мадригал это светская многоголосная песня на итальянские стихи о любви и природе.", "Послушайте, как голоса вступают по очереди и движутся плавно, без резких скачков. Ни один голос не главный. Этот мадригал был так популярен, что другие композиторы делали из него переложения для лютни и органа."]}, {"t": "Agnus Dei", "a": "Джованни Палестрина", "y": "XVI век", "d": "Часть мессы. Прислушайтесь: голоса вступают друг за другом, как волны.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg", "lic": "Public domain", "by": "Palestrina", "src": "media/audio/57adbf9b3d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c5/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg.mp3"}, "story": ["«Agnus Dei», «Агнец Божий», это последняя часть мессы. Палестрина написал её для праздника апостолов.", "Голоса вступают один за другим, повторяя мелодию, как эхо, а потом сливаются. Такой приём называют имитацией. Звучание мягкое, без острых созвучий: Палестрина избегал всего, что могло отвлечь от молитвы."]}, {"t": "Greensleeves («Зелёные рукава»)", "a": "Английская народная песня", "y": "XVI век", "d": "Самая знаменитая мелодия елизаветинской Англии. Легенда приписывает её Генриху VIII.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Greensleeves_Correct_Melody.ogg", "lic": "Public domain", "by": "Traditional English folk song", "src": "media/audio/3ca8312013.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Greensleeves_Correct_Melody.ogg/Greensleeves_Correct_Melody.ogg.mp3"}, "story": ["Это английская песня XVI века о возлюбленной в платье с зелёными рукавами, которая отвергает певца. Её впервые записали в 1580 году.", "Легенда говорит, что песню сочинил король Генрих VIII для Анны Болейн. Историки сомневаются: мелодия построена по итальянской схеме, которая пришла в Англию уже после смерти короля.", "Песня стала такой популярной, что о ней упоминает Шекспир в комедии «Виндзорские насмешницы». Сегодня её мелодию знают по всему миру, часто как рождественскую песню."]}, {"t": "Cruda Amarilli", "a": "Клаудио Монтеверди", "y": "1605", "d": "Поздний мадригал с острыми диссонансами — Монтеверди уже на пороге барокко.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Monteverdi_-_cruda_amarilli.ogg", "lic": "CC BY-SA 2.0", "by": "", "src": "media/audio/0b27d76300.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Monteverdi_-_cruda_amarilli.ogg/Monteverdi_-_cruda_amarilli.ogg.mp3"}, "story": ["«Жестокая Амариллида» это мадригал Монтеверди 1605 года на стихи из пасторали. Пастух упрекает возлюбленную в жестокости.", "Послушайте острые, будто фальшивые созвучия на словах о боли. Теоретик Джованни Артузи напечатал резкую критику, приведя эти места как пример ошибок. Монтеверди ответил, что намеренно нарушает правила ради выражения чувств. С этого спора начинается музыка барокко."]}], "quiz": [{"q": "Что значит «a cappella»?", "o": ["С оркестром", "Пение без инструментального сопровождения", "Очень быстро", "Для органа"], "a": 1, "e": "Буквально «как в капелле» — только голоса."}, {"q": "Кто — главный мастер церковной полифонии Возрождения?", "o": ["Вивальди", "Палестрина", "Гайдн", "Шопен"], "a": 1, "e": "Палестрина, Рим, XVI век."}, {"q": "Мадригал — это…", "o": ["Церковная месса", "Светская многоголосная песня", "Танец", "Инструмент"], "a": 1, "e": "Мадригалы пели о любви и природе."}], "why": ["В эпоху Возрождения композиторы научились сплетать несколько голосов в прозрачную ткань, где все звучат одинаково важно. Тогда же появилось нотопечатание, и музыку стали покупать и играть дома. А в самом конце эпохи в Италии родилась опера. Без этих открытий не было бы классической музыки."], "groups": [{"h": "Музыка в церкви", "p": "Главный жанр эпохи это месса, части католической службы, положенные на многоголосную музыку.", "items": [{"t": "Палестрина", "d": "Римский композитор, образец церковного многоголосия.", "c": "Джованни Пьерлуиджи да Палестрина", "more": ["Палестрина получил имя от городка рядом с Римом, где родился около 1525 года. Он руководил хорами в главных соборах Рима и написал больше ста месс.", "В середине XVI века церковь обсуждала, не запретить ли сложное многоголосие: слова молитвы тонули в переплетении голосов. Есть легенда, что Палестрина спас музыку, написав мессу, где каждое слово слышно. Скорее всего, это легенда, но его стиль действительно стал образцом: ясный, спокойный, с плавными голосами."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Giovanni_Pierluigi_da_Palestrina_by_Antonio_Locatelli_(before_1936)_-_Archivio_Storico_Ricordi_ICON010758.jpg", "lic": "CC BY-SA 4.0", "by": "Antonio Locatelli", "src": "media/img/746804f8c6-1000.webp", "w": 1000, "h": 1147, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c4/Giovanni_Pierluigi_da_Palestrina_by_Antonio_Locatelli_%28before_1936%29_-_Archivio_Storico_Ricordi_ICON010758.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Музыка дома", "p": "Богатые горожане хотели музицировать сами. Для них печатали ноты песен и пьес.", "items": [{"t": "Первые печатные ноты", "d": "В 1501 году в Венеции напечатали первый сборник нот.", "c": "«Одекатон» Петруччи, 1501", "more": ["Книгопечатание Гутенберга появилось около 1450 года, но ноты печатать было сложнее: нужно совместить линейки, ноты и текст. Венецианец Оттавиано Петруччи придумал печатать их в три прохода.", "Его сборник «Одекатон», то есть «сто песен», содержал многоголосные песни лучших композиторов. Теперь музыку можно было купить, как книгу, и любой грамотный музыкант мог её исполнить. Это изменило музыкальную жизнь так же, как интернет в наше время."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Petrucci-odhecaton-front.jpg", "lic": "Public domain", "by": "", "src": "media/img/3de8808521-1000.webp", "w": 1000, "h": 753, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Petrucci-odhecaton-front.jpg/1280px-Petrucci-odhecaton-front.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Лютня", "d": "Главный домашний инструмент эпохи.", "c": "Караваджо. «Лютнист», около 1596", "more": ["Лютня с изогнутым грифом пришла в Европу от арабов, её арабское название «аль-уд». На ней аккомпанировали пению, играли танцы и переложения песен.", "На картине Караваджо, которая хранится в Эрмитаже, юноша поёт мадригал под лютню. На столе раскрыты настоящие ноты, исследователи даже определили, какая песня: «Вы знаете, что я вас люблю». Скрипка лежит рядом, она скоро вытеснит лютню."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Lute_Player-Caravaggio_(Hermitage).jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/8fc0fe526f-1000.webp", "w": 1000, "h": 792, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/The_Lute_Player-Caravaggio_%28Hermitage%29.jpg/1280px-The_Lute_Player-Caravaggio_%28Hermitage%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Рождение оперы", "p": "Около 1600 года во Флоренции решили возродить античную трагедию, где, как думали, актёры пели. Так появилась опера.", "items": [{"t": "Монтеверди", "d": "Композитор, который соединил Возрождение и барокко.", "c": "Бернардо Строцци. Портрет Монтеверди, около 1630", "more": ["Клаудио Монтеверди служил при дворе герцогов Гонзага в Мантуе, а позже руководил музыкой в соборе Святого Марка в Венеции. Он писал мадригалы с острыми, «неправильными» созвучиями, чтобы передать боль и страсть слов. Критики ругали его за нарушение правил.", "Он отвечал, что правила должны служить словам и чувствам. Эта идея стала основой оперы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bernardo_Strozzi_-_Claudio_Monteverdi_(c.1630).jpg", "lic": "Public domain", "by": "Bernardo Strozzi", "src": "media/img/52e3705096-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Bernardo_Strozzi_-_Claudio_Monteverdi_%28c.1630%29.jpg/1280px-Bernardo_Strozzi_-_Claudio_Monteverdi_%28c.1630%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Первая великая опера", "d": "«Орфей» 1607 года до сих пор идёт на сценах.", "c": "Титульный лист «Орфея», 1609", "more": ["Опера «Орфей» Монтеверди рассказывает миф о певце, который спустился в подземное царство за погибшей женой Эвридикой. Его музыка смягчила даже стражей ада.", "Монтеверди использовал большой для своего времени оркестр: скрипки, трубы, тромбоны, орган, арфу, и каждому персонажу и сцене подбирал свой тембр. Это самая ранняя опера, которую регулярно ставят и сегодня."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Frontispiece_of_L%27Orfeo.jpg", "lic": "Public domain", "by": "Claudio Monteverdi (1567–1643)", "src": "media/img/50188e1ae1-1000.webp", "w": 1000, "h": 1319, "remote": "https://upload.wikimedia.org/wikipedia/commons/f/f2/Frontispiece_of_L%27Orfeo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "m3", "title": "Барокко", "period": "1600 — 1750", "intro": [], "traits": ["Рождение оперы (Монтеверди, 1607)", "Басо континуо, звучание клавесина и органа", "Концерт: солист против оркестра, контраст", "Фуга — вершина полифонии", "Бах, Вивальди, Гендель"], "works": [{"t": "Времена года: «Весна», 1 часть", "a": "Антонио Вивальди", "y": "1725", "d": "Программная музыка: скрипки щебечут как птицы, журчат ручьи, гремит гроза. К каждому концерту Вивальди написал сонет.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga", "lic": "CC BY-SA 4.0", "by": "Antonio Vivaldi", "src": "media/audio/1608612918.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/ff/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga.mp3"}, "story": ["«Времена года» это четыре скрипичных концерта Вивальди, опубликованные в 1725 году. К каждому он приложил стихотворение-сонет, описывающее, что изображает музыка.", "В «Весне» сначала звучит радостная тема всего оркестра, а потом солист и две скрипки щебечут, как птицы. Дальше журчат ручьи, гремит короткая гроза, и снова поют птицы. Это программная музыка, которая рассказывает историю без слов.", "Обратите внимание на чередование: то играет весь оркестр, то солист. Это главный принцип барочного концерта."]}, {"t": "Токката и фуга ре минор", "a": "Иоганн Себастьян Бах", "y": "около 1704", "d": "Органная пьеса в оркестровой версии Стоковского (запись 1927 года). Грозное начало знакомо всем по кино.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:PDP-CH_-_Philadelphia_Orchestra,_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor,_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac", "lic": "Public domain", "by": "", "src": "media/audio/9b14423118.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac.mp3"}, "story": ["Это органная пьеса, которую приписывают Баху, написанная, скорее всего, в молодости, около 1704 года. Здесь она звучит в версии для оркестра американского дирижёра Леопольда Стоковского, запись 1927 года.", "Токката это виртуозная пьеса со свободными пассажами, «пробой пальцев». Фуга это полифоническая пьеса: тема проходит по очереди в разных голосах, и они переплетаются.", "Грозное начало узнают многие: его часто используют в фильмах ужасов. В 1940 году эта версия Стоковского открывала мультфильм Диснея «Фантазия»."]}, {"t": "Бранденбургский концерт № 3", "a": "Иоганн Себастьян Бах", "y": "1721", "d": "Ровный «моторный» пульс и переклички групп струнных — образец барочного концерта.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Johann Sebastian Bach", "src": "media/audio/23a0896ac5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg.mp3"}, "story": ["В 1721 году Бах подарил маркграфу Бранденбургскому шесть концертов в надежде получить работу. Маркграф, судя по всему, их так и не исполнил, и рукопись пролежала в библиотеке больше ста лет.", "В третьем концерте нет солиста. Три группы струнных, по три скрипки, три альта и три виолончели, перекликаются друг с другом. Слышен ровный «моторный» пульс, который ни на секунду не останавливается, это очень характерно для барокко."]}, {"t": "«Аллилуйя» из оратории «Мессия»", "a": "Георг Фридрих Гендель", "y": "1741", "d": "По традиции на этом хоре публика встаёт — говорят, так впервые сделал король Георг II.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Handel_-_messiah_-_44_hallelujah.ogg", "lic": "CC BY-SA 2.0", "by": "Composer: Georg Friedrich Händel; Performed by: MIT Concert Choir; Directed by W", "src": "media/audio/17b9907669.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/ce/Handel_-_messiah_-_44_hallelujah.ogg/Handel_-_messiah_-_44_hallelujah.ogg.mp3"}, "story": ["Гендель написал ораторию «Мессия» в 1741 году всего за 24 дня. В ней рассказывается о рождении, смерти и воскресении Христа.", "Хор «Аллилуйя» завершает вторую часть. Слово «аллилуйя» значит «хвалите Бога». Голоса то звучат все вместе, мощными аккордами, то перекликаются.", "По традиции на этом хоре публика встаёт. Говорят, что на лондонском исполнении 1743 года встал король Георг II, а за ним и весь зал. Документов этому нет, но традиция живёт уже почти триста лет."]}, {"t": "Ария (Air)", "a": "Иоганн Себастьян Бах", "y": "около 1730", "d": "Из оркестровой сюиты № 3. Мелодия парит над шагающим басом — тем самым басо континуо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Air_(Bach).ogg", "lic": "Public domain", "by": "", "src": "media/audio/2bcfaba4de.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1e/Air_%28Bach%29.ogg/Air_%28Bach%29.ogg.mp3"}, "story": ["Это медленная часть из оркестровой сюиты № 3 Баха. Сюита это набор танцев, а ария здесь певучая пьеса без слов.", "Мелодия в скрипках парит медленно и длинно, а внизу басы шагают ровными шагами. Это и есть басо континуо. В XIX веке скрипач Август Вильгельми переложил арию для одной струны скрипки, «соль», и её стали называть «Ария на струне соль»."]}], "quiz": [{"q": "Какой жанр родился в эпоху барокко?", "o": ["Симфоническая поэма", "Опера", "Джаз", "Мадригал"], "a": 1, "e": "Первая сохранившаяся великая опера — «Орфей» Монтеверди, 1607."}, {"q": "Кто написал «Времена года»?", "o": ["Бах", "Гендель", "Вивальди", "Моцарт"], "a": 2, "e": "Антонио Вивальди, «рыжий священник» из Венеции."}, {"q": "Какой инструмент — «голос» барокко, на нём часто играли басо континуо?", "o": ["Рояль", "Клавесин", "Саксофон", "Арфа"], "a": 1, "e": "Фортепиано появится позже, а в барокко звучали клавесин и орган."}, {"q": "Фуга — это…", "o": ["Танец", "Полифоническая пьеса, где тема проходит по очереди во всех голосах", "Песня без слов", "Оркестровое вступление к опере"], "a": 1, "e": "Бах — величайший мастер фуги."}], "why": ["В эпоху барокко появились почти все жанры, которые мы считаем классическими: опера, концерт, соната, оратория, сюита. Тогда же сложился оркестр. Бах, Вивальди и Гендель до сих пор звучат в концертах, фильмах и рекламе. Если научиться узнавать барокко, станет понятно, откуда растёт вся классическая музыка."], "groups": [{"h": "Звучание барокко", "p": "Барокко легко узнать по ровному пульсу, звуку клавесина или органа и игре контрастов: громко и тихо, один и все.", "items": [{"t": "Клавесин", "d": "Главный клавишный инструмент эпохи.", "c": "Клавесин Рюккерса, Антверпен, 1627", "more": ["В клавесине струну не бьёт молоточек, как в пианино, а цепляет птичье перо. Звук звонкий и короткий, но громче или тише сыграть нельзя, сколько ни нажимай. Поэтому для контраста у дорогих клавесинов было две клавиатуры.", "Клавесин играл басо континуо, непрерывный бас с аккордами, на котором держалась почти вся музыка барокко. Семья мастеров Рюккерс из Антверпена делала лучшие клавесины, крышки расписывали картинами и девизами."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Harpsichord,_Antwerp_1627,_Andreas_Ruckers_pic1.jpg", "lic": "Public domain", "by": "Alf van Beem", "src": "media/img/d07145782a-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Harpsichord%2C_Antwerp_1627%2C_Andreas_Ruckers_pic1.jpg/1280px-Harpsichord%2C_Antwerp_1627%2C_Andreas_Ruckers_pic1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Орган", "d": "Самый большой инструмент, король церковной музыки.", "c": "Орган Арпа Шнитгера в Гамбурге, 1693", "more": ["Орган это тысячи труб разной длины, через которые меха гонят воздух. Регистры, специальные рычаги, меняют тембр: орган может звучать как флейта, труба или целый хор.", "Этот орган в Гамбурге построил мастер Арп Шнитгер. В 1720 году на нём играл Бах, когда хотел получить место органиста в этой церкви. Он не получил его: место досталось тому, кто внёс в казну церкви крупную сумму."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Arp_Schnitger_organ_St._Jacobi_Hamburg.jpg", "lic": "CC BY-SA 3.0", "by": "Kliojünger", "src": "media/img/c93c5992cc-1000.webp", "w": 1000, "h": 1329, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Arp_Schnitger_organ_St._Jacobi_Hamburg.jpg/1280px-Arp_Schnitger_organ_St._Jacobi_Hamburg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Три великих композитора", "p": "Все трое родились в 1685 году или около того, но прожили очень разные жизни.", "items": [{"t": "Иоганн Себастьян Бах", "d": "Мастер полифонии и органа, церковный музыкант.", "c": "Элиас Хаусман. Портрет Баха, 1748", "more": ["Бах почти всю жизнь прожил в небольших немецких городах. Последние 27 лет служил кантором церкви Святого Фомы в Лейпциге: каждую неделю писал кантату для воскресной службы, учил мальчиков хора. У него было двадцать детей.", "На портрете он держит лист с канон-загадкой, которую нужно разгадать, чтобы сыграть. При жизни Баха считали старомодным, а после смерти почти забыли. В 1829 году композитор Мендельсон исполнил его «Страсти по Матфею», и началось возвращение Баха."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Johann_Sebastian_Bach.jpg", "lic": "Public domain", "by": "Elias Gottlob Haussmann", "src": "media/img/ec2a213a8d-1000.webp", "w": 1000, "h": 1298, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Johann_Sebastian_Bach.jpg/1280px-Johann_Sebastian_Bach.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Антонио Вивальди", "d": "Венецианский священник и скрипач, мастер концерта.", "c": "Портрет Вивальди", "more": ["Вивальди из-за рыжих волос звали «рыжим священником». Он был рукоположен, но почти не служил мессы, ссылаясь на болезнь. Почти сорок лет он учил музыке девочек-сирот в венецианском приюте Пьета.", "Его воспитанницы играли за решёткой на балконе церкви, публика их не видела, но съезжалась со всей Европы. Вивальди написал около пятисот концертов. Он умер в бедности в Вене, а его музыку заново открыли только в XX веке."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Antonio_Vivaldi_portrait.jpg", "lic": "Public domain", "by": "Unidentified painter", "src": "media/img/ebdadd756b-1000.webp", "w": 1000, "h": 1246, "remote": "https://upload.wikimedia.org/wikipedia/commons/9/98/Antonio_Vivaldi_portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Георг Фридрих Гендель", "d": "Немец, ставший звездой Лондона, мастер оперы и оратории.", "c": "Томас Хадсон. Портрет Генделя, 1756", "more": ["Гендель учился в Италии, а потом поселился в Лондоне и прожил там почти пятьдесят лет. Он писал итальянские оперы для английской публики и был богат и знаменит.", "Когда мода на оперы прошла, он перешёл на оратории, большие произведения для хора и оркестра на библейские сюжеты, но без сцены и костюмов. Похоронен в Вестминстерском аббатстве рядом с королями."], "img": {"page": "https://commons.wikimedia.org/wiki/File:George_Frideric_Handel_by_Thomas_Hudson_-_1756.jpg", "lic": "Public domain", "by": "Thomas Hudson", "src": "media/img/5cd92de4ee-1000.webp", "w": 1000, "h": 1646, "remote": "https://upload.wikimedia.org/wikipedia/commons/9/9f/George_Frideric_Handel_by_Thomas_Hudson_-_1756.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "m4", "title": "Венская классика", "period": "1750 — 1820", "intro": [], "traits": ["Ясная мелодия + аккомпанемент", "Сонатная форма: экспозиция, разработка, реприза", "Симфония из четырёх частей", "Фортепиано вытесняет клавесин", "Гайдн, Моцарт, Бетховен"], "works": [{"t": "Маленькая ночная серенада, 1 часть", "a": "Вольфганг Амадей Моцарт", "y": "1787", "d": "Эталон классической ясности: изящные фразы, симметрия, лёгкость.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/1d88e5c0b6.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg.mp3"}, "story": ["Моцарт написал серенаду в 1787 году для небольшого струнного ансамбля. Серенада это лёгкая музыка для вечернего развлечения, часто под открытым небом.", "Это образец классической ясности. Фразы симметричные, как вопрос и ответ. Мелодия сверху, аккомпанемент снизу, всё прозрачно и понятно.", "Удивительно, что эту пьесу при жизни Моцарта, скорее всего, ни разу не исполнили публично. Её напечатали только через сорок лет после его смерти."]}, {"t": "Турецкий марш (Рондо в турецком стиле)", "a": "Вольфганг Амадей Моцарт", "y": "1783", "d": "Финал фортепианной сонаты. В Вене тогда была мода на «янычарскую» музыку.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_(Turkish_March).ogg", "lic": "CC BY-SA 3.0 de", "by": "Bernd Krueger", "src": "media/audio/512a2dd145.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bf/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg.mp3"}, "story": ["Это финал фортепианной сонаты, около 1783 года. В Вене тогда была мода на всё турецкое: пили кофе, носили тюрбаны и слушали янычарскую музыку турецких военных оркестров с барабанами и тарелками.", "Моцарт изобразил на фортепиано звуки турецкого оркестра: в левой руке звучат удары, как у барабана. Рондо значит форма, где главная тема возвращается несколько раз, чередуясь с новыми эпизодами."]}, {"t": "Симфония № 94 «Сюрприз», 2 часть", "a": "Йозеф Гайдн", "y": "1791", "d": "Тихая простая тема — и вдруг удар всего оркестра. Говорят, Гайдн хотел разбудить задремавшую публику.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Haydn;_Symphony_No._94_%22Surprise%22,_2._Andante.ogg", "lic": "Public domain", "by": "Boston Symphony Orchestra\n\nSerge Koussevitzky", "src": "media/audio/0ce9b31532.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg.mp3"}, "story": ["Гайдн написал симфонию в 1791 году для концертов в Лондоне. Вторая часть начинается очень тихой простой мелодией.", "А потом внезапно звучит громкий удар всего оркестра с литаврами. Отсюда и название «Сюрприз». Говорят, Гайдн хотел разбудить дремлющих дам, но сам он позже объяснял, что хотел удивить публику чем-то новым.", "Дальше Гайдн строит вариации: та же мелодия повторяется в разных нарядах. Это хороший пример того, как классики развивают одну простую тему."]}, {"t": "Реквием: Lacrimosa", "a": "Вольфганг Амадей Моцарт", "y": "1791", "d": "Последнее, над чем работал Моцарт: он умер, успев написать лишь восемь тактов «Лакримозы».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:W._A._Mozart_-_Requiem_-_8._Lacrimosa_(Herbert_von_Karajan,_Wiener_Philharmoniker,_Wiener_Singverein,_1960).ogg", "lic": "Public domain", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/a15c6d3970.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/04/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg.mp3"}, "story": ["В 1791 году незнакомец заказал Моцарту реквием, заупокойную мессу. Позже выяснилось, что это был граф, который хотел выдать музыку за свою. Моцарт был тяжело болен и работал над реквиемом до последних дней.", "Он успел написать всего восемь тактов «Лакримозы», «Слёзной» части, и умер. Реквием закончил его ученик Франц Зюсмайр по наброскам и указаниям.", "Мелодия поднимается вверх ступенями, как всхлипы, и снова опускается. Это одна из самых печальных страниц в музыке."]}, {"t": "«Лунная» соната, 3 часть", "a": "Людвиг ван Бетховен", "y": "1801", "d": "После знаменитой тихой первой части — буря. У Бетховена классическая форма наполняется страстью.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Beethoven_Moonlight_3rd_movement.ogg", "lic": "CC BY-SA 2.0 de", "by": "Ludwig van Beethoven", "src": "media/audio/01c1914487.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/d4/Beethoven_Moonlight_3rd_movement.ogg/Beethoven_Moonlight_3rd_movement.ogg.mp3"}, "story": ["Бетховен написал сонату в 1801 году и посвятил её юной ученице, графине Джульетте Гвиччарди, в которую был влюблён. Название «Лунная» придумал не он, а поэт Людвиг Рельштаб после смерти композитора.", "Все знают тихую первую часть. А третья часть это буря: стремительные пассажи, резкие аккорды. Бетховен показывает, что классическая соната может выражать отчаяние и страсть."]}], "quiz": [{"q": "Кого называют «отцом симфонии»?", "o": ["Моцарта", "Бетховена", "Гайдна", "Баха"], "a": 2, "e": "Гайдн написал 104 симфонии и закрепил её форму."}, {"q": "Какой инструмент пришёл на смену клавесину в эпоху классицизма?", "o": ["Орган", "Фортепиано", "Гитара", "Арфа"], "a": 1, "e": "Pianoforte — «тихо-громко»: удар молоточка зависит от силы нажатия."}, {"q": "Какой город — столица венской классики?", "o": ["Париж", "Вена", "Лейпциг", "Рим"], "a": 1, "e": "Все трое — Гайдн, Моцарт, Бетховен — работали в Вене."}, {"q": "Чьё творчество стало мостом от классицизма к романтизму?", "o": ["Гайдна", "Бетховена", "Вивальди", "Палестрины"], "a": 1, "e": "Бетховен — классик по форме, романтик по силе чувства."}], "why": ["Венские классики Гайдн, Моцарт и Бетховен создали формы, по которым композиторы работают до сих пор: симфония, соната, квартет, концерт. Их музыка звучит ясно и логично, как хорошо построенный рассказ. Поняв, как она устроена, вы начнёте слышать в любом классическом произведении начало, развитие и развязку."], "groups": [{"h": "Три венских классика", "p": "Они знали друг друга: Гайдн дружил с Моцартом, а молодой Бетховен брал уроки у Гайдна.", "items": [{"t": "Йозеф Гайдн", "d": "«Отец симфонии», написал больше ста симфоний.", "c": "Томас Харди. Портрет Гайдна, 1792", "more": ["Почти тридцать лет Гайдн служил капельмейстером у князей Эстерхази в их роскошном дворце в Венгрии. У него был свой оркестр, и он мог экспериментировать каждый день.", "Он сам говорил: «Я был отрезан от мира, и мне пришлось стать оригинальным». Гайдн закрепил форму симфонии из четырёх частей и струнного квартета. Его называли «папа Гайдн», он был добрым и остроумным, и в музыке у него много шуток."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Joseph_Haydn,_portrait_by_Thomas_Hardy.jpg", "lic": "Public domain", "by": "Thomas Hardy", "src": "media/img/4ad38dc7e1-1000.webp", "w": 1000, "h": 1229, "remote": "https://upload.wikimedia.org/wikipedia/commons/e/e5/Joseph_Haydn%2C_portrait_by_Thomas_Hardy.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Дворец Эстерхази", "d": "Где писал Гайдн.", "c": "Дворец Эстерхази в Фертёде, Венгрия", "more": ["Дворец называли «венгерским Версалем». В нём были оперный театр, кукольный театр и концертный зал. Оркестр выступал почти каждый день.", "Однажды князь слишком надолго задержался во дворце, и музыканты скучали по семьям. Гайдн написал «Прощальную симфонию»: в финале музыканты один за другим гасят свечи и уходят. Князь понял намёк и на следующий день отпустил всех домой."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Esterh%C3%A1zy_Palace,_Fert%C5%91d,_20220426_1053_5444.jpg", "lic": "CC BY-SA 4.0", "by": "Jakub Hałun", "src": "media/img/3e715a619d-1000.webp", "w": 1000, "h": 390, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Esterh%C3%A1zy_Palace%2C_Fert%C5%91d%2C_20220426_1053_5444.jpg/1280px-Esterh%C3%A1zy_Palace%2C_Fert%C5%91d%2C_20220426_1053_5444.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вольфганг Амадей Моцарт", "d": "Вундеркинд, писал во всех жанрах.", "c": "Семья Моцарт, около 1780", "more": ["Моцарт начал сочинять в пять лет, а в шесть отец возил его и сестру Наннерль по дворам Европы. На этом портрете они играют в четыре руки, отец со скрипкой, а на стене портрет умершей матери.", "Моцарт прожил всего 35 лет и написал больше шестисот произведений: оперы, симфонии, концерты, сонаты, мессы. Он одним из первых ушёл со службы и жил как свободный композитор в Вене, что было тогда рискованно."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_Family_Croce.jpg", "lic": "Public domain", "by": "Possibly Johann Nepomuk della Croce", "src": "media/img/e66d4259b5-1000.webp", "w": 1000, "h": 747, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Mozart_Family_Croce.jpg/1280px-Mozart_Family_Croce.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Людвиг ван Бетховен", "d": "Мост от классики к романтизму.", "c": "Йозеф Штилер. Бетховен, 1820", "more": ["Бетховен приехал в Вену из Бонна в 22 года. Около тридцати лет он начал терять слух и к концу жизни оглох полностью. Последние великие произведения, включая Девятую симфонию, он писал, не слыша их.", "Бетховен наполнил классическую форму бурными чувствами и борьбой. Его симфонии длиннее и мощнее, чем у Гайдна и Моцарта. Здесь он держит рукопись своей «Торжественной мессы»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Joseph_Karl_Stieler%27s_Beethoven_mit_dem_Manuskript_der_Missa_solemnis.jpg", "lic": "Public domain", "by": "Joseph Karl Stieler", "src": "media/img/8c0c002a00-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Joseph_Karl_Stieler%27s_Beethoven_mit_dem_Manuskript_der_Missa_solemnis.jpg/1280px-Joseph_Karl_Stieler%27s_Beethoven_mit_dem_Manuskript_der_Missa_solemnis.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "m5", "title": "Романтизм", "period": "1820 — 1900", "intro": [], "traits": ["Музыка как исповедь души", "Миниатюры: песня, ноктюрн, вальс, прелюдия", "Виртуозы: Лист, Паганини", "Национальные школы и фольклор", "Опера: Верди и Вагнер, лейтмотив"], "works": [{"t": "Ноктюрн ми-бемоль мажор, соч. 9 № 2", "a": "Фредерик Шопен", "y": "1832", "d": "Ноктюрн — «ночная» пьеса. Мелодия поёт как голос оперной певицы, а левая рука мягко покачивает аккомпанемент.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Chopin_Nocturne_Op_9_No_2.ogg", "lic": "CC BY-SA 3.0", "by": "Beeswaxcandle at English Wikisource and Londonjackbooks at English Wikisource", "src": "media/audio/bd368afbec.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fd/Chopin_Nocturne_Op_9_No_2.ogg/Chopin_Nocturne_Op_9_No_2.ogg.mp3"}, "story": ["Ноктюрн значит «ночная пьеса». Шопен написал его около 1830 года, в 20 лет.", "Правая рука поёт длинную мелодию, как оперная певица, с украшениями и трелями. Левая рука мягко покачивает аккомпанемент. Шопен обожал оперу и перенёс на фортепиано манеру итальянского пения бельканто."]}, {"t": "Ave Maria (Третья песня Эллен)", "a": "Франц Шуберт", "y": "1825", "d": "Песня на стихи Вальтера Скотта стала одной из самых любимых мелодий мира.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Schubert_-_Ellens_dritter_Gesang.oga", "lic": "CC BY 3.0", "by": "Composed by Franz Schubert", "src": "media/audio/564b062750.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/6/6f/Franz_Schubert_-_Ellens_dritter_Gesang.oga/Franz_Schubert_-_Ellens_dritter_Gesang.oga.mp3"}, "story": ["Шуберт написал эту песню в 1825 году на стихи шотландского поэта Вальтера Скотта из поэмы «Дева озера». Героиня Эллен прячется в пещере и молится Деве Марии о защите.", "Песня начинается словами «Ave Maria», поэтому её так и называют. Позже на эту мелодию стали петь латинскую молитву, и сейчас её часто исполняют в церквях и на свадьбах, хотя Шуберт задумывал её как часть романтической поэмы."]}, {"t": "Венгерская рапсодия № 2", "a": "Ференц Лист", "y": "1847", "d": "Медленное вступление и огненный пляс. Лист — величайший пианист-виртуоз своего века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg", "lic": "CC BY-SA 2.0", "by": "Franz Liszt", "src": "media/audio/5ef5468046.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg.mp3"}, "story": ["Рапсодия это свободная пьеса на народные темы. Лист написал её в 1847 году, используя мелодии, которые играли цыганские оркестры в Венгрии.", "Сначала звучит медленный, задумчивый лашшан, потом стремительный танец фришка. Лист мастерски изображает на фортепиано цимбалы и скрипки. Эту музыку многие помнят по мультфильмам «Том и Джерри» и «Багз Банни»."]}, {"t": "Полёт валькирий", "a": "Рихард Вагнер", "y": "1856", "d": "Из оперы «Валькирия». Девы-воительницы несутся над полем битвы — мощь вагнеровского оркестра.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Richard_Wagner_-_Ride_of_the_Valkyries.ogg", "lic": "Public domain", "by": "Richard Wagner (1813–1883)", "src": "media/audio/e260e0ce0d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/29/Richard_Wagner_-_Ride_of_the_Valkyries.ogg/Richard_Wagner_-_Ride_of_the_Valkyries.ogg.mp3"}, "story": ["Это начало третьего действия оперы Вагнера «Валькирия» 1856 года. Валькирии, девы-воительницы из германских мифов, на крылатых конях уносят с поля боя погибших героев.", "Тему ведут медные духовые, а скрипки изображают свист ветра. Это лейтмотив валькирий, он возвращается каждый раз, когда они появляются. Мощь звучания показывает, каким огромным стал оркестр романтиков.", "В фильме «Апокалипсис сегодня» под эту музыку летят вертолёты, и с тех пор её часто используют в кино."]}, {"t": "В пещере горного короля", "a": "Эдвард Григ", "y": "1875", "d": "Из музыки к «Пер Гюнту». Одна тема повторяется всё быстрее и громче — классический пример крещендо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg", "lic": "Public domain", "by": "Grieg, Edvard; Musopen Symphony Orchestra", "src": "media/audio/84d933de2a.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bb/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg.mp3"}, "story": ["Пер Гюнт пробрался в подземный зал короля троллей. Тролли сначала спят, а потом просыпаются и гонятся за ним.", "Мелодия одна и та же, она повторяется снова и снова, всё быстрее и громче. Сначала тихо у фаготов и контрабасов, в конце гремит весь оркестр. Это пример крещендо, постепенного нарастания громкости, и ускорения темпа."]}, {"t": "La donna è mobile («Сердце красавицы»)", "a": "Джузеппе Верди", "y": "1851", "d": "Песенка Герцога из оперы «Риголетто». Наутро после премьеры её насвистывала вся Венеция.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:La_Donna_E_Mobile_Rigoletto.ogg", "lic": "Public domain", "by": "Giuseppe Verdi &amp; Francesco Maria Piave", "src": "media/audio/4a5afe39a8.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5a/La_Donna_E_Mobile_Rigoletto.ogg/La_Donna_E_Mobile_Rigoletto.ogg.mp3"}, "story": ["Это песенка Герцога из оперы Верди «Риголетто» 1851 года. Легкомысленный Герцог поёт, что женщины непостоянны, как перо на ветру, хотя непостоянный тут он сам.", "Верди знал, что мелодия станет хитом, и до последней репетиции не давал тенору ноты, чтобы её не разучили и не разнесли по Венеции раньше премьеры. Наутро после премьеры её насвистывали гондольеры по всему городу."]}], "quiz": [{"q": "Что главное в музыке романтизма?", "o": ["Строгая форма", "Выражение чувств и личности", "Церковный канон", "Танцевальный ритм"], "a": 1, "e": "Романтики видели в музыке язык души."}, {"q": "Что такое лейтмотив?", "o": ["Финал оперы", "Повторяющаяся тема-характеристика героя или идеи", "Вид танца", "Музыкальный инструмент"], "a": 1, "e": "Вагнер построил на лейтмотивах свои огромные оперы."}, {"q": "Кто написал знаменитые ноктюрны и вальсы для фортепиано?", "o": ["Вагнер", "Шопен", "Верди", "Гайдн"], "a": 1, "e": "Фредерик Шопен — «поэт фортепиано»."}, {"q": "Как называется постепенное усиление громкости?", "o": ["Диминуэндо", "Крещендо", "Стаккато", "Легато"], "a": 1, "e": "Crescendo — «вырастая». Обратное — diminuendo."}], "why": ["Романтики сделали музыку языком личных чувств: любви, тоски, мечты, восторга перед природой. Именно романтизм подарил большую часть музыки, которую сегодня играют на концертах и используют в кино. Здесь появились первые музыкальные звёзды, а композиторы начали писать о своих народах и их легендах."], "groups": [{"h": "Музыка в гостиной", "p": "Многие романтики писали не для огромных залов, а для домашних вечеров с друзьями.", "items": [{"t": "Шубертиады", "d": "Вечера, где друзья слушали новые песни Шуберта.", "c": "Юлиус Шмид. «Шубертиада», 1897", "more": ["Франц Шуберт был застенчивым и небогатым. Его друзья, поэты и художники, собирались по вечерам в домах Вены, чтобы послушать его новые песни и пьесы. Эти вечера назвали шубертиадами.", "Шуберт прожил всего 31 год и написал больше шестисот песен. Песня с фортепиано стала у него целым миром: в ней рассказывают истории, рисуют пейзажи, передают настроение одного мгновения."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Julius_Schmid_Schubertiade.jpg", "lic": "Public domain", "by": "Julius Schmid", "src": "media/img/9db4b6a9ba-1000.webp", "w": 1000, "h": 658, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/66/Julius_Schmid_Schubertiade.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Шопен", "d": "«Поэт фортепиано», писал почти только для него.", "c": "Эжен Делакруа. Портрет Шопена, 1838", "more": ["Фредерик Шопен родился в Польше и в 20 лет уехал в Париж. Вскоре Польшу захватила Россия, и он больше никогда не вернулся на родину. В его мазурках и полонезах звучит тоска по Польше.", "Шопен не любил больших концертов и играл в салонах для узкого круга. Делакруа, его друг, написал этот портрет. Сердце Шопена по его просьбе после смерти тайно перевезли в Варшаву, оно хранится в костёле Святого Креста."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Eug%C3%A8ne_Delacroix_-_Fr%C3%A9d%C3%A9ric_Chopin_-_WGA06194.jpg", "lic": "Public domain", "by": "Eugène Delacroix", "src": "media/img/2aa4052726-1000.webp", "w": 1000, "h": 1344, "remote": "https://upload.wikimedia.org/wikipedia/commons/9/9a/Eug%C3%A8ne_Delacroix_-_Fr%C3%A9d%C3%A9ric_Chopin_-_WGA06194.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Первые звёзды сцены", "p": "Виртуозы собирали огромные залы, а публика сходила по ним с ума.", "items": [{"t": "Лист за роялем", "d": "Ференц Лист изобрёл сольный концерт.", "c": "Йозеф Данхаузер. «Лист за роялем», 1840", "more": ["Венгр Ференц Лист был величайшим пианистом своего времени. Он первым стал давать концерты один, без других музыкантов, и первым поставил рояль боком к публике, чтобы был виден его профиль.", "Дамы падали в обморок и дрались за его перчатки, это даже назвали «листоманией». На картине его слушают писатели Жорж Санд и Александр Дюма, композитор Россини и скрипач Паганини, на рояле бюст Бетховена."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Josef_Danhauser_Liszt_am_Fl%C3%BCgel_1840_01.jpg", "lic": "Public domain", "by": "Josef Danhauser", "src": "media/img/26ec9768f5-1000.webp", "w": 1000, "h": 748, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Josef_Danhauser_Liszt_am_Fl%C3%BCgel_1840_01.jpg/1280px-Josef_Danhauser_Liszt_am_Fl%C3%BCgel_1840_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Паганини", "d": "Скрипач, о котором говорили, что он продал душу дьяволу.", "c": "Энгр. Рисунок Паганини, 1819", "more": ["Итальянец Никколо Паганини играл такие быстрые и сложные пассажи, что слушатели не верили своим глазам. У него были очень длинные гибкие пальцы. Ходили слухи, что он продал душу дьяволу за мастерство.", "Паганини выступал в чёрном, был худым и бледным, и сам поддерживал эту легенду. Его 24 каприса для скрипки до сих пор считаются одними из самых трудных пьес."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Ingres_-_Portrait_de_Paganini,_RF_4381,_Recto.jpg", "lic": "Public domain", "by": "Jean-Auguste-Dominique Ingres", "src": "media/img/65458cc4f6-1000.webp", "w": 1000, "h": 1500, "remote": "https://upload.wikimedia.org/wikipedia/commons/0/0d/Ingres_-_Portrait_de_Paganini%2C_RF_4381%2C_Recto.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Опера: Верди и Вагнер", "p": "Два главных оперных композитора века родились в одном и том же 1813 году и пошли противоположными путями.", "items": [{"t": "Джузеппе Верди", "d": "Голос Италии, мастер мелодии.", "c": "Джованни Болдини. Портрет Верди, 1886", "more": ["Верди написал 26 опер, в том числе «Риголетто», «Травиату», «Аиду». Его мелодии пела вся Италия. Хор пленённых евреев из оперы «Набукко» итальянцы воспринимали как гимн своей свободы от Австрии.", "Буквы его имени VERDI читали как сокращение «Да здравствует Виктор Эммануил, король Италии», и надписи «Viva Verdi» на стенах были тайным призывом к объединению страны."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Verdi_by_Giovanni_Boldini.jpg", "lic": "Public domain", "by": "Giovanni Boldini", "src": "media/img/f8753ed0ac-1000.webp", "w": 1000, "h": 1234, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/19/Verdi_by_Giovanni_Boldini.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Байройт Вагнера", "d": "Театр, построенный для опер одного композитора.", "c": "Фестивальный театр в Байройте", "more": ["Рихард Вагнер считал, что опера должна соединять все искусства: музыку, поэзию, театр, живопись. Он сам писал тексты своих опер и придумал лейтмотивы, короткие темы-визитки героев и идей.", "Король Баварии Людвиг II помог ему построить специальный театр в городке Байройт. Его открыли в 1876 году четырёхдневным циклом «Кольцо нибелунга». Оркестр спрятан под сцену, чтобы не отвлекать. Фестиваль проходит там каждое лето до сих пор."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Festspielhaus_Bayreuth_2016.jpg", "lic": "CC BY-SA 4.0", "by": "El Grafo", "src": "media/img/1e9765d900-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Festspielhaus_Bayreuth_2016.jpg/1280px-Festspielhaus_Bayreuth_2016.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Эдвард Григ", "d": "Норвегия в музыке.", "c": "Ханс Хейердал. Портрет Грига", "more": ["Романтики интересовались народными песнями и легендами, и в каждой стране появились свои национальные композиторы. Эдвард Григ превратил норвежские мелодии и танцы в классическую музыку.", "Драматург Генрик Ибсен попросил его написать музыку к пьесе «Пер Гюнт» о мечтателе, который попадает к горным троллям. Сам Григ считал «В пещере горного короля» неудачной, говорил, что она «пахнет коровьим навозом и норвежщиной». Сейчас это одна из самых известных мелодий мира."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Hans_Heyerdahl_-_Portrett_av_Edvard_Grieg_-_Oslo_Museum_-_OB.00036.jpg", "lic": "CC BY 4.0", "by": "Hans Heyerdahl", "src": "media/img/0ffda8fa36-1000.webp", "w": 1000, "h": 1375, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Hans_Heyerdahl_-_Portrett_av_Edvard_Grieg_-_Oslo_Museum_-_OB.00036.jpg/1280px-Hans_Heyerdahl_-_Portrett_av_Edvard_Grieg_-_Oslo_Museum_-_OB.00036.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "m6", "title": "Русская классическая музыка", "period": "XIX — начало XX века", "intro": [], "traits": ["Глинка — основоположник русской классической музыки", "«Могучая кучка»: национальные сюжеты и фольклор", "Чайковский: лирика, балет, симфония", "Колокольность, протяжная песенность", "Рахманинов, Скрябин, Стравинский"], "works": [{"t": "Лебединое озеро (фрагмент из 2 акта)", "a": "Пётр Чайковский", "y": "1876", "d": "Тема лебедей — гобой поверх дрожащих струнных. Один из самых узнаваемых мотивов в истории балета.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg", "lic": "Public domain", "by": "Ballet Francaise Symphony Orchestra", "src": "media/audio/ca22213b07.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2b/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg.mp3"}, "story": ["Принц Зигфрид на охоте у озера встречает Одетту, принцессу, которую злой волшебник Ротбарт превратил в лебедя. Она становится девушкой только ночью.", "Тема лебедей звучит у гобоя на фоне дрожащих струнных и арфы. Это лейтмотив, он возвращается в балете несколько раз. Мелодия в миноре, печальная и прекрасная.", "В советское время «Лебединое озеро» показывали по телевизору в дни важных событий и смерти руководителей страны, и для многих в России эта музыка стала знаком перемен."]}, {"t": "Танец Феи Драже («Щелкунчик»)", "a": "Пётр Чайковский", "y": "1892", "d": "Чайковский первым в России использовал челесту — инструмент со звуком «хрустальных капель».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg", "lic": "CC BY 3.0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/93dc198ebb.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg.mp3"}, "story": ["Балет «Щелкунчик» 1892 года по сказке Гофмана. Девочка Маша оказывается в волшебной стране сладостей, и Фея Драже танцует для неё.", "Мелодию играет челеста, инструмент с клавишами, где молоточки бьют по металлическим пластинкам. Звук похож на хрустальные капли. Чайковский увидел новый инструмент в Париже и тайно привёз его в Россию, чтобы никто не опередил его с этим звучанием."]}, {"t": "Картинки с выставки: Прогулка", "a": "Модест Мусоргский", "y": "1874", "d": "Цикл о прогулке по выставке друга-художника Гартмана. «Прогулка» — сам композитор, переходящий от картины к картине.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg", "lic": "Public domain", "by": "Modest Petrovich Mussorgsky", "src": "media/audio/ec87b265b5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/df/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg.mp3"}, "story": ["В 1873 году умер друг Мусоргского, художник и архитектор Виктор Гартман. Через год прошла выставка его рисунков, и Мусоргский написал цикл пьес для фортепиано по этим картинам.", "Пьесы изображают отдельные картины: гнома, старый замок, детей в саду, избушку Бабы-яги, богатырские ворота. Между ними звучит «Прогулка», в ней Мусоргский переходит от одной картины к другой, и её настроение каждый раз меняется.", "В 1922 году француз Морис Равель сделал знаменитую версию цикла для оркестра."]}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Из оперы «Сказка о царе Салтане» по Пушкину: князь Гвидон, обернувшись шмелём, летит к отцу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg", "lic": "CC BY-SA 2.0", "by": "Pianists: Neal and Nancy O'Doan", "src": "media/audio/7d45ebcdf2.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ad/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg.mp3"}, "story": ["Это фрагмент из оперы Римского-Корсакова «Сказка о царе Салтане» 1900 года. Римский-Корсаков был морским офицером и совершил кругосветное плавание, а потом стал профессором консерватории и лучшим мастером оркестровки в России.", "Он особенно любил сказочные сюжеты: «Снегурочка», «Садко», «Золотой петушок». В «Полёте шмеля» скрипки играют быстрые хроматические пассажи, это звуки по полутонам подряд, и получается настоящее жужжание."]}, {"t": "Прелюдия до-диез минор", "a": "Сергей Рахманинов (играет автор)", "y": "1892", "d": "Редкая историческая запись: играет сам Рахманинов. Три тяжёлых «колокольных» удара открывают пьесу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor,_Op._3.ogg", "lic": "Public domain", "by": "Sergei Rachmaninoff", "src": "media/audio/0afd6fd1cc.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b9/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg.mp3"}, "story": ["Рахманинову было 19 лет, когда в 1892 году он написал эту прелюдию. Она сразу стала так популярна, что публика на всех концертах требовала её на бис. Рахманинов даже стал её недолюбливать и называл «Она».", "Здесь играет сам Рахманинов: это запись его исполнения, сохранившаяся с начала XX века. Начинается с трёх тяжёлых ударов, похожих на удары колокола. Колокольный звон часто слышен в музыке Рахманинова, он вырос рядом с новгородскими церквями."]}, {"t": "Концерт для фортепиано № 1, 1 часть", "a": "Пётр Чайковский", "y": "1875", "d": "Мощные аккорды рояля на фоне величественной темы оркестра — одно из самых ярких вступлений в музыке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky,_Concerto_No.1_in_B-flat_minor_Op.23,_I._Allegro.ogg", "lic": "CC0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/2b98fc1938.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/48/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg.mp3"}, "story": ["Чайковский написал концерт в 1874 году и показал его своему учителю, пианисту Николаю Рубинштейну. Тот разругал концерт и сказал, что играть его невозможно.", "Обиженный Чайковский отдал концерт немецкому пианисту Гансу фон Бюлову, и тот с огромным успехом исполнил его в Бостоне. Позже Рубинштейн признал ошибку и сам играл концерт.", "Вступление знает весь мир: рояль бьёт мощные аккорды, а оркестр поёт величественную мелодию. Удивительно, но эта тема больше в концерте ни разу не повторяется."]}], "quiz": [{"q": "Кого называют «отцом русской музыки»?", "o": ["Чайковского", "Глинку", "Мусоргского", "Рахманинова"], "a": 1, "e": "Михаил Глинка, оперы «Жизнь за царя» (1836) и «Руслан и Людмила» (1842)."}, {"q": "Кто НЕ входил в «Могучую кучку»?", "o": ["Мусоргский", "Бородин", "Чайковский", "Римский-Корсаков"], "a": 2, "e": "Чайковский дружил с «кучкистами», но шёл своим путём."}, {"q": "Из какой оперы «Полёт шмеля»?", "o": ["«Садко»", "«Сказка о царе Салтане»", "«Снегурочка»", "«Золотой петушок»"], "a": 1, "e": "Римский-Корсаков, опера по сказке Пушкина, 1900."}, {"q": "Какой балет НЕ принадлежит Чайковскому?", "o": ["«Лебединое озеро»", "«Щелкунчик»", "«Спящая красавица»", "«Жар-птица»"], "a": 3, "e": "«Жар-птица» — балет Стравинского (1910)."}], "why": ["Русская классическая музыка появилась поздно, только в XIX веке, но за сто лет стала одной из самых исполняемых в мире. Чайковский и Рахманинов звучат на каждом континенте. Здесь вы поймёте, как русские композиторы соединили европейскую технику с народной песней и сказкой."], "groups": [{"h": "Рождение русской школы", "p": "До Глинки в России в основном звучала музыка итальянцев и немцев.", "items": [{"t": "Михаил Глинка", "d": "«Отец русской музыки».", "c": "Карл Брюллов. Шарж на Глинку", "more": ["Михаил Глинка был помещиком и учился музыке в Италии и Германии. Он решил создать музыку, в которой будут русские мелодии и русская история.", "В 1836 году его опера «Жизнь за царя» об Иване Сусанине стала первой русской оперой мирового уровня. Потом он написал «Руслана и Людмилу» по Пушкину. Чайковский сказал, что вся русская симфоническая музыка выросла из пьесы Глинки «Камаринская», как дуб из жёлудя."], "img": {"page": "https://commons.wikimedia.org/wiki/File:BriullovGlinka.jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/ae8b0bc4b5-1000.webp", "w": 1000, "h": 1152, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/d1/BriullovGlinka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Модест Мусоргский", "d": "Самый смелый из «Могучей кучки».", "c": "Илья Репин. Портрет Мусоргского, 1881", "more": ["В 1860-х годах в Петербурге собрался кружок молодых композиторов: Балакирев, Мусоргский, Бородин, Римский-Корсаков и Кюи. Критик Стасов назвал их «Могучей кучкой». Они хотели музыку о русской истории, сказках, народе.", "Мусоргский был офицером и чиновником, а музыке учился почти сам. Его опера «Борис Годунов» звучала так необычно, что её поначалу не принимали. Репин написал этот портрет в госпитале за несколько дней до смерти композитора."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Ilya_Repin_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BA%D0%BE%D0%BC%D0%BF%D0%BE%D0%B7%D0%B8%D1%82%D0%BE%D1%80%D0%B0_%D0%9C.%D0%9F.%D0%9C%D1%83%D1%81%D0%BE%D1%80%D0%B3%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/632ea6683f-1000.webp", "w": 1000, "h": 1248, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Ilya_Repin_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BA%D0%BE%D0%BC%D0%BF%D0%BE%D0%B7%D0%B8%D1%82%D0%BE%D1%80%D0%B0_%D0%9C.%D0%9F.%D0%9C%D1%83%D1%81%D0%BE%D1%80%D0%B3%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/1280px-Ilya_Repin_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BA%D0%BE%D0%BC%D0%BF%D0%BE%D0%B7%D0%B8%D1%82%D0%BE%D1%80%D0%B0_%D0%9C.%D0%9F.%D0%9C%D1%83%D1%81%D0%BE%D1%80%D0%B3%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Чайковский и балет", "p": "Пётр Чайковский сделал балет серьёзной музыкой.", "items": [{"t": "Пётр Чайковский", "d": "Самый исполняемый русский композитор.", "c": "Пётр Ильич Чайковский", "more": ["Чайковский учился на юриста и служил в министерстве, а в 21 год пошёл учиться в только что открытую Петербургскую консерваторию. Он написал шесть симфоний, десять опер, три балета, концерты.", "В 1891 году его пригласили открыть новый концертный зал в Нью-Йорке, сейчас это Карнеги-холл. Его музыка сочетает русскую песенность с европейской формой, и её любят во всём мире."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky_2.jpg", "lic": "Public domain", "by": "Alfred Fedecki", "src": "media/img/d44979f734-1000.webp", "w": 1000, "h": 1312, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/43/Tchaikovsky_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Большой театр", "d": "Здесь впервые поставили «Лебединое озеро».", "c": "Большой театр, Москва", "more": ["До Чайковского музыку к балету писали ремесленники, она была просто аккомпанементом для танца. Чайковский написал для «Лебединого озера» настоящую симфоническую музыку с темами и развитием.", "Первая постановка в Большом театре в 1877 году прошла неудачно. Успех пришёл только в 1895 году, уже после смерти Чайковского, когда балет поставили хореографы Мариус Петипа и Лев Иванов в Мариинском театре."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bolshoi_Theatre_-_Moscow_-_2024-8.jpg", "lic": "CC BY 4.0", "by": "Юрий Д.К.", "src": "media/img/c4221eb969-1000.webp", "w": 1000, "h": 677, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Bolshoi_Theatre_-_Moscow_-_2024-8.jpg/1280px-Bolshoi_Theatre_-_Moscow_-_2024-8.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Сергей Рахманинов", "d": "Композитор и великий пианист.", "c": "Рахманинов около 1900 года", "more": ["Рахманинов был очень высоким, с огромными руками: он мог охватить на клавиатуре двенадцать белых клавиш. Его музыка требует таких рук, и пианистам с маленькой ладонью она даётся тяжело.", "После провала Первой симфонии он три года почти не сочинял. Его вылечил врач-психотерапевт, и Рахманинов посвятил ему Второй фортепианный концерт, свою самую известную вещь. После революции он уехал из России и больше не вернулся."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Rachmaninoff_1900.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/81202ef7a8-1000.webp", "w": 1000, "h": 1544, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3e/Rachmaninoff_1900.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "m7", "title": "Импрессионизм и новая музыка", "period": "1890 — 1930", "intro": [], "traits": ["Импрессионизм: краски, настроение, размытость", "Дебюсси, Равель, Сати", "Необычные лады и «плывущие» аккорды", "XX век: эксперименты с ритмом и тональностью", "Стравинский, Шёнберг, Прокофьев, Шостакович"], "works": [{"t": "Лунный свет (Clair de lune)", "a": "Клод Дебюсси", "y": "1905", "d": "Из «Бергамасской сюиты». Тихая, мерцающая музыка — как лунный свет на воде.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Clair_de_lune_(Claude_Debussy)_Suite_bergamasque.ogg", "lic": "Public domain", "by": "Claude Debussy", "src": "media/audio/bbacfbab82.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/be/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg.mp3"}, "story": ["Это третья пьеса из «Бергамасской сюиты» Дебюсси, закончена в 1905 году. Название взято из стихотворения Поля Верлена о лунном саду.", "Музыка начинается очень тихо, аккорды будто растворяются друг в друге. Нет чёткого ритма, звуки переливаются, как отблески луны на воде. Это и есть импрессионизм в музыке.", "Сегодня «Лунный свет» одна из самых популярных пьес для фортепиано, её используют в десятках фильмов."]}, {"t": "Гимнопедия № 1", "a": "Эрик Сати", "y": "1888", "d": "Медленная, прозрачная, почти неподвижная музыка. Сати предвосхитил минимализм и «фоновую» музыку XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac", "lic": "Public domain", "by": "Mlaucke", "src": "media/audio/92a127ed15.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/a6/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac.mp3"}, "story": ["Сати написал три «Гимнопедии» в 1888 году. Название он взял из греческой истории: так назывались танцы юношей на празднике в Спарте.", "Музыка медленная и прозрачная. В левой руке повторяется спокойное покачивание, в правой плывёт простая печальная мелодия. Почти ничего не происходит, и в этом её очарование. Позже Дебюсси сделал переложение двух «Гимнопедий» для оркестра."]}, {"t": "Болеро", "a": "Морис Равель", "y": "1928", "d": "Одна мелодия и неизменный ритм барабана 15 минут — но каждый раз в новом тембре и всё громче. Урок оркестровки.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bolero-Maurice_Ravel-1930.ogg", "lic": "Public domain", "by": "Maurice Ravel", "src": "media/audio/0cd80089af.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c3/Bolero-Maurice_Ravel-1930.ogg/Bolero-Maurice_Ravel-1930.ogg.mp3"}, "story": ["Танцовщица Ида Рубинштейн заказала Морису Равелю музыку для балета в испанском стиле. В 1928 году он написал «Болеро» и сам называл его экспериментом.", "Малый барабан пятнадцать минут отбивает один и тот же ритм. Две мелодии повторяются снова и снова, каждый раз у новых инструментов: флейта, кларнет, фагот, саксофон, труба. Музыка постепенно становится громче, и в самом конце внезапно меняется тональность, всё рушится.", "Это урок оркестровки: как одна мелодия может звучать совсем по-разному. Говорят, когда на премьере одна дама закричала, что автор сумасшедший, Равель ответил: «Она поняла»."]}, {"t": "Жар-птица: Поганый пляс Кащея", "a": "Игорь Стравинский", "y": "1910", "d": "Балет для «Русских сезонов» Дягилева. Резкие акценты и дикий ритм — новая музыка XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg", "lic": "Public domain", "by": "", "src": "media/audio/36bce0b1a3.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ab/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg.mp3"}, "story": ["В 1910 году Дягилев заказал 27-летнему Игорю Стравинскому балет по русским сказкам для «Русских сезонов». «Жар-птица» прославила Стравинского в одну ночь.", "Царевич Иван попадает в царство Кащея Бессмертного. Нечисть пускается в бешеный пляс, а Жар-птица заставляет их танцевать до изнеможения. Резкие удары, неожиданные акценты, огромный оркестр.", "Стравинский потом стал одним из главных композиторов XX века. Он жил в Швейцарии, Франции и США и много раз менял стиль, но ритм всегда оставался его главным оружием."]}], "quiz": [{"q": "Кто главный композитор-импрессионист?", "o": ["Вагнер", "Дебюсси", "Бетховен", "Гендель"], "a": 1, "e": "Клод Дебюсси, хотя сам он не любил этот ярлык."}, {"q": "В чём необычность «Болеро» Равеля?", "o": ["Оно без мелодии", "Одна тема и ритм повторяются, меняются тембр и громкость", "Его играют на одном рояле", "Оно длится 2 минуты"], "a": 1, "e": "Огромное крещендо на одной теме."}, {"q": "Для чьей антрепризы Стравинский написал «Жар-птицу»?", "o": ["Сергея Дягилева", "Петра Чайковского", "Мариуса Петипа", "Анны Павловой"], "a": 0, "e": "«Русские сезоны» Дягилева в Париже, 1910."}], "why": ["На рубеже XIX и XX веков композиторы стали искать новые звучания, так же как художники искали новые краски. Дебюсси создал музыку-впечатление, Стравинский ошеломил публику ритмом. Отсюда растёт почти вся музыка XX века, включая саундтреки к фильмам и играм."], "groups": [{"h": "Музыкальный импрессионизм", "p": "Композиторы во Франции писали музыку, похожую на картины Моне: размытые звучания, переливы, настроение.", "items": [{"t": "Клод Дебюсси", "d": "Главный композитор-импрессионист.", "c": "Клод Дебюсси, фото ателье Надара", "more": ["Дебюсси учился в Парижской консерватории и всё время спорил с педагогами: он использовал «запрещённые» аккорды и необычные лады. В молодости он год жил в России, учил детей мецената Надежды фон Мекк и полюбил музыку Мусоргского.", "Его пьесы названы как картины: «Море», «Облака», «Шаги на снегу», «Затонувший собор». Сам он не любил слово «импрессионизм», но лучше его не придумали."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Claude_Debussy_by_Atelier_Nadar.jpg", "lic": "Public domain", "by": "Adam Cuerden", "src": "media/img/387cdf084e-1000.webp", "w": 1000, "h": 1398, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Claude_Debussy_by_Atelier_Nadar.jpg/1280px-Claude_Debussy_by_Atelier_Nadar.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Эрик Сати", "d": "Чудак, который опередил своё время.", "c": "Эрик Сати", "more": ["Сати работал пианистом в кабаре на Монмартре и одевался всегда одинаково: у него было семь одинаковых бархатных костюмов. Названия его пьес были шуточными, например «Три пьесы в форме груши».", "Его простые медленные пьесы с повторами предвосхитили минимализм и фоновую музыку. Он даже придумал «музыку-обстановку», которую не надо слушать, она просто звучит в комнате, как мебель."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Erik_Satie_portrait.jpg", "lic": "CC0", "by": "Studio Hamelle, Paris, c. 1914", "src": "media/img/32b504cbb8-1000.webp", "w": 1000, "h": 1201, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/47/Erik_Satie_portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "«Русские сезоны»", "p": "Антрепренёр Сергей Дягилев с 1909 года привозил в Париж русский балет, и это стало главным событием художественной жизни Европы.", "items": [{"t": "Балет как синтез искусств", "d": "Музыка, танец и живопись в одном спектакле.", "c": "Лев Бакст. Эскиз костюма Жар-птицы", "more": ["Дягилев не был ни танцором, ни композитором, но умел находить таланты. Для своих спектаклей он заказывал музыку молодым композиторам, а декорации и костюмы лучшим художникам: Баксту, Бенуа, потом Пикассо и Матиссу.", "Бакст придумывал костюмы с яркими восточными узорами. Эскиз Жар-птицы в огненном оперении сам по себе стал произведением искусства."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bakst_-_Oiseau_de_feu_1913.jpg", "lic": "Public domain", "by": "Léon Bakst", "src": "media/img/ebe674fa52-1000.webp", "w": 1000, "h": 1396, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Bakst_-_Oiseau_de_feu_1913.jpg/1280px-Bakst_-_Oiseau_de_feu_1913.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вацлав Нижинский", "d": "Танцовщик, который будто парил в воздухе.", "c": "Нижинский в «Послеполуденном отдыхе фавна», 1912", "more": ["Нижинский был звездой «Русских сезонов», о его прыжках ходили легенды. В 1912 году он поставил балет на музыку Дебюсси, где танцоры двигались плоско, в профиль, как на древнегреческой вазе.", "В 1913 году он поставил «Весну священную» Стравинского. На премьере публика начала свистеть, кричать и драться, это один из самых знаменитых скандалов в истории музыки. Сейчас «Весну» считают одним из главных произведений XX века."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Nijinsky_as_the_faun,_photographs_by_Adolf_de_Meyer_1912.jpg", "lic": "Public domain", "by": "Adolf de Meyer", "src": "media/img/e1a03e2e28-1000.webp", "w": 1000, "h": 1390, "remote": "https://upload.wikimedia.org/wikipedia/commons/9/99/Nijinsky_as_the_faun%2C_photographs_by_Adolf_de_Meyer_1912.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "m8", "title": "Регтайм, блюз и джаз", "period": "1890-е — 1920-е", "intro": [], "traits": ["Синкопа — смещённый, «рваный» акцент", "Регтайм: Скотт Джоплин", "Блюз: 12 тактов, блюзовые ноты", "Джаз: импровизация и свинг", "Новый Орлеан — колыбель джаза"], "works": [{"t": "Maple Leaf Rag («Регтайм кленового листа»)", "a": "Скотт Джоплин (играет автор, 1916)", "y": "1899", "d": "Самый известный регтайм. Левая рука шагает ровно, правая — синкопирует. Запись с перфоленты механического пианино, которую набил сам Джоплин.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg", "lic": "Public domain", "by": "Scott Joplin", "src": "media/audio/8857d3a7b4.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e9/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg.mp3"}, "story": ["Джоплин написал пьесу в 1899 году. Название дал клуб «Кленовый лист» в городке Седейлия, где он играл.", "Послушайте, как устроен регтайм. Левая рука шагает ровно, как марш: бас и аккорд, бас и аккорд. А правая рука играет мелодию со смещёнными акцентами, синкопами, будто спотыкается и догоняет. Отсюда название ragtime, «рваное время».", "Эта запись сделана с рулона пианолы, который в 1916 году набил сам Джоплин."]}, {"t": "Livery Stable Blues", "a": "Original Dixieland Jass Band", "y": "1917", "d": "Первая в истории изданная джазовая пластинка. Кларнет, корнет и тромбон подражают животным на конюшне.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:ODJB_Livery_Stable_Blues_1917.ogg", "lic": "Public domain", "by": "Original Dixieland Jass Band (performer); Ray Lopez, Alcide Nunez (composers)", "src": "media/audio/9ef34d8c24.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/ODJB_Livery_Stable_Blues_1917.ogg/ODJB_Livery_Stable_Blues_1917.ogg.mp3"}, "story": ["Это первая изданная джазовая пластинка, записанная в феврале 1917 года. Название значит «Блюз на конюшне».", "Кларнет изображает кудахтанье курицы, корнет ржание лошади, тромбон мычание коровы. Публике это казалось очень смешным. Музыканты играют одновременно разные мелодии, переплетая их, это типичный новоорлеанский стиль.", "Музыка звучит ещё грубо по сравнению с поздним джазом, но именно с неё начинается история джазовой звукозаписи."]}, {"t": "Рапсодия в стиле блюз", "a": "Джордж Гершвин (за роялем автор)", "y": "1924", "d": "Первая запись 1924 года. Знаменитое глиссандо кларнета в начале придумал музыкант оркестра на репетиции.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_(1924_version).ogg", "lic": "Public domain", "by": "George Gershwin and Paul Whiteman Orchestra", "src": "media/audio/3068c75e26.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/1/16/1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_%281924_version%29.ogg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"}, "story": ["Дирижёр Пол Уайтмен объявил концерт «Эксперимент в современной музыке» и анонсировал новую вещь Гершвина. Гершвин узнал об этом из газеты и написал рапсодию за пять недель. Премьера прошла 12 февраля 1924 года в Нью-Йорке.", "Начало знаменито: кларнет взлетает долгим скользящим глиссандо. Это придумал на репетиции кларнетист оркестра в шутку, а Гершвину понравилось, и он оставил.", "Здесь звучит самая первая запись 1924 года, где на фортепиано играет сам Гершвин. Рапсодия соединяет джазовые ритмы, блюзовые ноты и симфонический оркестр."]}], "quiz": [{"q": "Что такое синкопа?", "o": ["Медленный темп", "Смещение акцента на слабую долю", "Вид барабана", "Пение хором"], "a": 1, "e": "Синкопы делают ритм «рваным» и упругим — основа регтайма и джаза."}, {"q": "Кто «король регтайма»?", "o": ["Луи Армстронг", "Скотт Джоплин", "Джордж Гершвин", "Дюк Эллингтон"], "a": 1, "e": "Scott Joplin, «Maple Leaf Rag», 1899."}, {"q": "Какой город считают колыбелью джаза?", "o": ["Нью-Йорк", "Чикаго", "Новый Орлеан", "Лос-Анджелес"], "a": 2, "e": "New Orleans, конец XIX — начало XX века."}, {"q": "Что главное в джазе?", "o": ["Строгое следование нотам", "Импровизация и свинг", "Пение на латыни", "Отсутствие ритма"], "a": 1, "e": "Джазмен сочиняет прямо во время игры."}], "why": ["Джаз родился в США из встречи африканских ритмов и европейской гармонии. Это была первая музыка, которая распространилась по миру благодаря пластинкам, а не нотам. Из джаза и блюза потом выросли рок-н-ролл, соул, поп-музыка и хип-хоп. Почти всё, что звучит сегодня по радио, имеет корни здесь."], "groups": [{"h": "Регтайм", "p": "В 1890-х годах в барах и на ярмарках США зазвучала фортепианная музыка с «рваным» ритмом.", "items": [{"t": "Скотт Джоплин", "d": "«Король регтайма».", "c": "Скотт Джоплин", "more": ["Скотт Джоплин родился в семье бывших рабов в Техасе. Он учился у немецкого учителя музыки и знал европейскую классику. Регтайм он считал серьёзной музыкой и мечтал, чтобы его играли в концертных залах.", "Он написал даже оперу «Тримониша» о девушке, которая учит свой народ грамоте, но поставить её при жизни не смог. Признание пришло через полвека после его смерти, в 1970-х, когда его музыка прозвучала в фильме «Афера»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Scott_Joplin_19072.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/7766430946-1000.webp", "w": 1000, "h": 1300, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/ca/Scott_Joplin_19072.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Ноты и пианолы", "d": "Регтайм распространялся через ноты и механические пианино.", "c": "Первое издание «Maple Leaf Rag», 1899", "more": ["Ноты «Maple Leaf Rag» продавались огромными тиражами: за десять лет около полумиллиона экземпляров. Джоплин одним из первых получал проценты с продаж, а не разовую плату.", "Ещё регтайм играли пианолы, механические пианино. В них вставляли бумажный рулон с дырочками, и клавиши нажимались сами. Джоплин записал несколько своих пьес на такие рулоны, и мы можем услышать, как он играл."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Maple_Leaf_Rag_1st_ed.jpg", "lic": "Public domain", "by": "Scott Joplin", "src": "media/img/36b6f53fea-1000.webp", "w": 1000, "h": 1221, "remote": "https://upload.wikimedia.org/wikipedia/commons/f/f0/Maple_Leaf_Rag_1st_ed.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Рождение джаза", "p": "Джаз появился в Новом Орлеане, городе, где смешались африканская, французская, испанская и американская культуры.", "items": [{"t": "Первая джазовая пластинка", "d": "Белые музыканты из Нового Орлеана первыми записали джаз.", "c": "Original Dixieland Jass Band", "more": ["Джаз играли чернокожие музыканты на улицах, в барах и на похоронах Нового Орлеана. Но первую пластинку записал в 1917 году белый ансамбль из пяти человек, приехавший в Нью-Йорк.", "Пластинка разошлась тиражом больше миллиона. Сначала слово писали «jass», потом «jazz». Происхождение слова неизвестно. Так джаз за несколько месяцев узнала вся Америка, а потом и Европа."], "img": {"page": "https://commons.wikimedia.org/wiki/File:ODJBcard.JPG", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/7cba5a9c76-1000.webp", "w": 1000, "h": 615, "remote": "https://upload.wikimedia.org/wikipedia/commons/9/90/ODJBcard.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Граммофон", "d": "Пластинки разнесли джаз по миру.", "c": "Граммофон «Виктрола»", "more": ["Джаз почти не записывают нотами: музыканты импровизируют, сочиняя прямо во время игры. Поэтому его можно было сохранить и распространить только благодаря звукозаписи.", "В 1920-х граммофон появился почти в каждом американском доме. Люди учились джазу по пластинкам, и молодые музыканты по всему миру повторяли соло с записей."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Victrola_VV_J2-5_Gramophone,_Victor_Talking_Machine_Co._of_Japan,_Ltd,_undated_-_Kanazawa_Phonograph_Museum_-_Kanazawa,_Japan_-_DSC00859.jpg", "lic": "CC0", "by": "Daderot", "src": "media/img/3516c25edd-1000.webp", "w": 1000, "h": 1393, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Victrola_VV_J2-5_Gramophone%2C_Victor_Talking_Machine_Co._of_Japan%2C_Ltd%2C_undated_-_Kanazawa_Phonograph_Museum_-_Kanazawa%2C_Japan_-_DSC00859.jpg/1280px-Victrola_VV_J2-5_Gramophone%2C_Victor_Talking_Machine_Co._of_Japan%2C_Ltd%2C_undated_-_Kanazawa_Phonograph_Museum_-_Kanazawa%2C_Japan_-_DSC00859.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Джордж Гершвин", "d": "Соединил джаз и симфонию.", "c": "Гершвин на обложке журнала Time, 1925", "more": ["Джордж Гершвин был сыном русских эмигрантов из Нью-Йорка. В 15 лет он бросил школу и работал «песенным плаггером»: играл новые песни в нотном магазине, чтобы покупатели их купили.", "Он писал песни для бродвейских мюзиклов, а потом решил соединить джаз с классической музыкой. Его опера «Порги и Бесс» 1935 года с песней «Summertime» стала американской классикой. Гершвин умер в 38 лет от опухоли мозга."], "img": {"page": "https://commons.wikimedia.org/wiki/File:George_Gershwin-TIME-1925.jpg", "lic": "Public domain", "by": "Time Magazine", "src": "media/img/3bb1b08b41-1000.webp", "w": 1000, "h": 1318, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/7f/George_Gershwin-TIME-1925.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}], "lit": [{"id": "l0", "title": "Как читать литературу", "period": "Азбука", "intro": [], "traits": ["Три рода: эпос, лирика, драма", "Ямб (та-ТА) и хорей (ТА-та)", "Эпитет, метафора, сравнение, олицетворение", "Сюжет, композиция, герой, конфликт", "Классика — то, что перечитывают веками"], "works": [{"t": "Зимнее утро", "a": "Александр Пушкин", "y": "1829", "ws": "Зимнее утро (Пушкин)", "q": "Мороз и солнце; день чудесный!\nЕще ты дремлешь, друг прелестный —\nПора, красавица, проснись…", "d": "Лирика. Четырёхстопный ямб. Найдите эпитеты: «день чудесный», «друг прелестный».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Пушкин написал стихотворение в ноябре 1829 года в имении друзей в Тверской губернии. Это пример лирики: никаких событий, только радость солнечного зимнего утра и приглашение любимой на прогулку.", "Размер четырёхстопный ямб, ударение на каждом втором слоге. Найдите тропы: «мороз и солнце; день чудесный» начинается с эпитета, «под голубыми небесами великолепными коврами» снег сравнивается с коврами. Во второй строфе контраст: вечером была вьюга и мгла, а сейчас всё сияет."]}, {"t": "Ворона и Лисица", "a": "Иван Крылов", "y": "1807", "ws": "Ворона и Лисица (Крылов)", "q": "Уж сколько раз твердили миру,\nЧто лесть гнусна, вредна; но только всё не впрок,\nИ в сердце льстец всегда отыщет уголок.", "d": "Басня — эпос в миниатюре: короткий рассказ с моралью. Крылов сделал её народным жанром.", "img": {"page": "https://commons.wikimedia.org/wiki/File:0521Fc._Portrait_of_I.A._Krylov,_1839_(Karl_Bryullov).jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/55eee36680-360.webp", "w": 1000, "h": 1208, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg/1280px-0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Это басня Ивана Крылова 1807 года. Сюжет взят у французского баснописца Лафонтена, а тот брал его у Эзопа. За две с половиной тысячи лет история о льстеце, который выманивает сыр, почти не изменилась.", "Мораль стоит в самом начале: «Уж сколько раз твердили миру, что лесть гнусна, вредна». Обратите внимание на живой разговорный язык. Крылов писал так, как говорили люди на улице, поэтому его строчки легко запоминаются."]}, {"t": "К *** («Я помню чудное мгновенье…»)", "a": "Александр Пушкин", "y": "1825", "ws": "К *** («Я помню чудное мгновенье...») (Пушкин)", "q": "Я помню чудное мгновенье:\nПередо мной явилась ты,\nКак мимолетное виденье,\nКак гений чистой красоты.", "d": "Любовная лирика, посвящённая Анне Керн. Обратите внимание на сравнение «как мимолетное виденье».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Пушкин написал стихотворение в 1825 году в Михайловском, где жил в ссылке. Посвящено Анне Керн. Он впервые увидел её на балу шесть лет назад, а летом 1825 года она приехала погостить к соседям.", "Композиция кольцевая: в начале «явилась ты», в середине годы «в глуши, во мраке заточенья», в конце снова «явилась ты» и вернулись «и божество, и вдохновенье». Композитор Глинка, позже влюблённый в дочь Керн, написал на эти стихи знаменитый романс."]}], "quiz": [{"q": "К какому роду литературы относится трагедия?", "o": ["Эпос", "Лирика", "Драма", "Басня"], "a": 2, "e": "Трагедия и комедия — жанры драмы, они пишутся для сцены."}, {"q": "Какой стихотворный размер: та-ТА, та-ТА?", "o": ["Хорей", "Ямб", "Дактиль", "Анапест"], "a": 1, "e": "Ямб — ударение на второй слог стопы. «Мой дЯдя сАмых чЕстных прАвил»."}, {"q": "«Чудное мгновенье» — это пример…", "o": ["Метафоры", "Эпитета", "Рифмы", "Гиперболы"], "a": 1, "e": "Эпитет — художественное определение."}, {"q": "Басня — это…", "o": ["Лирическое стихотворение", "Короткий поучительный рассказ с моралью", "Пьеса", "Роман в письмах"], "a": 1, "e": "Басни писали Эзоп, Лафонтен, Крылов."}], "why": ["Учебники и критики говорят «эпос», «лирика», «ямб», «метафора». Эти термины помогают увидеть, как текст сделан, и понять, почему одни строчки запоминаются на всю жизнь, а другие забываются. Здесь собраны основы, а внизу три коротких текста, на которых их удобно проверить."], "groups": [{"h": "Три рода литературы", "p": "Ещё Аристотель заметил, что тексты бывают трёх типов. От рода зависит, кто говорит и как мы воспринимаем текст.", "items": [{"t": "Эпос", "d": "Рассказ о событиях: роман, повесть, рассказ, поэма, басня.", "c": "Гюстав Доре. Дон Кихот за книгами", "more": ["В эпосе есть рассказчик, который сообщает, что произошло с героями, где и когда. Это самый большой по объёму род: в него входят и короткая басня, и «Война и мир» в четырёх томах.", "Слово «эпос» греческое и значит «слово, рассказ». Первыми эпическими произведениями были героические поэмы вроде «Илиады». Роман появился гораздо позже, в эпоху Возрождения. На гравюре Доре Дон Кихот, герой одного из первых романов, сходит с ума от рыцарских книг."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Gustave_Dor%C3%A9_-_Miguel_de_Cervantes_-_Don_Quixote_-_Part_1_-_Chapter_1_-_Plate_1_%22A_world_of_disorderly_notions,_picked_out_of_his_books,_crowded_into_his_imagination%22.jpg", "lic": "Public domain", "by": "Héliodore Pisan / After Gustave Doré", "src": "media/img/dc52b046dc-1000.webp", "w": 1000, "h": 1294, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Gustave_Dor%C3%A9_-_Miguel_de_Cervantes_-_Don_Quixote_-_Part_1_-_Chapter_1_-_Plate_1_%22A_world_of_disorderly_notions%2C_picked_out_of_his_books%2C_crowded_into_his_imagination%22.jpg/1280px-thumbnail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Лирика", "d": "Стихи о чувствах и мыслях: стихотворение, ода, элегия, послание.", "c": "Кипренский. Портрет Пушкина", "more": ["В лирике нет сюжета в обычном смысле. Главное в ней переживание одного момента: любовь, грусть, восторг перед природой. Говорит лирический герой, часто очень близкий к самому поэту.", "Лирика почти всегда написана стихами. Стих держится на ритме. В русской поэзии самые частые размеры ямб, где ударение падает на каждый второй слог («Мой дЯдя сАмых чЕстных прАвил»), и хорей, где на каждый первый («БУря мглОю нЕбо крОет»)."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-1000.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Драма", "d": "Текст для сцены: трагедия, комедия, драма.", "c": "Театр «Глобус» в Лондоне, реконструкция", "more": ["Драма пишется для того, чтобы её играли актёры. Рассказчика почти нет: всё узнаём из реплик героев и коротких ремарок автора, например «уходит» или «за сценой шум».", "Трагедия заканчивается гибелью героя, комедия высмеивает пороки и кончается счастливо. Театр «Глобус», где играли пьесы Шекспира, построили в 1599 году. Он сгорел, и в 1997 году рядом построили точную копию по старым чертежам и описаниям."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Reconstruction_of_Shakespeare%27s_Globe_Theatre_-_geograph.org.uk_-_2282929.jpg", "lic": "CC BY-SA 2.0", "by": "Anthony O'Neil", "src": "media/img/d70f0e16a1-1000.webp", "w": 1000, "h": 750, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Reconstruction_of_Shakespeare%27s_Globe_Theatre_-_geograph.org.uk_-_2282929.jpg/1280px-Reconstruction_of_Shakespeare%27s_Globe_Theatre_-_geograph.org.uk_-_2282929.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Жанры и приёмы", "p": "Внутри каждого рода есть жанры. А чтобы текст действовал на читателя, писатели используют тропы, особые обороты речи.", "items": [{"t": "Басня", "d": "Короткая история с моралью, чаще про животных.", "c": "Памятник Крылову в Летнем саду, Петербург", "more": ["Басню придумали ещё в Древней Греции, её отцом считают раба Эзопа. Звери в баснях ведут себя как люди: лиса хитрит, волк грабит, осёл глупит. Так легче говорить о человеческих пороках, никого не называя прямо.", "Иван Крылов написал больше двухсот басен, и десятки фраз из них стали поговорками. Памятник ему в Летнем саду поставили в 1855 году, вокруг постамента герои его басен."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Krylov_monument_in_SPB_01.jpg", "lic": "CC BY-SA 4.0", "by": "Florstein (Telegram:WikiPhoto.Space)", "src": "media/img/3f15323e8b-1000.webp", "w": 1000, "h": 662, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Krylov_monument_in_SPB_01.jpg/1280px-Krylov_monument_in_SPB_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Тропы", "d": "Слова в переносном смысле: эпитет, сравнение, метафора, олицетворение.", "c": "Гюстав Доре. Иллюстрация к «Ворону» По", "more": ["Эпитет это выразительное определение: «чудное мгновенье». Сравнение прямо сопоставляет одно с другим: «как мимолётное виденье». Метафора это скрытое сравнение: «горит восток зарёю новой», хотя ничего не горит. Олицетворение наделяет предметы чувствами: «буря плачет».", "Без тропов текст сообщает только факты. С ними он рисует картинку и вызывает чувство. Хороший способ тренироваться: найти в любом стихотворении все тропы и спросить себя, что изменилось бы без них."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_Gustave_Dore_Raven0.jpg", "lic": "Public domain", "by": "Gustave Doré", "src": "media/img/f096ba3b21-1000.webp", "w": 1000, "h": 1409, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Paul_Gustave_Dore_Raven0.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "l1", "title": "Античность", "period": "VIII век до н. э. — V век н. э.", "intro": [], "traits": ["Эпос: Гомер, «Илиада» и «Одиссея»", "Театр: трагедия и комедия", "Мифы как основа сюжетов", "Рок, судьба, катарсис", "Рим: Вергилий, Овидий, Гораций"], "works": [{"t": "Илиада", "a": "Гомер (перевод Н. Гнедича)", "y": "VIII век до н. э.", "ws": "Илиада (Гомер; Гнедич)", "q": "Гнев, богиня, воспой Ахиллеса, Пелеева сына,\nГрозный, который ахеянам тысячи бедствий соделал…", "d": "Пятьдесят дней десятого года Троянской войны. Перевод Гнедича писан гекзаметром — размером Гомера.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["«Илиада» рассказывает не всю Троянскую войну, а около пятидесяти дней на её десятом году. Её главная тема гнев Ахиллеса, величайшего греческого воина. Царь Агамемнон отнял у него пленницу, и Ахиллес в обиде отказался сражаться.", "Без него греки проигрывают. Тогда его лучший друг Патрокл идёт в бой в доспехах Ахиллеса и погибает от руки троянского героя Гектора. Ахиллес возвращается, убивает Гектора и в ярости таскает его тело за колесницей. Поэма заканчивается тем, что старый отец Гектора ночью приходит к Ахиллесу просить тело сына, и тот, плача, отдаёт.", "На русский язык «Илиаду» перевёл Николай Гнедич, он работал над переводом больше двадцати лет. Пушкин восхищался его трудом."]}, {"t": "Одиссея", "a": "Гомер (перевод В. Жуковского)", "y": "VIII век до н. э.", "ws": "Одиссея (Гомер; Жуковский)", "q": "Муза, скажи мне о том многоопытном муже, который,\nСтранствуя долго со дня, как святой Илион им разрушен…", "d": "Циклоп, сирены, волшебница Цирцея — и верная Пенелопа, ждущая двадцать лет. Первый в мире «роман-путешествие».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["После взятия Трои царь острова Итака Одиссей десять лет плывёт домой. Он ослепил циклопа Полифема, сына бога морей Посейдона, и тот мстит ему штормами.", "По пути Одиссей встречает волшебницу Цирцею, которая превращает его спутников в свиней, проплывает мимо сирен, привязав себя к мачте, теряет всех товарищей. Тем временем дома женихи осаждают его жену Пенелопу. Она обещает выбрать одного, когда соткёт саван, и каждую ночь распускает сотканное за день.", "В конце Одиссей возвращается переодетым нищим, его узнаёт только старая собака, и он расправляется с женихами. Слово «одиссея» стало означать долгое путешествие с приключениями. Перевод Жуковского 1849 года до сих пор читают."]}, {"t": "Царь Эдип", "a": "Софокл", "y": "около 429 г. до н. э.", "ws": "Царь Эдип (Софокл; Зелинский)", "q": "", "d": "Эдип расследует убийство царя — и выясняет, что убийца он сам. Аристотель считал эту трагедию образцовой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sophocles_pushkin.jpg", "lic": "CC BY-SA 3.0", "by": "user:shakko", "src": "media/img/ffce1e9764-360.webp", "w": 1000, "h": 1358, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/19/Sophocles_pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Трагедия Софокла, около 429 года до нашей эры. Оракул предсказал, что Эдип убьёт отца и женится на матери. Родители бросили младенца, но его спасли и вырастили в другом городе.", "Узнав предсказание, Эдип бежит от тех, кого считает родителями. По дороге в ссоре убивает незнакомого старика, а потом спасает город Фивы от Сфинкса и в награду женится на овдовевшей царице. Через годы в Фивах начинается чума, и Эдип расследует, кто убил прежнего царя. Шаг за шагом он выясняет, что убийца он сам, а царица его мать.", "Главная мысль трагедии: человек не может убежать от судьбы, но может мужественно принять правду. Аристотель считал «Царя Эдипа» образцом трагедии."]}, {"t": "Метаморфозы", "a": "Овидий", "y": "8 г. н. э.", "ws": "Метаморфозы (Овидий)", "q": "", "d": "Около 250 мифов: Нарцисс, Эхо, Дедал и Икар, Орфей и Эвридика. Главная «шпаргалка» художников Возрождения и барокко.", "story": ["Римский поэт Овидий закончил поэму в 8 году нашей эры. В ней около 250 мифов, и все о превращениях, по-гречески «метаморфозах»: девушка становится деревом, юноша цветком, люди камнями и птицами.", "Здесь история Нарцисса, влюбившегося в своё отражение, Дедала и Икара, которые улетели с острова на восковых крыльях, певца Орфея, спустившегося в ад за женой. Мифы искусно связаны в одну цепочку от сотворения мира до времён Цезаря.", "В том же году император Август сослал Овидия на край империи, к Чёрному морю, и он больше не вернулся в Рим. Почему, неизвестно. «Метаморфозы» стали главным источником мифов для художников Возрождения и барокко."]}], "quiz": [{"q": "О чём рассказывает «Илиада»?", "o": ["О странствиях Одиссея", "О Троянской войне и гневе Ахиллеса", "О сотворении мира", "О Риме"], "a": 1, "e": "Илион — другое название Трои."}, {"q": "Где родился европейский театр?", "o": ["В Риме", "В Афинах", "В Египте", "В Византии"], "a": 1, "e": "Афины, V век до н. э., праздники Диониса."}, {"q": "Что такое катарсис?", "o": ["Финальная битва", "Очищение души через сострадание и страх", "Вид стиха", "Хор в трагедии"], "a": 1, "e": "Так Аристотель описал действие трагедии на зрителя."}], "why": ["Почти все сюжеты европейской литературы где-то начинаются в Греции и Риме: верный муж, который годами плывёт домой, герой, бессильный перед судьбой, любовь, превращающая людей. Выражения «троянский конь», «ахиллесова пята», «одиссея» пришли отсюда. Античная литература это словарь, на котором написаны все следующие книги."], "groups": [{"h": "Эпос Гомера", "p": "Две поэмы Гомера греки знали наизусть и учили по ним детей. Их сочинили около VIII века до нашей эры.", "items": [{"t": "Гомер", "d": "Слепой певец, о котором почти ничего не известно.", "c": "Бюст Гомера, римская копия", "more": ["Греки считали, что Гомер был слепым странствующим певцом. Семь городов спорили, кто из них его родина. Многие учёные думают, что «Илиада» и «Одиссея» сложились из песен многих сказителей и долго передавались устно.", "Поэмы написаны гекзаметром, длинным размером в шесть стоп. Его удобно было петь под лиру и запоминать. Изображения Гомера, как этот бюст, созданы через сотни лет после него, это не портрет, а представление о мудром поэте."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Portrait_Bust_of_Homer_-_British_Museum_-_Joy_of_Museums.jpg", "lic": "CC BY-SA 4.0", "by": "Joyofmuseums", "src": "media/img/9c89105a65-1000.webp", "w": 1000, "h": 1364, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Portrait_Bust_of_Homer_-_British_Museum_-_Joy_of_Museums.jpg/1280px-Portrait_Bust_of_Homer_-_British_Museum_-_Joy_of_Museums.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Троянский конь", "d": "Хитрость, которой закончилась десятилетняя война.", "c": "Ваза с Миконоса, около 670 года до н. э.", "more": ["Греки десять лет осаждали Трою и не могли её взять. Тогда хитроумный Одиссей предложил построить деревянного коня, спрятать внутри воинов и сделать вид, что флот уплыл. Троянцы втащили коня в город как трофей, а ночью греки вышли и открыли ворота.", "В «Илиаде» коня ещё нет, эта история рассказывается в «Одиссее» и у Вергилия. На этой вазе одно из самых ранних изображений: в окошках коня видны головы воинов. Сегодня «троянским конём» называют любую ловушку, которую впускают добровольно."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mykonos_vase,_relief_pithos,_capture_of_Troy,_670_BC,_AM_Mykonos,_2240,_177256.jpg", "lic": "CC BY-SA 4.0", "by": "Zde", "src": "media/img/f83e0e5651-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Mykonos_vase%2C_relief_pithos%2C_capture_of_Troy%2C_670_BC%2C_AM_Mykonos%2C_2240%2C_177256.jpg/1280px-Mykonos_vase%2C_relief_pithos%2C_capture_of_Troy%2C_670_BC%2C_AM_Mykonos%2C_2240%2C_177256.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Рождение театра", "p": "Театр появился в Афинах в VI–V веках до нашей эры из праздников в честь бога вина Диониса.", "items": [{"t": "Амфитеатр", "d": "Греческий театр строили на склоне холма.", "c": "Театр в Эпидавре, IV век до н. э.", "more": ["Театр в Эпидавре вмещал около 14 000 зрителей. Его акустика поразительна: шёпот актёра в центре круглой площадки слышен на самом верхнем ряду. Спектакли шли днём, под открытым небом.", "Каждый год в Афинах проходил конкурс драматургов. За несколько дней показывали трагедии и комедии, и жюри выбирало лучшего. Ходить в театр было гражданским делом, бедным даже выдавали деньги на билет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Theatre_of_Epidaurus,_091172.jpg", "lic": "CC BY-SA 4.0", "by": "Zde", "src": "media/img/9d265bbd6e-1000.webp", "w": 1000, "h": 666, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Theatre_of_Epidaurus%2C_091172.jpg/1280px-Theatre_of_Epidaurus%2C_091172.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Маски трагедии и комедии", "d": "Все роли играли мужчины в масках.", "c": "Мозаика с театральными масками", "more": ["Актёры носили большие маски с открытым ртом. Маска показывала зрителям на дальних рядах, кто перед ними: царь, старик, женщина, раб. Один актёр мог за спектакль сыграть несколько ролей, просто меняя маски.", "Трагедия показывала героя, которого губят судьба или собственная ошибка, и зритель переживал катарсис, очищение через страх и сострадание. Комедия высмеивала политиков и обычаи. Две маски, смеющаяся и плачущая, до сих пор символ театра."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Sousse_mosaic_theatre_masks_detail_01.JPG", "lic": "CC BY-SA 3.0", "by": "Ad Meskens", "src": "media/img/ee9ed160c9-1000.webp", "w": 1000, "h": 750, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Sousse_mosaic_theatre_masks_detail_01.JPG/1280px-Sousse_mosaic_theatre_masks_detail_01.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Рим", "p": "Римские поэты учились у греков и создали свою великую литературу на латыни.", "items": [{"t": "Вергилий", "d": "Автор «Энеиды», главной поэмы Рима.", "c": "Мозаика с Вергилием и музами, III век", "more": ["Император Август попросил Вергилия написать поэму о происхождении Рима. В «Энеиде» троянец Эней после гибели Трои плывёт в Италию и становится предком римлян. Так Рим связал себя с Гомером.", "Вергилий работал над поэмой десять лет и умер, не закончив её. Он просил её сжечь, но Август запретил. На мозаике поэт держит свиток, а рядом стоят музы истории и трагедии. Через тысячу триста лет Данте выберет Вергилия своим проводником по загробному миру."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Virgil_Mosaic_Bardo_Museum_Tunis-cropped_3.jpg", "lic": "Public domain", "by": "Virgil_Mosaic_Bardo_Museum_Tunis.jpg: Cybjorg\nderivative work: — Habib M'HENNI  ", "src": "media/img/187bfa9766-1000.webp", "w": 1000, "h": 1253, "remote": "https://upload.wikimedia.org/wikipedia/commons/8/86/Virgil_Mosaic_Bardo_Museum_Tunis-cropped_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "l2", "title": "Средневековье", "period": "V — XV век", "intro": [], "traits": ["Героический эпос и рыцарский роман", "Религиозная литература, жития", "Древнерусская литература: летописи, «Слово»", "Аллегория и символ", "Данте — мост к Возрождению"], "works": [{"t": "Слово о полку Игореве", "a": "Неизвестный автор", "y": "конец XII века", "ws": "Слово о полку Игореве", "q": "Не лѣпо ли ны бяшетъ, братие, начяти старыми словесы трудныхъ повѣстий о пълку Игоревѣ, Игоря Святъславлича?", "d": "Поход 1185 года. Рукопись нашли в конце XVIII века, а в 1812 году она сгорела в московском пожаре.", "story": ["В 1185 году новгород-северский князь Игорь Святославич без поддержки других князей пошёл в поход на кочевников-половцев. Перед походом случилось солнечное затмение, но Игорь не повернул назад. Войско было разбито, сам князь попал в плен и позже бежал.", "Неизвестный автор сделал из этого поражения призыв к русским князьям прекратить ссоры и объединиться против врагов. Знаменит «Плач Ярославны»: жена Игоря на городской стене в Путивле обращается к ветру, Днепру и солнцу с просьбой вернуть мужа.", "Рукопись нашёл в конце XVIII века коллекционер Мусин-Пушкин. Её успели напечатать в 1800 году, а в 1812 году она сгорела в московском пожаре. По «Слову» Бородин написал оперу «Князь Игорь»."]}, {"t": "Божественная комедия", "a": "Данте Алигьери (перевод Д. Мина)", "y": "1307–1321", "ws": "Божественная комедия (Данте; Мин)/ДО", "q": "Земную жизнь пройдя до половины,\nЯ очутился в сумрачном лесу…\n(перевод М. Лозинского)", "d": "Сто песен, девять кругов Ада. Проводник Данте — римский поэт Вергилий, а в Раю — возлюбленная Беатриче.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Portrait_de_Dante.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/03f2e287dc-360.webp", "w": 1000, "h": 1528, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/6f/Portrait_de_Dante.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Данте писал поэму примерно с 1307 по 1321 год. «Комедией» он назвал её потому, что она начинается мрачно, а кончается счастливо. Слово «Божественная» добавили восхищённые читатели позже.", "В 35 лет, «на половине жизни», Данте заблудился в тёмном лесу. Римский поэт Вергилий ведёт его через ад и чистилище, где Данте встречает исторических людей и своих врагов. В рай его ведёт Беатриче, девушка, которую он любил с юности и которая рано умерла.", "Данте писал не на латыни, как тогда полагалось для серьёзных книг, а на итальянском языке Флоренции. Благодаря поэме этот язык стал основой литературного итальянского."]}], "quiz": [{"q": "О чём «Слово о полку Игореве»?", "o": ["О Куликовской битве", "О походе князя Игоря на половцев", "О крещении Руси", "О Ледовом побоище"], "a": 1, "e": "Поход 1185 года."}, {"q": "Кто ведёт Данте по Аду и Чистилищу?", "o": ["Гомер", "Вергилий", "Беатриче", "Овидий"], "a": 1, "e": "Вергилий, автор «Энеиды». В Раю его сменяет Беатриче."}, {"q": "Какой эпос — французский?", "o": ["«Песнь о Нибелунгах»", "«Песнь о Роланде»", "«Беовульф»", "«Калевала»"], "a": 1, "e": "«Песнь о Роланде», XI–XII век."}], "why": ["Средневековая литература подарила нам рыцарей, легенды о короле Артуре и русские былины. А главное, именно тогда на Руси появились первые книги и летописи, из которых мы знаем свою древнюю историю. Здесь же начинается Данте, без которого не было бы итальянского языка в его нынешнем виде."], "groups": [{"h": "Летописи и эпос", "p": "Большинство книг переписывали монахи. Писали о вере, истории и героях.", "items": [{"t": "Летописи", "d": "Записи событий год за годом.", "c": "Радзивилловская летопись: княгиня Ольга в Константинополе", "more": ["Монахи-летописцы записывали события по годам: «В лето такое-то...». Самая древняя русская летопись, «Повесть временных лет», составлена в Киеве около 1113 года. Из неё мы знаем о призвании варягов, о княгине Ольге, о крещении Руси.", "Радзивилловская летопись XV века содержит больше 600 цветных миниатюр, это самая богато иллюстрированная летопись. Здесь княгиня Ольга приезжает в Константинополь к византийскому императору, где принимает крещение."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Radziwi%C5%82%C5%82_Chronicle_(miniature_of_Olga_of_Kiev_received_in_Constantinople).jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/26cbdc3b5b-1000.webp", "w": 1000, "h": 1156, "remote": "https://upload.wikimedia.org/wikipedia/commons/5/5d/Radziwi%C5%82%C5%82_Chronicle_%28miniature_of_Olga_of_Kiev_received_in_Constantinople%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Рыцарский эпос", "d": "Поэмы о подвигах рыцарей и королей.", "c": "Гибель Роланда, французская рукопись", "more": ["«Песнь о Роланде» записана во Франции около 1100 года. Рыцарь Роланд прикрывает отступление армии Карла Великого в горах и гибнет в неравном бою, не желая трубить в рог и звать на помощь, чтобы не уронить честь.", "В реальной истории 778 года отряд разбили не мусульмане, как в поэме, а местные баски. Но эпос превращает событие в образец рыцарской верности. Похожие поэмы были у немцев, «Песнь о Нибелунгах», и у испанцев, «Песнь о моём Сиде»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Grandes_chroniques_Roland.jpg", "lic": "Public domain", "by": "Simon Marmion", "src": "media/img/b9794d6fa9-1000.webp", "w": 1000, "h": 1058, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c1/Grandes_chroniques_Roland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Данте", "p": "Флорентийский поэт Данте Алигьери написал поэму, которая подвела итог всему Средневековью.", "items": [{"t": "Данте и его поэма", "d": "Путешествие через ад, чистилище и рай.", "c": "Доменико ди Микелино. Данте и три царства, 1465", "more": ["Данте был политиком во Флоренции, но в 1302 году его изгнали из города под угрозой смертной казни. Он больше никогда не вернулся домой и в изгнании написал «Божественную комедию».", "На этой картине из флорентийского собора Данте держит раскрытую книгу. Слева вход в ад, сзади гора чистилища, справа Флоренция, вверху небесные сферы рая. Город, который изгнал поэта, через полтора века повесил его портрет в главном храме."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Domenico-Di-Michelino-Dante-and-the-Three-Kingdoms.jpg", "lic": "CC0", "by": "Domenico di Michelino / After Alesso Baldovinetti", "src": "media/img/d21015d103-1000.webp", "w": 1000, "h": 784, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Domenico-Di-Michelino-Dante-and-the-Three-Kingdoms.jpg/1280px-Domenico-Di-Michelino-Dante-and-the-Three-Kingdoms.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ад Данте", "d": "Девять кругов, где грешники наказаны по своим грехам.", "c": "Гюстав Доре. Харон перевозит души", "more": ["В аду Данте девять кругов, которые сужаются, как воронка, к центру Земли. Чем тяжелее грех, тем ниже круг. Наказание связано с грехом: например, гадалки, которые пытались заглянуть в будущее, ходят с головами, повёрнутыми назад.", "Лодочник Харон из греческих мифов перевозит души через реку Ахерон. Над входом в ад надпись: «Оставь надежду, всяк сюда входящий». Иллюстрации Доре 1861 года так прославились, что многие представляют ад Данте именно по ним."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Gustave_Dor%C3%A9_-_Dante_Alighieri_-_Inferno_-_Plate_9_(Canto_III_-_Charon).jpg", "lic": "Public domain", "by": "Gustave Doré", "src": "media/img/e901f237de-1000.webp", "w": 1000, "h": 1375, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Gustave_Dor%C3%A9_-_Dante_Alighieri_-_Inferno_-_Plate_9_%28Canto_III_-_Charon%29.jpg/1280px-Gustave_Dor%C3%A9_-_Dante_Alighieri_-_Inferno_-_Plate_9_%28Canto_III_-_Charon%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "l3", "title": "Возрождение", "period": "XIV — начало XVII века", "intro": [], "traits": ["Гуманизм, земная любовь, личность", "Сонет: 14 строк (Петрарка, Шекспир)", "Новелла: Боккаччо", "Шекспир — вершина драмы", "Сервантес — рождение романа"], "works": [{"t": "Гамлет", "a": "Уильям Шекспир (перевод А. Кронеберга)", "y": "около 1600", "ws": "Гамлет (Шекспир; Кронеберг)", "q": "Быть или не быть — вот в чём вопрос.", "d": "Принц датский мстит за отца — и мучается сомнениями. Самая ставимая пьеса в мире.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Шекспир написал «Гамлета» около 1600 года. Сюжет он взял из старой скандинавской легенды о принце, мстящем за отца.", "Призрак убитого короля Дании рассказывает сыну Гамлету, что его отравил брат Клавдий, который теперь сел на трон и женился на вдове. Гамлет должен отомстить, но сомневается: а вдруг призрак лжёт? Он притворяется безумным и ставит спектакль, чтобы проверить реакцию дяди.", "Знаменитый монолог «Быть или не быть» это размышление, стоит ли жить и бороться, когда мир несправедлив. Промедление Гамлета приводит к гибели почти всех героев. Это самая ставимая пьеса в мире. Тургенев сравнивал сомневающегося Гамлета и действующего Дон Кихота как два вечных человеческих типа."]}, {"t": "Ромео и Джульетта", "a": "Уильям Шекспир", "y": "1595", "ws": "Ромео и Джульетта (Шекспир)", "q": "Нет повести печальнее на свете,\nЧем повесть о Ромео и Джульетте.\n(перевод Т. Щепкиной-Куперник)", "d": "Любовь детей враждующих семей Вероны. Из этой пьесы выросли балет Прокофьева и множество фильмов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Трагедия 1595 года. В итальянском городе Верона враждуют два знатных рода, Монтекки и Капулетти. Ромео Монтекки на балу влюбляется в Джульетту Капулетти, и они тайно венчаются.", "Всё происходит за пять дней. Ромео в драке убивает брата Джульетты и его изгоняют, а её хотят выдать замуж за другого. Монах даёт ей зелье, от которого она уснёт мёртвым сном. Ромео не получает письма о плане, видит её «мёртвой» и выпивает яд. Джульетта просыпается и закалывается.", "Шекспир показал, к чему ведёт бессмысленная вражда. Родители мирятся только над телами детей. Сюжет стал основой балета Прокофьева, мюзикла «Вестсайдская история» и десятков фильмов."]}, {"t": "Дон Кихот", "a": "Мигель де Сервантес", "y": "1605–1615", "ws": "Дон Кихот Ламанчский (Сервантес)", "q": "", "d": "Бедный идальго начитался рыцарских романов и отправился совершать подвиги со своим оруженосцем Санчо Пансой. Пародия, ставшая трагедией идеалиста.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Cervantes_J%C3%A1uregui.jpg", "lic": "Public domain", "by": "Attributed to Juan de Jáuregui", "src": "media/img/444076cb72-360.webp", "w": 1000, "h": 1312, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Cervantes_J%C3%A1uregui.jpg/1280px-Cervantes_J%C3%A1uregui.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мигель де Сервантес был солдатом, в битве потерял подвижность левой руки, пять лет провёл в плену у пиратов в Алжире, сидел в тюрьме. Первую часть «Дон Кихота» он опубликовал в 1605 году, почти в шестьдесят лет.", "Бедный идальго из Ла-Манчи начитался рыцарских романов, назвал себя Дон Кихотом и отправился совершать подвиги. Он принимает мельницы за великанов, а трактир за замок. С ним едет оруженосец Санчо Панса, простой практичный крестьянин.", "Сначала это пародия на рыцарские романы. Но постепенно смешной старик становится трогательным: он верит в справедливость в мире, где её нет. «Дон Кихота» часто называют первым современным романом, и после Библии это одна из самых переводимых книг мира."]}], "quiz": [{"q": "Сколько строк в сонете?", "o": ["8", "12", "14", "16"], "a": 2, "e": "Сонет — 14 строк: Петрарка, Шекспир, Пушкин."}, {"q": "Кто написал «Дон Кихота»?", "o": ["Шекспир", "Сервантес", "Боккаччо", "Данте"], "a": 1, "e": "Мигель де Сервантес Сааведра."}, {"q": "Чьи слова «Быть или не быть»?", "o": ["Ромео", "Гамлета", "Макбета", "Отелло"], "a": 1, "e": "Монолог принца Гамлета, III акт."}], "why": ["В эпоху Возрождения литература заговорила о живом человеке: его любви, сомнениях, характере. Изобрели книгопечатание, и книги стали доступны тысячам людей. Шекспир и Сервантес создали героев, которых знает весь мир, а их сюжеты до сих пор пересказывают в фильмах и сериалах."], "groups": [{"h": "Новые голоса", "p": "Итальянцы первыми заговорили о земной любви и обычной жизни.", "items": [{"t": "Петрарка", "d": "Отец сонета о любви.", "c": "Франческо Петрарка", "more": ["В 1327 году в церкви во французском Авиньоне молодой Франческо Петрарка увидел Лауру и любил её всю жизнь. Она была замужем и, возможно, даже не знала о его чувствах.", "Петрарка написал больше трёхсот сонетов, это стихотворения из четырнадцати строк. В них не идеальная средневековая дама, а живая женщина, которая стареет и умирает от чумы. Его сонеты станут образцом любовной лирики на триста лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Petrarch_by_Bargilla.jpg", "lic": "Public domain", "by": "Andrea del Castagno", "src": "media/img/ce4c8d040d-1000.webp", "w": 1000, "h": 1552, "remote": "https://upload.wikimedia.org/wikipedia/commons/8/8f/Petrarch_by_Bargilla.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Декамерон", "d": "Сто весёлых и печальных историй.", "c": "Иллюстрация к «Декамерону», издание 1492 года", "more": ["В 1348 году во Флоренцию пришла чума. Джованни Боккаччо придумал, как десять молодых людей уезжают на загородную виллу и десять дней рассказывают друг другу истории, чтобы отвлечься. Всего сто новелл.", "Истории о хитрых монахах, ловких любовниках, глупых мужьях, благородных героях. Это энциклопедия жизни XIV века. «Декамерон» значит «десятидневник». По нему потом писали пьесы и снимали фильмы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Boccaccio_-_Decameron,_MCCCCLXXXXII_ad_di_XX_de_giugno_-_3852856_Scan00015_(cropped)-miglior.jpg", "lic": "Public domain", "by": "Boccaccio, Giovanni", "src": "media/img/935ab0693c-1000.webp", "w": 1000, "h": 1559, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/6b/Boccaccio_-_Decameron%2C_MCCCCLXXXXII_ad_di_XX_de_giugno_-_3852856_Scan00015_%28cropped%29-miglior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Книга для всех", "p": "Изобретение печатного станка изменило всё.", "items": [{"t": "Библия Гутенберга", "d": "Первая большая книга, напечатанная в Европе.", "c": "Библия Гутенберга, около 1455", "more": ["До Гутенберга книги переписывали от руки, одна книга могла занимать год работы. Иоганн Гутенберг из немецкого Майнца придумал отливать отдельные металлические буквы и собирать из них страницы.", "Около 1455 года он напечатал Библию тиражом примерно 180 экземпляров. Сохранилось около пятидесяти, это одни из самых дорогих книг в мире. Через пятьдесят лет в Европе было напечатано уже двадцать миллионов книг."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Gutenberg_Bible,_New_York_Public_Library,_USA._Pic_01.jpg", "lic": "CC BY 2.0", "by": "Joshua Keller", "src": "media/img/3bf279466c-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Gutenberg_Bible%2C_New_York_Public_Library%2C_USA._Pic_01.jpg/1280px-Gutenberg_Bible%2C_New_York_Public_Library%2C_USA._Pic_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Театр Шекспира", "d": "Театр для всех сословий.", "c": "Театр «Глобус», Лондон", "more": ["В театре «Глобус» стоячие места у сцены стоили один пенни, столько же, сколько кружка пива. Здесь стояли подмастерья и торговцы, а богатые сидели на галереях. Спектакли шли днём при солнечном свете, без декораций.", "Шекспир был актёром и совладельцем театра. Он писал пьесы так, чтобы понравиться и простым людям, и знатным: в них драки и шутки соседствуют с философией. Женские роли играли мальчики."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Globe_Theatre,_London_-_geograph.org.uk_-_1778892.jpg", "lic": "CC BY-SA 2.0", "by": "Peter Trimming", "src": "media/img/abf3f20118-1000.webp", "w": 1000, "h": 669, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/The_Globe_Theatre%2C_London_-_geograph.org.uk_-_1778892.jpg/1280px-The_Globe_Theatre%2C_London_-_geograph.org.uk_-_1778892.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "l4", "title": "Классицизм и Просвещение", "period": "XVII — XVIII век", "intro": [], "traits": ["Правило трёх единств", "«Говорящие» фамилии, герои-маски", "Комедия высмеивает пороки (Мольер)", "Просвещение: вера в разум", "Гёте, Вольтер, Свифт, Фонвизин"], "works": [{"t": "Тартюф, или Обманщик", "a": "Мольер", "y": "1664", "ws": "Тартюф, или Обманщик (Мольер; Лихачёв)", "q": "", "d": "Лицемер-святоша втирается в доверие к богатому Оргону. Пьесу пять лет запрещали — церковь узнала себя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_(1622-1673)_-_Google_Art_Project_(cropped).jpg", "lic": "Public domain", "by": "Pierre Mignard I", "src": "media/img/483bdcde10-360.webp", "w": 1000, "h": 1134, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg/1280px-Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мольер написал комедию в 1664 году. Богатый Оргон приютил в доме нищего святошу Тартюфа и восхищается его благочестием. Все домашние видят, что Тартюф лицемер, но Оргон слепо ему верит и даже хочет отдать ему дочь и всё имущество.", "Жене Оргона приходится доказать правду: Оргон прячется под столом, пока Тартюф пытается её соблазнить. Но Тартюф уже владеет бумагами на дом. Спасает всех только вмешательство короля.", "Церковь увидела в пьесе нападение на веру, и её пять лет запрещали. Имя Тартюф стало нарицательным для лицемера."]}, {"t": "Кандид, или Оптимизм", "a": "Вольтер", "y": "1759", "ws": "Кандид, или Оптимизм (Вольтер; Сологуб)", "q": "", "d": "Философская повесть: наивный Кандид проходит через войны и бедствия, но учитель твердит, что «всё к лучшему в этом лучшем из миров». Финал: «надо возделывать свой сад».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Atelier_de_Nicolas_de_Largilli%C3%A8re,_portrait_de_Voltaire,_d%C3%A9tail_(mus%C3%A9e_Carnavalet)_-002.jpg", "lic": "Public domain", "by": "Nicolas de Largillière", "src": "media/img/75f8d54fe1-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg/1280px-Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Вольтер опубликовал повесть в 1759 году. Юноша Кандид, «простодушный», вырос в замке, где его учитель Панглос твердил, что «всё к лучшему в этом лучшем из возможных миров».", "Кандида выгоняют из замка, и он проходит через войны, землетрясение в Лиссабоне, инквизицию, пиратов, рабство. Учитель Панглос даже после всех бед повторяет, что всё к лучшему. Вольтер высмеивает этот бездумный оптимизм.", "В конце герои поселяются на маленькой ферме, и Кандид произносит знаменитое: «Надо возделывать свой сад». То есть вместо пустых рассуждений заниматься честным трудом."]}, {"t": "Фауст", "a": "Иоганн Вольфганг Гёте", "y": "1808–1832", "ws": "Фауст (Гёте)", "q": "Остановись, мгновенье, ты прекрасно!", "d": "Учёный продаёт душу Мефистофелю в обмен на мгновение полного счастья. Гёте писал «Фауста» почти 60 лет.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Goethe_(Stieler_1828).jpg", "lic": "Public domain", "by": "Joseph Karl Stieler", "src": "media/img/1b680922c8-360.webp", "w": 1000, "h": 1233, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Goethe_%28Stieler_1828%29.jpg/1280px-Goethe_%28Stieler_1828%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Иоганн Вольфганг Гёте писал «Фауста» почти шестьдесят лет, первую часть опубликовал в 1808 году, вторую закончил незадолго до смерти в 1832-м.", "Учёный доктор Фауст изучил все науки и разочаровался: знания не дали счастья. Дьявол Мефистофель предлагает договор: он исполнит любые желания, а Фауст отдаст душу, если хоть раз скажет: «Остановись, мгновенье, ты прекрасно!»", "Фауст проходит через любовь к девушке Маргарите, которая кончается трагедией, через путешествия в античный мир и государственные дела. Счастье он находит, только когда работает для людей, осушая болота. Это философская драма о смысле жизни."]}, {"t": "Горе от ума", "a": "Александр Грибоедов", "y": "1824", "ws": "Горе от ума (Грибоедов)", "q": "Карету мне, карету!", "d": "Чацкий возвращается в Москву и сталкивается с фамусовским обществом. Пушкин предсказал: половина стихов войдёт в пословицы. Так и вышло: «Счастливые часов не наблюдают».", "story": ["Александр Грибоедов был дипломатом и композитором. Комедию он закончил в 1824 году, но цензура разрешила напечатать её полностью только через сорок лет. До этого её переписывали от руки десятки тысяч людей.", "Молодой Чацкий три года был за границей и возвращается в Москву к любимой Софье. Он искренне и резко высмеивает московское общество: чинопочитание, преклонение перед всем французским, пустые разговоры. В ответ его объявляют сумасшедшим.", "Грибоедов соблюдает правила классицизма, одно место и одни сутки, а у героев «говорящие» фамилии: Молчалин, Скалозуб. Но характеры живые. Пушкин предсказал, что половина стихов войдёт в пословицы: «Счастливые часов не наблюдают», «А судьи кто?»."]}], "quiz": [{"q": "Что такое правило трёх единств?", "o": ["Три героя, три акта, три песни", "Единство места, времени и действия", "Три размера стиха", "Три рода литературы"], "a": 1, "e": "Действие пьесы — в одном месте, за сутки, с одной сюжетной линией."}, {"q": "Кому Фауст продаёт душу?", "o": ["Воланду", "Мефистофелю", "Люциферу", "Демону"], "a": 1, "e": "Мефистофель у Гёте — «часть силы той, что вечно хочет зла и вечно совершает благо»."}, {"q": "Кто главный герой «Горя от ума»?", "o": ["Онегин", "Чацкий", "Печорин", "Обломов"], "a": 1, "e": "Александр Андреевич Чацкий."}], "why": ["В XVII–XVIII веках писатели верили, что литература должна воспитывать и учить разуму. Появились строгие правила театра, первые энциклопедии и сатира на глупость и лицемерие. В России в это время рождается современный литературный язык. Многие выражения, например «Карету мне, карету!», пришли отсюда."], "groups": [{"h": "Классицизм: правила и мораль", "p": "Пьеса должна была соблюдать три единства: одно место, одни сутки, одна сюжетная линия.", "items": [{"t": "Мольер", "d": "Комедии, которые высмеивают пороки.", "c": "Иллюстрация к «Тартюфу», XVIII век", "more": ["Жан-Батист Поклен взял псевдоним Мольер и стал актёром, а потом руководителем труппы. Король Людовик XIV покровительствовал ему. Мольер высмеивал скупцов, лжеучёных, мнимых больных, и зрители узнавали в героях знакомых.", "Он умер почти на сцене: в 1673 году играл главную роль в своей комедии «Мнимый больной», ему стало плохо во время спектакля, и через несколько часов его не стало. Французский театр «Комеди Франсез» до сих пор называют «Домом Мольера»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Oeuvres_de_Moli%C3%A8re_-Le_Tartuffe_-_Bret_-_Jean-Baptiste_Simonet.jpg", "lic": "Public domain", "by": "Jean-Baptiste Blaise Simonet / After Jean-Michel Moreau", "src": "media/img/657c4d8e10-1000.webp", "w": 1000, "h": 1657, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/6e/Oeuvres_de_Moli%C3%A8re_-Le_Tartuffe_-_Bret_-_Jean-Baptiste_Simonet.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Просвещение: вера в разум", "p": "Философы XVIII века считали, что знания и разум сделают людей лучше и свободнее.", "items": [{"t": "Энциклопедия", "d": "Всё знание мира в одном издании.", "c": "Фронтиспис «Энциклопедии», 1772", "more": ["Французы Дени Дидро и Жан Д’Аламбер больше двадцати лет издавали «Энциклопедию» в 28 томах, с 1751 по 1772 год. В ней объяснялись науки, ремёсла, машины, философия.", "Церковь и власти её запрещали: там критиковали суеверия и несправедливость. На гравюре в центре Истина в покрывале, а Разум и Философия снимают с неё покров. Энциклопедия подготовила умы к Французской революции."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Encyclopedie_frontispice_full.jpg", "lic": "Public domain", "by": "Benoît-Louis Prévost / Charles-Nicolas Cochin", "src": "media/img/37103fbf95-1000.webp", "w": 1000, "h": 1576, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Encyclopedie_frontispice_full.jpg/1280px-Encyclopedie_frontispice_full.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Сатира", "d": "Смех над обществом под видом сказки.", "c": "Гулливер в Лилипутии", "more": ["Ирландец Джонатан Свифт в 1726 году опубликовал «Путешествия Гулливера». Корабельный врач попадает к крошечным лилипутам, к великанам, на летающий остров учёных и в страну умных лошадей.", "Детям это сказка, а взрослым злая сатира. Лилипуты ведут войну из-за того, с какого конца разбивать яйцо, так Свифт высмеивал религиозные споры и партии Англии. Здесь Гулливер стоит, а армия лилипутов маршем проходит у него между ног."], "img": {"page": "https://commons.wikimedia.org/wiki/File:D%C3%A9fil%C3%A9_des_troupes_de_Lilliput.jpg", "lic": "CC BY-SA 4.0", "by": "Martien19", "src": "media/img/7303539687-1000.webp", "w": 1000, "h": 1291, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/D%C3%A9fil%C3%A9_des_troupes_de_Lilliput.jpg/1280px-D%C3%A9fil%C3%A9_des_troupes_de_Lilliput.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ломоносов", "d": "Создатель русского литературного языка.", "c": "Михаил Ломоносов, 1757", "more": ["Сын рыбака из-под Архангельска пешком пришёл в Москву учиться. Ломоносов стал учёным в химии, физике, географии, основал Московский университет.", "Он же разработал правила русского стихосложения и предложил деление слов на высокий, средний и низкий «штили». Его оды писались ямбом, который потом стал главным размером русской поэзии от Пушкина до наших дней."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_Lomonosov_(1757).jpg", "lic": "Public domain", "by": "Wortmann Christian-Albert, Fessard Etienne", "src": "media/img/7f8cca7a24-1000.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Mikhail_Lomonosov_%281757%29.jpg/1280px-Mikhail_Lomonosov_%281757%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "l5", "title": "Романтизм: от Байрона до Лермонтова", "period": "конец XVIII — середина XIX века", "intro": [], "traits": ["Романтический герой: одиночка и бунтарь", "Двоемирие: мечта против реальности", "Экзотика, история, фольклор", "Байрон, Гюго, Скотт, По", "Пушкин и Лермонтов — от романтизма к реализму"], "works": [{"t": "Евгений Онегин", "a": "Александр Пушкин", "y": "1823–1831", "ws": "Евгений Онегин (Пушкин)", "q": "Мой дядя самых честных правил,\nКогда не в шутку занемог,\nОн уважать себя заставил\nИ лучше выдумать не мог.", "d": "Роман в стихах. Пушкин придумал для него особую «онегинскую строфу» из 14 строк.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Пушкин писал роман в стихах почти восемь лет, с 1823 по 1831 год. Для него он придумал особую «онегинскую строфу» из 14 строк с определённым порядком рифм.", "Скучающий петербургский денди Онегин приезжает в деревню. Юная Татьяна Ларина влюбляется в него и пишет письмо с признанием. Онегин холодно отвечает ей отповедью. Потом от скуки он флиртует с невестой своего друга Ленского, тот вызывает его на дуэль, и Онегин убивает друга.", "Через несколько лет Онегин встречает Татьяну в Петербурге, она замужем за генералом. Теперь он влюблён, но она отвечает: «Я вас люблю... но я другому отдана; я буду век ему верна». Критик Белинский назвал роман «энциклопедией русской жизни»."]}, {"t": "Капитанская дочка", "a": "Александр Пушкин", "y": "1836", "ws": "Капитанская дочка (Пушкин)", "q": "Береги честь смолоду.", "d": "Исторический роман о Пугачёвском бунте. Эпиграф — пословица, ставшая девизом героя Петра Гринёва.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Пушкин опубликовал повесть в 1836 году. Он сам ездил в Оренбургские степи, расспрашивал стариков о восстании Пугачёва и написал о нём историческое исследование.", "Молодой дворянин Пётр Гринёв едет служить в глухую Белогорскую крепость и влюбляется в Машу, дочь коменданта. Крепость захватывает Емельян Пугачёв. Гринёва спасает то, что однажды в метель он подарил бродяге свой заячий тулуп. Бродягой оказался Пугачёв.", "Эпиграф «Береги честь смолоду» становится главной мыслью: Гринёв не изменяет присяге даже под угрозой смерти. Пушкин показал Пугачёва не только злодеем, но и живым человеком."]}, {"t": "Герой нашего времени", "a": "Михаил Лермонтов", "y": "1840", "ws": "Герой нашего времени (Лермонтов)", "q": "Я ехал на перекладных из Тифлиса.", "d": "Пять повестей о Печорине — «лишнем человеке», умном и разочарованном. Первый русский психологический роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Лермонтов опубликовал роман в 1840 году. Он состоит из пяти повестей, и они идут не по порядку событий. Сначала мы видим Печорина глазами других, а потом читаем его собственный дневник.", "Григорий Печорин умён, храбр, привлекателен, но ему скучно жить. Он похищает черкешенку Бэлу, ради забавы влюбляет в себя княжну Мери, убивает на дуэли Грушницкого. Всем, кто рядом, он приносит несчастье, и сам это понимает.", "Лермонтов писал в предисловии, что это портрет пороков целого поколения. Это первый русский психологический роман, где главное не события, а внутренний мир героя."]}, {"t": "Мцыри", "a": "Михаил Лермонтов", "y": "1839", "ws": "Мцыри (Лермонтов)", "q": "", "d": "Романтическая поэма: юноша-послушник бежит из монастыря на три дня свободы. Исповедь бунтаря.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Лермонтов написал поэму в 1839 году. Поводом стал рассказ старого монаха, которого ребёнком взяли в плен и оставили в грузинском монастыре.", "Мальчик-горец растёт в монастыре, но тоскует по родине и свободе. Перед постригом он сбегает. Три дня на воле он видит красоту природы, встречает грузинскую девушку, побеждает барса в схватке. Но заблудился и вернулся к стенам монастыря умирать.", "Почти вся поэма это исповедь Мцыри старому монаху. «Мцыри» по-грузински значит и «послушник», и «чужеземец». Это гимн свободе: три дня на воле дороже для героя всей жизни в неволе."]}, {"t": "Собор Парижской Богоматери", "a": "Виктор Гюго", "y": "1831", "ws": "Собор Парижской Богоматери (Гюго)", "q": "", "d": "Эсмеральда, звонарь Квазимодо и мрачный Фролло. Роман спас собор: после него Париж начал реставрацию готического шедевра.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg", "lic": "Public domain", "by": "Étienne Carjat", "src": "media/img/6b06b66375-360.webp", "w": 1000, "h": 1230, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg/1280px-Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Виктор Гюго опубликовал роман в 1831 году. Действие происходит в 1482 году, в Париже Средних веков.", "Цыганка Эсмеральда танцует на площади перед собором. В неё влюблены сразу трое: суровый священник Клод Фролло, красавец-капитан Феб и горбатый звонарь Квазимодо. Фролло из ревности ранит Феба и обвиняет Эсмеральду. Квазимодо спасает её и прячет в соборе, но в конце её казнят.", "Гюго написал роман, чтобы защитить старый собор, который тогда разрушался и мог быть снесён. Книга сделала собор знаменитым, и в 1844 году его начали реставрировать."]}, {"t": "Ворон", "a": "Эдгар По (перевод В. Брюсова)", "y": "1845", "ws": "Ворон (По; Брюсов)", "q": "", "d": "Ночью к тоскующему по умершей Ленор приходит ворон и твердит одно слово: «Nevermore» — «никогда».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Allan_Poe_daguerreotype_crop.png", "lic": "Public domain", "by": "Unknown authorUnknown author; most likely George C. Gilchrest, Samuel P. Howes, ", "src": "media/img/04d08822cc-360.webp", "w": 1000, "h": 1400, "remote": "https://upload.wikimedia.org/wikipedia/commons/8/84/Edgar_Allan_Poe_daguerreotype_crop.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Американец Эдгар По опубликовал стихотворение в 1845 году, и оно сразу прославило его.", "Глухой ночью герой тоскует по умершей возлюбленной Ленор. В окно влетает ворон и садится на бюст богини мудрости Афины. На все вопросы героя он отвечает одним словом «Nevermore», «никогда». Увидит ли герой Ленор на небесах? «Никогда».", "По объяснял, что выбрал слово ради звучания: долгое «о» и «р» передают тоску. Стихотворение очень музыкальное, с внутренними рифмами. На русский его переводили Бальмонт, Брюсов и многие другие."]}], "quiz": [{"q": "Кто назвал «Евгения Онегина» «энциклопедией русской жизни»?", "o": ["Гоголь", "Белинский", "Толстой", "Тургенев"], "a": 1, "e": "Критик Виссарион Белинский."}, {"q": "Какой роман считают первым русским психологическим романом?", "o": ["«Евгений Онегин»", "«Герой нашего времени»", "«Мёртвые души»", "«Обломов»"], "a": 1, "e": "Лермонтов, 1840 год, герой — Григорий Печорин."}, {"q": "Типичный романтический герой — это…", "o": ["Добропорядочный чиновник", "Одинокий бунтарь в конфликте с обществом", "Весёлый крестьянин", "Мудрый правитель"], "a": 1, "e": "Байронический герой: изгнанник, гордец, мечтатель."}, {"q": "Что твердит ворон в стихотворении Эдгара По?", "o": ["«Forever»", "«Nevermore»", "«Remember»", "«Goodbye»"], "a": 1, "e": "«Nevermore» — «никогда больше»."}], "why": ["Романтизм сделал главным героем литературы мятежную одинокую личность. Именно в эту эпоху русская литература стала великой: Пушкин и Лермонтов создали язык, на котором мы говорим и пишем до сих пор. Если вы хотите понять, откуда взялись Онегин, Печорин и всё, что читают в школе, начинать нужно здесь."], "groups": [{"h": "Европейские романтики", "p": "Романтизм пришёл из Англии и Германии и охватил всю Европу.", "items": [{"t": "Байрон", "d": "Поэт, который сам жил как романтический герой.", "c": "Лорд Байрон в албанском костюме, 1813", "more": ["Английский лорд Джордж Байрон путешествовал по Греции и Турции и писал поэмы о гордых изгнанниках, которые бросают вызов обществу. Его героев стали называть «байроническими». Молодёжь Европы подражала ему в одежде и манерах.", "В 1824 году Байрон поехал помогать грекам в войне за независимость от Турции и умер там от лихорадки в 36 лет. Пушкин и Лермонтов в молодости увлекались Байроном."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lord_Byron_in_Albanian_Dress_by_Phillips,_1813.jpg", "lic": "Public domain", "by": "Thomas Phillips", "src": "media/img/da5ac5a2f9-1000.webp", "w": 1000, "h": 1262, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Lord_Byron_in_Albanian_Dress_by_Phillips%2C_1813.jpg/1280px-Lord_Byron_in_Albanian_Dress_by_Phillips%2C_1813.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вальтер Скотт", "d": "Создатель исторического романа.", "c": "Генри Реберн. Портрет Вальтера Скотта", "more": ["Шотландец Вальтер Скотт придумал новый жанр: роман, где вымышленные герои живут в реальную историческую эпоху и встречают настоящих королей и полководцев. Так написаны «Айвенго» и «Роб Рой».", "Его читала вся Европа. Под его влиянием Пушкин написал «Капитанскую дочку», а Гюго «Собор Парижской Богоматери»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Sir_Henry_Raeburn_-_Portrait_of_Sir_Walter_Scott.jpg", "lic": "Public domain", "by": "Henry Raeburn", "src": "media/img/69a906de68-1000.webp", "w": 1000, "h": 1213, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Sir_Henry_Raeburn_-_Portrait_of_Sir_Walter_Scott.jpg/1280px-Sir_Henry_Raeburn_-_Portrait_of_Sir_Walter_Scott.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Пушкин и Лермонтов", "p": "Два поэта, чьи жизни трагически оборвались на дуэлях, начали золотой век русской литературы.", "items": [{"t": "Дуэль Пушкина", "d": "Самая известная дуэль русской истории.", "c": "Адриан Наумов. Дуэль Пушкина с Дантесом, 1884", "more": ["Пушкин создал современный русский литературный язык: соединил книжную речь, разговорную и народную. До него русская литература писалась тяжело и старомодно, после него так, как мы пишем сейчас.", "В 1837 году француз Жорж Дантес настойчиво ухаживал за женой Пушкина, по Петербургу пошли сплетни. Пушкин вызвал его на дуэль и был смертельно ранен. Ему было 37 лет. Лермонтов в ответ написал стихотворение «Смерть поэта» и за это был сослан на Кавказ."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pushkin%27s_duel_with_d%27Anthes,_atrist_A._Naumov_1884.jpg", "lic": "Public domain", "by": "В стиле Наумов, Алексей Аввакумович", "src": "media/img/73042fd2fd-1000.webp", "w": 1000, "h": 613, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Pushkin%27s_duel_with_d%27Anthes%2C_atrist_A._Naumov_1884.jpg/1280px-Pushkin%27s_duel_with_d%27Anthes%2C_atrist_A._Naumov_1884.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Лермонтов-художник", "d": "Лермонтов не только писал, но и рисовал.", "c": "Лермонтов. Эпизод сражения при Валерике, 1840", "more": ["На Кавказе Лермонтов служил офицером, участвовал в боях. Он хорошо рисовал и писал маслом пейзажи гор. Этот рисунок изображает битву на реке Валерик, о которой он написал и стихотворение.", "Кавказ стал главным местом его поэзии: «Мцыри», «Демон», «Герой нашего времени». В 1841 году Лермонтова убил на дуэли в Пятигорске его бывший товарищ Мартынов. Поэту было 26 лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Paintings_by_Mikhail_Lermontov,_1840,_Valerik.jpg", "lic": "Public domain", "by": "Mikhail Lermontov / Grigory Gagarin", "src": "media/img/becacfad9a-1000.webp", "w": 1000, "h": 876, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Paintings_by_Mikhail_Lermontov%2C_1840%2C_Valerik.jpg/1280px-Paintings_by_Mikhail_Lermontov%2C_1840%2C_Valerik.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "l6", "title": "Реализм в Европе", "period": "XIX век", "intro": [], "traits": ["Типичные характеры в типичных обстоятельствах", "Социальная тема: деньги, классы, среда", "Роман — главный жанр", "Франция: Бальзак, Стендаль, Флобер", "Англия: Остин, Диккенс, Бронте"], "works": [{"t": "Шагреневая кожа", "a": "Оноре де Бальзак", "y": "1831", "ws": "Шагреневая кожа (Бальзак; Аверкиев)", "q": "", "d": "Талисман исполняет любое желание, но каждое желание сокращает кожу — и жизнь владельца. Философская притча о цене страстей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Honor%C3%A9_de_Balzac_(1842)_Detail.jpg", "lic": "Public domain", "by": "Louis-Auguste Bisson", "src": "media/img/7047817b44-360.webp", "w": 1000, "h": 909, "remote": "https://upload.wikimedia.org/wikipedia/commons/e/e6/Honor%C3%A9_de_Balzac_%281842%29_Detail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Бальзак опубликовал роман в 1831 году. Молодой разорившийся аристократ Рафаэль собирается броситься в Сену, но заходит в антикварную лавку. Старик-торговец даёт ему кусок шагреневой кожи, выделанной ослиной шкуры, с надписью.", "Кожа исполняет любые желания, но с каждым желанием уменьшается, а вместе с ней сокращается жизнь владельца. Рафаэль получает богатство и любовь и начинает бояться чего-либо хотеть. Он живёт затворником, а кожа всё сжимается.", "Это философская притча: страсти и желания сжигают человеческую жизнь. Бальзак соединил фантастику с точным реалистическим описанием Парижа."]}, {"t": "Госпожа Бовари", "a": "Гюстав Флобер", "y": "1856", "ws": "Госпожа Бовари (Флобер; Ромм)", "q": "", "d": "Провинциальная жена врача мечтает о романтической жизни из книг. Флобер якобы сказал: «Эмма — это я».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Gustave_Flaubert.jpg", "lic": "Public domain", "by": "Nadar", "src": "media/img/907809b4ae-360.webp", "w": 1000, "h": 1102, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/4f/Gustave_Flaubert.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Гюстав Флобер писал роман пять лет и опубликовал в 1857 году. Его сразу отдали под суд за «оскорбление морали», но оправдали.", "Эмма в юности начиталась романтических романов и мечтает о страстной любви и красивой жизни. Она выходит замуж за доброго, но скучного провинциального врача Шарля Бовари. Скука толкает её на измены и огромные долги. Не найдя выхода, она отравляется мышьяком.", "Флобер подолгу искал каждое слово и мог неделю переписывать одну страницу. Сам он не осуждает героиню и не жалеет её, а точно показывает, как мечты, оторванные от жизни, разрушают человека. Есть легенда, что он сказал: «Эмма это я»."]}, {"t": "Оливер Твист", "a": "Чарльз Диккенс", "y": "1838", "ws": "Оливер Твист (Диккенс)", "q": "", "d": "Сирота из работного дома попадает в банду лондонских воров. Диккенс заставил Англию увидеть детскую нищету.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Charles_Dickens_3.jpg", "lic": "Public domain", "by": "", "src": "media/img/310a6413ba-360.webp", "w": 1000, "h": 970, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/48/Charles_Dickens_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Диккенс публиковал роман частями в 1837–1839 годах. Мальчик-сирота Оливер растёт в работном доме, где детей морят голодом. Однажды он просит добавки каши, и это вызывает скандал.", "Сбежав в Лондон, Оливер попадает в банду, где старый Феджин учит мальчишек воровать. Его втягивают в кражи, но он сохраняет доброту. В конце выясняется, что Оливер из хорошей семьи, и он находит дом.", "Роман потряс читателей описанием детской нищеты. Фраза Оливера «Пожалуйста, сэр, я хочу ещё» стала одной из самых известных в английской литературе."]}], "quiz": [{"q": "Как называется цикл романов Бальзака?", "o": ["«Ругон-Маккары»", "«Человеческая комедия»", "«В поисках утраченного времени»", "«Сага о Форсайтах»"], "a": 1, "e": "«Человеческая комедия» — отсылка к «Божественной комедии» Данте."}, {"q": "Какой жанр — главный для реализма?", "o": ["Ода", "Роман", "Сонет", "Трагедия"], "a": 1, "e": "Роман позволяет показать общество широко и подробно."}, {"q": "Кто автор «Оливера Твиста»?", "o": ["Теккерей", "Диккенс", "Остин", "Скотт"], "a": 1, "e": "Чарльз Диккенс."}], "why": ["В XIX веке роман стал главным способом понять общество. Писатели-реалисты изучали людей почти как учёные: показывали, как деньги, сословие и среда определяют судьбу. Читая их, вы видите Европу того времени изнутри, от парижских гостиных до лондонских трущоб."], "groups": [{"h": "Франция", "p": "Париж был столицей европейской культуры, и французские романисты описывали его во всех подробностях.", "items": [{"t": "Бальзак", "d": "Задумал описать всё общество в сотне романов.", "c": "Оноре де Бальзак, фото 1842", "more": ["Оноре де Бальзак работал по ночам, выпивая десятки чашек крепкого кофе, и написал около девяноста романов и повестей. Он объединил их в цикл «Человеческая комедия», отсылка к «Божественной комедии» Данте.", "В его книгах больше двух тысяч персонажей, и многие переходят из романа в роман. Бальзак показывал, как власть денег меняет людей: банкиры, ростовщики, карьеристы, обнищавшие аристократы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Balzac_Bisson_Nadar.png", "lic": "Public domain", "by": "Paul Nadar", "src": "media/img/ded302a4b3-1000.webp", "w": 1000, "h": 1290, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c1/Balzac_Bisson_Nadar.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Англия", "p": "Англия была самой богатой страной мира и одновременно страной с огромной бедностью.", "items": [{"t": "Джейн Остин", "d": "Ироничные романы о жизни провинциального дворянства.", "c": "Портрет работы сестры Кассандры, около 1810", "more": ["Джейн Остин жила в небольших городках на юге Англии, никогда не была замужем и публиковала романы без имени, «от одной леди». Это единственный достоверный её портрет, набросок сестры.", "Её романы, например «Гордость и предубеждение», о том, как молодые девушки ищут мужа, ведь без брака у них почти не было будущего. Остин пишет с тонкой иронией, у неё живые диалоги и точные характеры. По её книгам сняты десятки фильмов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:CassandraAusten-JaneAusten(c.1810)_hires.jpg", "lic": "Public domain", "by": "Cassandra Austen", "src": "media/img/bde2e45bcb-1000.webp", "w": 1000, "h": 1290, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/CassandraAusten-JaneAusten%28c.1810%29_hires.jpg/1280px-CassandraAusten-JaneAusten%28c.1810%29_hires.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Диккенс", "d": "Самый популярный писатель Англии своего времени.", "c": "Уильям Фрит. Портрет Диккенса, 1859", "more": ["В двенадцать лет Чарльз Диккенс работал на фабрике, наклеивая этикетки на банки с ваксой, пока его отец сидел в долговой тюрьме. Этот опыт он не забыл никогда.", "Его романы выходили по частям в журналах, и читатели ждали каждый выпуск. Диккенс заставил Англию увидеть бедность, детский труд, жестокость работных домов и тюрем. Его книги помогли изменить законы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Charles_Dickens_by_Frith_1859.jpg", "lic": "Public domain", "by": "William Powell Frith", "src": "media/img/4a7e092317-1000.webp", "w": 1000, "h": 1256, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/db/Charles_Dickens_by_Frith_1859.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Иллюстрации Крукшенка", "d": "Романы выходили с картинками.", "c": "Джордж Крукшенк. «Последний шанс», «Оливер Твист»", "more": ["Каждый выпуск романа Диккенса сопровождали гравюры. Джордж Крукшенк проиллюстрировал «Оливера Твиста» так выразительно, что потом даже утверждал, будто часть сюжета придумал сам.", "Здесь бандит Билл Сайкс, загнанный толпой на крышу, пытается спастись по верёвке. Иллюстрации помогали читателям, многие из которых только недавно научились читать."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Cruikshank_-_The_Last_Chance_(Oliver_Twist).png", "lic": "Public domain", "by": "", "src": "media/img/db81d4d575-1000.webp", "w": 1000, "h": 1262, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/40/Cruikshank_-_The_Last_Chance_%28Oliver_Twist%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "l7", "title": "Золотой век русской прозы", "period": "1840 — 1880-е", "intro": [], "traits": ["«Маленький человек» (Гоголь)", "«Лишний человек» (Онегин, Печорин, Обломов)", "Психологизм: «диалектика души»", "Нравственные и религиозные вопросы", "Гоголь, Тургенев, Достоевский, Толстой"], "works": [{"t": "Шинель", "a": "Николай Гоголь", "y": "1842", "ws": "Шинель (Гоголь)", "q": "", "d": "Бедный чиновник Акакий Акакиевич копит на новую шинель — и её крадут. Классическая повесть о «маленьком человеке».", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Николай Гоголь опубликовал повесть в 1842 году. Бедный мелкий чиновник Акакий Акакиевич Башмачкин всю жизнь переписывает бумаги, и это его единственная радость. Над ним смеются сослуживцы.", "Его старая шинель совсем износилась, и он долгие месяцы экономит на еде и свечах, чтобы сшить новую. Шинель становится смыслом его жизни. В первый же вечер её отнимают грабители. Акакий Акакиевич идёт за помощью к «значительному лицу», тот кричит на него, и бедняк умирает от горя и простуды.", "После смерти по Петербургу бродит призрак, срывающий шинели с прохожих. Это главная повесть о «маленьком человеке». Есть известная фраза, что вся русская литература «вышла из гоголевской шинели»."]}, {"t": "Мёртвые души", "a": "Николай Гоголь", "y": "1842", "ws": "Мёртвые души (Гоголь)", "q": "И какой же русский не любит быстрой езды?", "d": "Чичиков скупает умерших крестьян, числящихся живыми. Галерея помещиков — Манилов, Коробочка, Ноздрёв, Собакевич, Плюшкин.", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Гоголь опубликовал первый том в 1842 году. Сюжет ему подсказал Пушкин. В России крепостных крестьян называли «душами», и перепись проводили раз в несколько лет. Умершие числились живыми до следующей переписи.", "Ловкий Павел Чичиков ездит по помещикам и скупает умерших крестьян по документам. Он хочет заложить их в банк как живых и разбогатеть. Каждый помещик это отдельный портрет: мечтательный Манилов, жадная Коробочка, буйный Ноздрёв, грубый Собакевич, скупой до безумия Плюшкин.", "Гоголь назвал роман поэмой и хотел написать три тома, как «Божественную комедию». Второй том он сжёг незадолго до смерти. «Мёртвые души» это и помещики, у которых умерли души."]}, {"t": "Отцы и дети", "a": "Иван Тургенев", "y": "1862", "ws": "Отцы и дети (Тургенев)", "q": "Природа не храм, а мастерская, и человек в ней работник.", "d": "Нигилист Базаров против «отцов»-либералов. Конфликт поколений, который вечно актуален.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Turgenev_by_Repin.jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/c3e7d708bf-360.webp", "w": 1000, "h": 1304, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Turgenev_by_Repin.jpg/1280px-Turgenev_by_Repin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Иван Тургенев опубликовал роман в 1862 году, сразу после отмены крепостного права. Молодой врач Евгений Базаров приезжает с другом в имение его отца.", "Базаров называет себя нигилистом, человеком, который ничего не принимает на веру. Он отвергает искусство, любовь и традиции и верит только в науку. Он постоянно спорит со старшим поколением, особенно с изящным Павлом Петровичем. Дело доходит до дуэли.", "Потом Базаров сам влюбляется, и его теория рушится. Он умирает, заразившись во время вскрытия. Роман вызвал огромные споры: молодые считали, что Тургенев их оклеветал, а старшие, что он им льстит. Слово «нигилист» после этой книги вошло во все языки."]}, {"t": "Преступление и наказание", "a": "Фёдор Достоевский", "y": "1866", "ws": "Преступление и наказание (Достоевский)", "q": "Тварь ли я дрожащая или право имею…", "d": "Студент Раскольников убивает старуху-процентщицу, чтобы проверить свою теорию. Роман о совести и искуплении.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/223d7771e2-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/1280px-Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Достоевский опубликовал роман в 1866 году. Бывший студент Родион Раскольников живёт в нищете в каморке в Петербурге. Он придумал теорию: люди делятся на «тварей дрожащих» и «право имеющих», которым позволено переступить закон ради великой цели.", "Чтобы проверить себя, он убивает топором старуху-процентщицу и случайно её сестру. После убийства его мучает совесть, он заболевает. Следователь Порфирий Петрович догадывается обо всём и ведёт с ним психологическую игру.", "Спасает Раскольникова Соня Мармеладова, бедная девушка, которая ради семьи вынуждена продавать себя, но сохранила веру. Он признаётся и едет на каторгу, Соня следует за ним. Роман о том, что никакая идея не оправдывает убийства."]}, {"t": "Война и мир", "a": "Лев Толстой", "y": "1865–1869", "ws": "Война и мир", "q": "— Eh bien, mon prince. Gênes et Lucques ne sont plus que des apanages…", "d": "Роман-эпопея о войне 1812 года: Наташа Ростова, Пьер Безухов, Андрей Болконский. Около 600 персонажей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Толстой писал роман шесть лет, с 1863 по 1869 год. В нём больше 550 персонажей, в том числе реальные Наполеон, Александр I и Кутузов. Около четверти текста на французском: на нём тогда говорила русская знать.", "Действие идёт с 1805 по 1820 год, через войны с Наполеоном и пожар Москвы 1812 года. В центре три героя: задумчивый неуклюжий Пьер Безухов, гордый князь Андрей Болконский и живая, искренняя Наташа Ростова.", "Толстой показывает, что историю делают не великие полководцы, а миллионы обычных людей. Князь Андрей, раненный под Аустерлицем, смотрит в небо и понимает, как ничтожна слава. Наташа взрослеет на глазах у читателя. Роман о том, как жить, любить и находить смысл."]}, {"t": "Анна Каренина", "a": "Лев Толстой", "y": "1878", "ws": "Анна Каренина (Толстой)", "q": "Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему.", "d": "Две линии: трагическая любовь Анны и Вронского и поиски смысла Константином Лёвиным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Толстой опубликовал роман в 1878 году. Знаменитая первая фраза: «Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему».", "Анна, жена важного чиновника Каренина, влюбляется в молодого офицера Вронского. Она уходит от мужа, но общество отвергает её, а с сыном ей запрещают видеться. Ревность и одиночество доводят её до отчаяния, и она бросается под поезд.", "Вторая линия о Константине Лёвине, помещике, который ищет смысл жизни в честном труде, семье и вере. Две судьбы противопоставлены: страсть, разрушающая жизнь, и тихое счастье, которое приходит через поиск."]}], "quiz": [{"q": "Кто главный герой «Шинели»?", "o": ["Чичиков", "Акакий Акакиевич", "Раскольников", "Базаров"], "a": 1, "e": "Акакий Акакиевич Башмачкин."}, {"q": "Кем называет себя Базаров?", "o": ["Романтиком", "Нигилистом", "Славянофилом", "Декабристом"], "a": 1, "e": "Нигилист — человек, который ничего не принимает на веру."}, {"q": "Какая война в центре «Войны и мира»?", "o": ["Крымская", "Отечественная 1812 года", "Русско-турецкая", "Первая мировая"], "a": 1, "e": "Наполеоновские войны и 1812 год."}, {"q": "Что скупает Чичиков?", "o": ["Землю", "Мёртвые души — умерших крестьян", "Лошадей", "Картины"], "a": 1, "e": "Чтобы заложить их как живых в Опекунский совет."}], "why": ["Во второй половине XIX века русская литература стала мировой. Достоевского и Толстого читают на всех континентах, по их книгам учатся писатели и психологи. Именно здесь появились главные вопросы русской культуры: кто виноват, что делать, есть ли Бог и как жить честно. Эту главу полезно прочитать перед тем, как браться за сами романы."], "groups": [{"h": "Главные писатели", "p": "Они жили в одно время, знали друг друга, спорили, иногда ссорились на годы.", "items": [{"t": "Тургенев", "d": "Самый европейский русский писатель.", "c": "Илья Репин. Портрет Тургенева, 1874", "more": ["Иван Тургенев много лет прожил во Франции и дружил с Флобером и Мопассаном. Через него Европа открыла русскую литературу.", "Его «Записки охотника» с правдивыми портретами крестьян, по общему мнению, повлияли на отмену крепостного права в 1861 году. В романах Тургенев показывал разные поколения и типы людей, а его девушек, чистых, сильных и решительных, назвали «тургеневскими»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Turgenev_by_Repin_1879.jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/bf6fdac7af-1000.webp", "w": 1000, "h": 1290, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/17/Turgenev_by_Repin_1879.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Достоевский", "d": "Исследователь человеческой души.", "c": "Василий Перов. Портрет Достоевского, 1872", "more": ["В 1849 году молодого Фёдора Достоевского приговорили к расстрелу за участие в революционном кружке. Его уже вывели на эшафот, и только в последнюю минуту объявили помилование. Он провёл четыре года на каторге в Омске.", "Этот опыт определил всё его творчество. Достоевский пишет о людях в крайних состояниях: преступление, отчаяние, вера. Портрет Перова, по воспоминаниям жены писателя, точно передаёт его сосредоточенность в момент творчества."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/223d7771e2-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/1280px-Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Толстой", "d": "Автор «Войны и мира», философ и учитель.", "c": "Иван Крамской. Портрет Толстого, 1873", "more": ["Граф Лев Толстой воевал на Кавказе и в Севастополе. Свои главные романы он написал в 1860–1870-х годах. Потом пережил духовный кризис, отказался от собственности, ходил в крестьянской одежде, пахал землю.", "Его учение о непротивлении злу насилием повлияло на Махатму Ганди. В 82 года Толстой тайно ушёл из дома и умер на маленькой железнодорожной станции."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Ivan_Nikolayevich_Kramskoi_-_Portrait_of_Leo_Tolstoy,_1873.jpg", "lic": "Public domain", "by": "Ivan Kramskoi", "src": "media/img/b75d683926-1000.webp", "w": 1000, "h": 1235, "remote": "https://upload.wikimedia.org/wikipedia/commons/a/aa/Ivan_Nikolayevich_Kramskoi_-_Portrait_of_Leo_Tolstoy%2C_1873.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Ясная Поляна", "d": "Усадьба, где написаны «Война и мир» и «Анна Каренина».", "c": "Дом Толстого в Ясной Поляне", "more": ["В этой усадьбе под Тулой Толстой родился и прожил большую часть жизни. Здесь он открыл школу для крестьянских детей и сам писал для них учебники.", "Жена Софья Андреевна несколько раз переписывала от руки огромные черновики «Войны и мира». Сейчас в усадьбе музей, и всё в доме осталось так, как было при Толстом. Его могила в лесу без креста и надписи, по его просьбе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Tula_Oblast._Yasnaya_Polyana._Leo_Tolstoy_House_P5131474_2800.jpg", "lic": "CC BY-SA 4.0", "by": "Alexxx1979", "src": "media/img/2e987b3214-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Tula_Oblast._Yasnaya_Polyana._Leo_Tolstoy_House_P5131474_2800.jpg/1280px-Tula_Oblast._Yasnaya_Polyana._Leo_Tolstoy_House_P5131474_2800.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "l8", "title": "Чехов и Серебряный век", "period": "1880 — 1920-е", "intro": [], "traits": ["Чехов: подтекст, «краткость — сестра таланта»", "Символизм: Блок, Брюсов, Бальмонт", "Акмеизм: Гумилёв, Ахматова, Мандельштам", "Футуризм: Маяковский, Хлебников", "Цветаева, Есенин, Пастернак"], "works": [{"t": "Палата № 6", "a": "Антон Чехов", "y": "1892", "ws": "Палата № 6 (Чехов)", "q": "", "d": "Врач провинциальной больницы спорит с пациентом о страдании и сам оказывается в палате для душевнобольных. Ленин, прочитав, сказал, что почувствовал себя запертым в палате.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Антон Чехов был врачом и опубликовал повесть в 1892 году. Действие происходит в провинциальной больнице, где царит грязь и равнодушие.", "Доктор Андрей Ефимович Рагин считает, что страдание неизбежно и бороться с ним бессмысленно, поэтому ничего не меняет. Он начинает ходить в палату для душевнобольных, чтобы спорить с умным пациентом Громовым. Окружающие решают, что доктор сам сошёл с ума, и запирают его в той же палате.", "Там Рагин впервые испытывает побои сторожа и понимает, что его философия была удобным оправданием бездействия. Повесть так потрясала читателей, что они чувствовали себя запертыми в этой палате вместе с героем."]}, {"t": "Вишнёвый сад", "a": "Антон Чехов", "y": "1903", "ws": "Вишнёвый сад (Чехов)", "q": "Вся Россия наш сад.", "d": "Имение продают за долги, сад вырубают. Чехов называл пьесу комедией, а МХТ поставил её как драму.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Чехов написал последнюю пьесу в 1903 году, уже тяжело больным. Помещица Любовь Андреевна Раневская возвращается из Парижа в своё имение со знаменитым вишнёвым садом. Имение заложено, и его продадут за долги.", "Купец Лопахин, сын бывшего крепостного этой семьи, предлагает выход: вырубить сад и сдать землю дачникам. Но Раневская и её брат не могут на это решиться и ничего не делают. На торгах имение покупает сам Лопахин.", "В финале все уезжают, слышен стук топора по деревьям, а в забитом доме забыли старого слугу Фирса. Чехов называл пьесу комедией. Это прощание со старой дворянской Россией, и в ней одновременно смешно и грустно."]}, {"t": "Незнакомка", "a": "Александр Блок", "y": "1906", "ws": "Незнакомка (Блок)", "q": "По вечерам над ресторанами\nГорячий воздух дик и глух…", "d": "Символизм: в пошлом загородном кабаке поэту является прекрасная Незнакомка — мечта или видение?", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Блок написал стихотворение в 1906 году. Действие происходит в загородном ресторане в пригороде Петербурга, где пыль, пьяные крики и скука.", "И вдруг каждый вечер у окна появляется загадочная женщина «в шелка затянутый стан», в шляпе с траурными перьями. Поэт не знает, реальна она или это видение. В ней соединяются пошлый мир кабака и мечта о прекрасном.", "Это классический символизм: обычная сцена становится намёком на что-то большее и таинственное. Последняя строчка «In vino veritas» значит «истина в вине»."]}, {"t": "Двенадцать", "a": "Александр Блок", "y": "1918", "ws": "Двенадцать (Блок)", "q": "Черный вечер.\nБелый снег.\nВетер, ветер!", "d": "Поэма о революционном Петрограде: двенадцать красногвардейцев идут сквозь метель, а впереди — неожиданно — Христос.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Блок написал поэму в январе 1918 года, через два месяца после Октябрьской революции. Двенадцать красногвардейцев идут патрулём по ночному Петрограду сквозь метель.", "Поэма построена как музыка улицы: частушки, лозунги, марш, обрывки разговоров. Один из патрульных в ревности убивает свою возлюбленную Катьку. Патруль идёт дальше, разрушая и угрожая.", "А в последних строках впереди отряда неожиданно появляется Иисус Христос с красным флагом. Что это значит, спорят до сих пор. Поэму не приняли ни красные, ни белые. Блок говорил, что сам не до конца понимает финал."]}, {"t": "Мне нравится, что вы больны не мной…", "a": "Марина Цветаева", "y": "1915", "ws": "Мне нравится, что Вы больны не мной (Цветаева)", "q": "Мне нравится, что вы больны не мной,\nМне нравится, что я больна не вами…", "d": "Нежное и ироничное стихотворение, ставшее песней в фильме «Ирония судьбы».", "story": ["Цветаева написала стихотворение в 1915 году. Долгое время думали, что оно обращено к поэту Мандельштаму. Сестра Цветаевой рассказала, что адресат Маврикий Минц, который позже стал её мужем.", "Героиня радуется, что они не влюблены друг в друга: можно быть свободной, «смешной, распущенной и не играть словами». Но к концу становится понятно, что за этой лёгкостью есть грусть. Последние строки: «за то, что вы больны, увы, не мной».", "В 1975 году Алла Пугачёва спела песню на эти стихи в фильме Эльдара Рязанова «Ирония судьбы», и их узнала вся страна."]}, {"t": "Письмо матери", "a": "Сергей Есенин", "y": "1924", "ws": "Письмо матери (Есенин)", "q": "Ты жива еще, моя старушка?\nЖив и я. Привет тебе, привет!", "d": "Исповедь блудного сына. Простые слова, песенная интонация — фирменный голос Есенина.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sergey_Yesenin_2.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/8d42bf61f2-360.webp", "w": 1000, "h": 1332, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Sergey_Yesenin_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Есенин написал стихотворение в 1924 году, когда жил в Москве и почти не бывал дома. Это письмо стареющей матери в деревню.", "Сын знает, что мать тревожится о нём и выходит на дорогу «в старомодном ветхом шушуне». Он обещает вернуться, когда «расцветёт по-весеннему наш низкий дом», но признаётся, что жизнь его надломлена и в прошлое вернуться нельзя.", "Простые слова, песенная интонация, искренность. На эти стихи написана песня, и это одно из самых известных стихотворений Есенина."]}], "quiz": [{"q": "Кому принадлежат слова «Краткость — сестра таланта»?", "o": ["Толстому", "Чехову", "Гоголю", "Блоку"], "a": 1, "e": "Из письма Чехова брату Александру, 1889."}, {"q": "Блок — представитель какого направления?", "o": ["Акмеизма", "Символизма", "Футуризма", "Реализма"], "a": 1, "e": "Главный поэт русского символизма."}, {"q": "Кто из поэтов — футурист?", "o": ["Есенин", "Маяковский", "Гумилёв", "Цветаева"], "a": 1, "e": "Маяковский и Хлебников — лидеры русского футуризма."}, {"q": "Что происходит в «Вишнёвом саде»?", "o": ["Свадьба", "Имение с садом продают за долги", "Дуэль", "Революция"], "a": 1, "e": "Сад покупает Лопахин, сын бывшего крепостного."}], "why": ["На рубеже XIX и XX веков русская литература пережила новый расцвет, его называют Серебряным веком. Чехов изменил театр и рассказ, а поэты придумали десятки новых способов писать стихи. Многие из этих поэтов пережили революцию, эмиграцию и репрессии, и их стихи это ещё и история страны."], "groups": [{"h": "Новый театр", "p": "Чехов писал пьесы, где «ничего не происходит», а смысл скрыт между словами.", "items": [{"t": "МХТ и «Чайка»", "d": "Спектакль, который спас пьесу Чехова.", "c": "«Чайка» в Московском Художественном театре, 1898", "more": ["В 1896 году «Чайка» Чехова провалилась в Петербурге: зрители смеялись в драматических местах, актёры не понимали пьесу. Чехов поклялся больше не писать для театра.", "Через два года её поставили Константин Станиславский и Владимир Немирович-Данченко в только что открытом Художественном театре. Актёры играли тихо и естественно, будто в жизни, без пафоса. Спектакль имел огромный успех, и чайка стала эмблемой театра, она до сих пор на его занавесе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Moscow_Art_Theatre_production_of_Anton_Chekhov%27s_The_Seagull_1898.jpg", "lic": "Public domain", "by": "Moscow Art Theatre", "src": "media/img/431cd70e7a-1000.webp", "w": 1000, "h": 687, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3f/Moscow_Art_Theatre_production_of_Anton_Chekhov%27s_The_Seagull_1898.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Серебряный век поэзии", "p": "Поэты объединялись в течения: символисты, акмеисты, футуристы, и спорили, какой должна быть поэзия.", "items": [{"t": "«Бродячая собака»", "d": "Подвал, где собирались поэты.", "c": "Подвал кабаре «Бродячая собака» в Петербурге", "more": ["В 1911 году в подвале дома на Михайловской площади открылось артистическое кафе «Бродячая собака». Здесь по ночам читали стихи Ахматова, Гумилёв, Маяковский, Мандельштам, выступали актёры и музыканты.", "Стены расписали художники. Гостей, не связанных с искусством, называли «фармацевтами», и они платили за вход больше. Кафе закрыли в 1915 году, а в 2001-м возродили на том же месте."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Stray_Dog_Cafe_basement_in_St._Petersburg.JPG", "lic": "Public domain", "by": "spaniel", "src": "media/img/62adef698b-1000.webp", "w": 1000, "h": 750, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Stray_Dog_Cafe_basement_in_St._Petersburg.JPG/1280px-Stray_Dog_Cafe_basement_in_St._Petersburg.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Блок", "d": "Главный поэт символизма.", "c": "Александр Блок", "more": ["Символисты верили, что за обычным миром скрыт другой, таинственный, и поэзия может на него намекнуть. Александр Блок начинал со стихов о Прекрасной Даме, неземном идеале. Прототипом была его невеста Любовь Менделеева, дочь великого химика.", "Позже его стихи стали тревожными: город, ночь, предчувствие катастрофы. Блок принял революцию, написал поэму «Двенадцать», а через три года, разочарованный и больной, умер в 40 лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander-Blok-stihi-o-prekrashoj-dame.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/bc22444cbc-1000.webp", "w": 1000, "h": 1421, "remote": "https://upload.wikimedia.org/wikipedia/commons/e/ee/Alexander-Blok-stihi-o-prekrashoj-dame.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Цветаева", "d": "Поэт с самым узнаваемым голосом.", "c": "Марина Цветаева в Коктебеле, 1911", "more": ["Марина Цветаева выпустила первую книгу стихов в 18 лет. Летом 1911 года в Коктебеле в Крыму у поэта Волошина она встретила Сергея Эфрона и вскоре вышла за него замуж.", "Её стихи узнают по резкому ритму, множеству тире и восклицаний, страстной интонации. После революции она семнадцать лет жила в эмиграции в бедности, вернулась в СССР в 1939 году, а в 1941-м в эвакуации покончила с собой."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Marina_Tsvetaeva_by_Max_Voloshin_1911.jpeg", "lic": "Public domain", "by": "Max Voloshin", "src": "media/img/b6edb8d791-1000.webp", "w": 1000, "h": 1408, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/60/Marina_Tsvetaeva_by_Max_Voloshin_1911.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Есенин", "d": "Поэт деревни и Москвы.", "c": "Сергей Есенин, Москва, 1922", "more": ["Сергей Есенин родился в рязанской деревне Константиново и пришёл в литературу «крестьянским поэтом». В стихах у него поля, берёзы, лошади, мать, простые слова и песенные интонации.", "Потом была шумная жизнь в Москве, скандалы, брак с американской танцовщицей Айседорой Дункан, поездки по Европе и Америке. Есенин умер в 1925 году в ленинградской гостинице «Англетер» в 30 лет. Его стихи до сих пор поют как песни."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Esenin_Moscow_1922.jpg", "lic": "Public domain", "by": "UnknownUnknown", "src": "media/img/f499abbf95-1000.webp", "w": 1000, "h": 1332, "remote": "https://upload.wikimedia.org/wikipedia/commons/a/a1/Esenin_Moscow_1922.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}]};
